/* ---------- Amériques : régions et îles encore peu servies ---------- */
const D57 = [
{ id:'poutine-rapee', c:'na', lat:46.098, lon:-64.798, base:6, prep:90, cook:180, diff:3, tags:['pork','slow','festive'],
  art:{v:'bowl',bg:'#2c3440',plate:'#f4f0e6',style:'stew',food:['#e8dcc0','#f4f0e6','#8f5a3a','#c9a878'],garnish:'#7fae6a'},
  n:{fr:'Poutine râpée',en:'Poutine râpée'},
  p:{fr:'Bouctouche, Nouveau-Brunswick, Canada',en:'Bouctouche, New Brunswick, Canada'},
  d:{fr:"Une boule de pomme de terre râpée farcie de porc salé, bouillie trois heures. Elle n'a rien à voir avec la poutine du Québec ; en Acadie, c'est le plat de Noël, et râper vingt livres de patates est une affaire de famille.",
     en:"A ball of grated potato stuffed with salt pork, boiled for three hours. Nothing to do with Quebec poutine; in Acadia it is the Christmas dish, and grating twenty pounds of potatoes is a family affair."},
  i:[['potato',3,'kg'],['salted_pork',500,'g'],['onion',2,'pc'],['coarse_salt',2,'tbsp'],['brown_sugar',3,'tbsp'],['butter',60,'g'],['pepper',null,'']],
  s:{fr:["Râpez les deux tiers des pommes de terre très finement et pressez-les dans un linge jusqu'à ce qu'il ne coule plus rien.","Recueillez l'eau de pressage et laissez décanter : l'amidon tombe au fond, on jette l'eau claire et l'on garde l'amidon.","Faites cuire le tiers restant, écrasez-le, et mêlez-le à la râpure pressée et à l'amidon récupéré.","Formez des boules autour d'un cube de porc salé et d'oignon, en refermant bien : une fuite et la boule se défait.","Pochez 3 heures à l'eau frémissante salée, sans jamais bouillir fort. Servez avec beurre, cassonade ou mélasse."],
     en:["Grate two thirds of the potatoes very finely and press them in a cloth until nothing more runs out.","Collect the pressing liquid and let it settle: the starch falls to the bottom; discard the clear water and keep the starch.","Boil the remaining third, mash it, and mix it with the pressed gratings and the recovered starch.","Shape balls around a cube of salt pork and onion, sealing them well: one leak and the ball falls apart.","Poach for 3 hours in barely simmering salted water, never at a hard boil. Serve with butter, brown sugar or molasses."]} },

{ id:'bannock-des-prairies', c:'na', lat:52.130, lon:-106.671, base:6, prep:15, cook:20, diff:1, tags:['bread','fry','comfort'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'flat',food:['#e0b45a','#c9924a','#f2dfa8','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Bannock',en:'Bannock'},
  p:{fr:'Saskatoon, Saskatchewan, Canada',en:'Saskatoon, Saskatchewan, Canada'},
  d:{fr:"Un pain plat sans levure cuit à la poêle ou sur un bâton au-dessus du feu. Les Premières Nations l'ont adopté au XIXe siècle avec la farine des postes de traite ; il est devenu un symbole ambigu, à la fois nourriture et mémoire.",
     en:"A flat unleavened bread cooked in a pan or on a stick over the fire. First Nations adopted it in the 19th century with trading-post flour; it has become an ambiguous symbol, both food and memory."},
  i:[['flour',500,'g'],['baking_powder',3,'tsp'],['lard',80,'g'],['warm_water',300,'ml'],['saskatoon_berries',200,'g'],['maple_syrup',100,'ml'],['frying_oil',300,'ml'],['salt',null,'']],
  s:{fr:["Mêlez la farine, la levure et le sel, puis sablez le saindoux du bout des doigts.","Versez l'eau tiède d'un coup et rassemblez la pâte en quelques gestes : trop pétrie, elle devient élastique et dure.","Incorporez les baies de saskatoon sans les écraser, si vous en avez.","Aplatissez la pâte à 2 cm et faites-la cuire à la poêle dans un fond de graisse, 8 minutes par face à feu moyen.","Elle est prête quand elle sonne creux. Servez chaude, rompue à la main, avec du sirop d'érable."],
     en:["Mix the flour, baking powder and salt, then rub in the lard with your fingertips.","Pour in the warm water all at once and bring the dough together in a few movements: overworked, it turns elastic and hard.","Fold in the saskatoon berries without crushing them, if you have them.","Flatten the dough to 2 cm and cook it in a pan in a little fat, 8 minutes a side over medium heat.","It is ready when it sounds hollow. Serve hot, broken by hand, with maple syrup."]} },

{ id:'hangtown-fry', c:'na', lat:38.729, lon:-120.799, base:4, prep:20, cook:15, diff:2, tags:['sea','breakfast','fry'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ecd8',style:'flat',food:['#e8c46a','#c9924a','#f0e8d0','#8f5a3a'],garnish:'#7fae6a'},
  n:{fr:'Hangtown fry',en:'Hangtown fry'},
  p:{fr:'Placerville, Californie, États-Unis',en:'Placerville, California, United States'},
  d:{fr:"Une omelette d'huîtres panées et de bacon, née en 1849 dans les camps de chercheurs d'or. Un mineur enrichi aurait demandé le plat le plus cher de la carte : les huîtres venaient de San Francisco à dos de mule, les œufs coûtaient une fortune.",
     en:"An omelette of fried oysters and bacon, born in 1849 in the gold camps. A newly rich miner is said to have asked for the most expensive dish on the menu: oysters came by mule from San Francisco, and eggs cost a fortune."},
  i:[['oysters',12,'pc'],['egg',8,'pc'],['smoked_bacon',200,'g'],['breadcrumbs',100,'g'],['flour',60,'g'],['butter',60,'g'],['heavy_cream',60,'ml'],['spring_onion',4,'pc'],['parsley',3,'tbsp'],['lemon',1,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Ouvrez les huîtres et épongez-les soigneusement : une huître mouillée refuse la panure.","Farinez-les, passez-les à l'œuf battu puis à la chapelure, et faites-les frire 90 secondes par face au beurre.","Faites griller le bacon jusqu'à ce qu'il croustille, et gardez la graisse dans la poêle.","Battez les œufs restants avec la crème, sans les faire mousser, et versez-les sur la graisse chaude.","Disposez huîtres et bacon dessus, laissez prendre 4 minutes à feu doux, et servez au citron."],
     en:["Shuck the oysters and pat them thoroughly dry: a wet oyster refuses the crumb.","Flour them, dip in beaten egg then breadcrumbs, and fry 90 seconds a side in butter.","Grill the bacon until crisp, and keep the fat in the pan.","Beat the remaining eggs with the cream, without aerating them, and pour them onto the hot fat.","Arrange the oysters and bacon over the top, let it set for 4 minutes over low heat, and serve with lemon."]} },

{ id:'green-chile-stew', c:'na', lat:35.084, lon:-106.651, base:6, prep:35, cook:90, diff:1, tags:['pork','spicy','comfort'],
  art:{v:'bowl',bg:'#28331f',plate:'#f4ecd8',style:'stew',food:['#4f8f4a','#7fae5a','#8f5a3a','#f0e8d0'],garnish:'#6fbf8f'},
  n:{fr:'Ragoût au chile vert',en:'Green chile stew'},
  p:{fr:'Albuquerque, Nouveau-Mexique, États-Unis',en:'Albuquerque, New Mexico, United States'},
  d:{fr:"Un ragoût de porc aux piments verts de Hatch grillés, épais et vert. Chaque automne, le Nouveau-Mexique grille ses chiles dans des tambours rotatifs sur les parkings : l'odeur annonce la saison mieux qu'un calendrier.",
     en:"A pork stew with roasted Hatch green chiles, thick and green. Every autumn New Mexico roasts its chiles in rotating drums in car parks: the smell announces the season better than a calendar."},
  i:[['pork_shoulder',1,'kg'],['hatch_green_chiles',800,'g'],['onion',3,'pc'],['garlic',8,'clove'],['potato',600,'g'],['ripe_tomato',300,'g'],['cumin',1,'tbsp'],['oregano',1,'tbsp'],['chicken_broth',1,'l'],['flour',40,'g'],['lard',60,'g'],['flour_tortillas',8,'pc'],['salt',null,'']],
  s:{fr:["Grillez les piments verts jusqu'à ce que la peau cloque et noircisse, puis enfermez-les 15 minutes dans un sac.","Pelez-les, épépinez-les et hachez-les grossièrement : ils doivent rester en morceaux visibles.","Faites saisir le porc en cubes dans le saindoux, singez de farine et laissez-la blondir.","Ajoutez l'oignon, l'ail, le cumin et l'origan, puis le bouillon, et laissez mijoter 45 minutes.","Ajoutez les piments, la tomate et les pommes de terre pour 30 minutes. Servez avec des tortillas de blé."],
     en:["Roast the green chiles until the skins blister and blacken, then shut them in a bag for 15 minutes.","Peel, seed and chop them roughly: they should stay in visible pieces.","Sear the cubed pork in lard, dust with flour and let it turn golden.","Add the onion, garlic, cumin and oregano, then the stock, and simmer for 45 minutes.","Add the chiles, tomato and potatoes for 30 minutes. Serve with flour tortillas."]} },

{ id:'frogmore-stew', c:'na', lat:32.377, lon:-80.669, base:8, prep:25, cook:35, diff:1, tags:['sea','festive','fast'],
  art:{v:'board',bg:'#33251c',plate:'#f2e6c8',style:'fish',food:['#c9402c','#e8c46a','#f0a878','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Frogmore stew',en:'Frogmore stew'},
  p:{fr:'Beaufort, Caroline du Sud, États-Unis',en:'Beaufort, South Carolina, United States'},
  d:{fr:"Crevettes, saucisse fumée, maïs et pommes de terre bouillis ensemble et versés sur une table couverte de papier journal. On mange debout, sans assiette ni couvert, et l'on jette les carapaces au centre.",
     en:"Shrimp, smoked sausage, corn and potatoes boiled together and tipped onto a table covered in newspaper. You eat standing, without plate or fork, and throw the shells into the middle."},
  i:[['shrimp',1.5,'kg'],['smoked_sausage',800,'g'],['corn_cobs',8,'pc'],['baby_potatoes',1.5,'kg'],['old_bay_seasoning',6,'tbsp'],['lemon',4,'pc'],['onion',3,'pc'],['garlic',1,'pc'],['butter',150,'g'],['salt',null,'']],
  s:{fr:["Portez une très grande marmite d'eau à ébullition avec l'assaisonnement, les citrons coupés et l'ail entier.","Le bouillon doit être franchement trop salé et trop épicé : les ingrédients l'absorberont.","Ajoutez les pommes de terre et laissez 12 minutes, puis la saucisse en tronçons pour 5 minutes.","Ajoutez le maïs en tronçons pour 5 minutes, puis les crevettes entières pour 3 minutes seulement.","Égouttez d'un coup et versez la marmite au centre de la table. Beurre fondu et citron à volonté."],
     en:["Bring a very large pot of water to the boil with the seasoning, cut lemons and whole garlic.","The broth should taste frankly too salty and too spiced: the ingredients will absorb it.","Add the potatoes for 12 minutes, then the sausage in lengths for 5 minutes.","Add the corn in lengths for 5 minutes, then the whole shrimp for 3 minutes only.","Drain in one movement and tip the pot into the middle of the table. Melted butter and lemon to taste."]} },

{ id:'kalua-pig', c:'na', lat:21.307, lon:-157.858, base:12, prep:90, cook:420, diff:3, tags:['pork','slow','festive'],
  art:{v:'board',bg:'#2b2419',plate:'#f0e4c8',style:'grill',food:['#8f5a3a','#c9754a','#e8dcb8','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Kālua puaʻa',en:'Kālua pig'},
  p:{fr:'Hilo, Hawaï, États-Unis',en:'Hilo, Hawaii, United States'},
  d:{fr:"Un porc entier cuit sept heures dans un imu, four de terre tapissé de pierres de lave et de feuilles de bananier. Le sel de mer rouge d'Hawaï est le seul assaisonnement ; la fumée fait le reste.",
     en:"A whole pig cooked seven hours in an imu, an earth oven lined with lava stones and banana leaves. Hawaiian red sea salt is the only seasoning; the smoke does the rest."},
  i:[['pork_shoulder',5,'kg'],['hawaiian_salt',5,'tbsp'],['banana_leaf',20,'pc'],['ti_leaves',20,'pc'],['liquid_smoke',2,'tbsp'],['sweet_potato',2,'kg'],['cabbage',1,'pc']],
  s:{fr:["Creusez une fosse et chauffez-y des pierres de lave sur un feu de bois dur pendant trois heures.","Entaillez le porc profondément et frottez-le de sel rouge, en insistant dans les entailles.","Glissez des pierres brûlantes dans la cavité de l'animal : il cuit alors de l'intérieur comme de l'extérieur.","Enveloppez-le de feuilles de ti puis de bananier, posez-le sur les pierres et recouvrez de terre humide.","Laissez 7 heures sans ouvrir. La chair s'effiloche à la fourchette ; on la mélange à un peu de chou étuvé."],
     en:["Dig a pit and heat lava stones in it on a hardwood fire for three hours.","Score the pork deeply and rub it with red salt, working into the cuts.","Slip hot stones into the cavity: the animal then cooks from within as well as without.","Wrap it in ti leaves then banana leaves, set it on the stones and cover with damp earth.","Leave for 7 hours without opening. The flesh shreds at a fork; toss it with a little steamed cabbage."]} },

{ id:'burgoo-kentucky', c:'na', lat:38.041, lon:-84.504, base:12, prep:45, cook:300, diff:2, tags:['beef','slow','festive'],
  art:{v:'pot',bg:'#33291f',plate:'#f0e4c8',style:'stew',food:['#8f5a3a','#c9754a','#e0913a','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Burgoo',en:'Burgoo'},
  p:{fr:'Lexington, Kentucky, États-Unis',en:'Lexington, Kentucky, United States'},
  d:{fr:"Un ragoût de plusieurs viandes et de tous les légumes, mijoté une demi-journée dans un chaudron. On le prépare pour les courses de chevaux et les réunions politiques ; la règle veut que la cuillère y tienne debout.",
     en:"A stew of several meats and every vegetable, simmered half a day in a cauldron. It is made for horse races and political rallies; the rule is that the spoon must stand up in it."},
  i:[['beef_chuck',1,'kg'],['pork_shoulder',700,'g'],['chicken',1,'kg'],['lamb_shoulder',500,'g'],['potato',800,'g'],['corn_kernels',400,'g'],['lima_beans',300,'g'],['okra',300,'g'],['ripe_tomato',800,'g'],['onion',4,'pc'],['cabbage',400,'g'],['worcestershire',3,'tbsp'],['bourbon',80,'ml'],['cayenne',1,'tsp'],['beef_stock',2,'l'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites cuire les viandes ensemble 2 heures dans le fond de bœuf, jusqu'à ce qu'elles se détachent de l'os.","Retirez-les, désossez-les et effilochez-les à la main ; remettez la chair dans le bouillon.","Ajoutez tomate, oignon et pommes de terre, et laissez mijoter 1 heure en remuant régulièrement.","Ajoutez maïs, haricots de Lima, gombos et chou, et poursuivez 2 heures à feu très doux.","Remuez souvent le fond : à ce stade, le burgoo attache en un instant. Finissez au worcestershire et au bourbon."],
     en:["Cook the meats together for 2 hours in the beef stock, until they leave the bone.","Lift them out, bone them and shred them by hand; return the meat to the broth.","Add the tomato, onion and potatoes, and simmer for 1 hour, stirring regularly.","Add the corn, lima beans, okra and cabbage, and continue for 2 hours over very low heat.","Stir the bottom often: at this stage burgoo catches in an instant. Finish with Worcestershire and bourbon."]} },

{ id:'haluski-pittsburgh', c:'na', lat:40.441, lon:-79.996, base:6, prep:90, cook:30, diff:2, tags:['veg','comfort','cheese'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ecd8',style:'pastry',food:['#e0b45a','#f0e8d0','#c9924a','#e8dcc0'],garnish:'#7fae6a'},
  n:{fr:'Halušky de Pittsburgh',en:'Pittsburgh haluski'},
  p:{fr:'Pittsburgh, Pennsylvanie, États-Unis',en:'Pittsburgh, Pennsylvania, United States'},
  d:{fr:"Des nouilles au chou fondu et au beurre, plat des ouvriers slovaques des aciéries. Le chou doit cuire quarante minutes jusqu'à devenir sucré et brun : pressé, il reste un légume et rate son effet.",
     en:"Noodles with butter-melted cabbage, the dish of Slovak steelworkers. The cabbage must cook forty minutes until sweet and brown: rushed, it stays a vegetable and misses the point."},
  i:[['egg_noodles',500,'g'],['cabbage',1.2,'kg'],['onion',3,'pc'],['butter',200,'g'],['smoked_bacon',200,'g'],['caraway',1,'tsp'],['sour_cream',200,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Émincez le chou très finement, salez-le et laissez-le dégorger 30 minutes, puis pressez-le.","Faites rissoler le lard, retirez-le, et faites fondre l'oignon dans la graisse rendue et le beurre.","Ajoutez le chou et laissez-le cuire 40 minutes à feu moyen, en remuant de temps en temps.","Il doit passer du blanc au brun doré et devenir franchement sucré : c'est le seul moment qui compte.","Mêlez-y les nouilles cuites, le carvi et le lard, poivrez généreusement, et servez avec de la crème aigre."],
     en:["Slice the cabbage very finely, salt it and let it drain for 30 minutes, then squeeze it.","Fry the bacon, lift it out, and melt the onion in the rendered fat and butter.","Add the cabbage and cook it for 40 minutes over medium heat, stirring now and then.","It should go from white to golden brown and turn frankly sweet: that is the only moment that matters.","Toss in the cooked noodles, caraway and bacon, season generously with pepper, and serve with soured cream."]} },

{ id:'rice-and-beans-belize', c:'na', lat:17.498, lon:-88.196, base:6, prep:30, cook:75, diff:2, tags:['sea','rice','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ecd8',style:'rice',food:['#6f4a5a','#f0e8d0','#e0913a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Rice and beans du Belize',en:'Belizean rice and beans'},
  p:{fr:'Belize City, Belize',en:'Belize City, Belize'},
  d:{fr:"Du riz cuit dans le lait de coco avec des haricots rouges, servi avec du poulet mijoté au recado. On distingue le rice and beans, cuits ensemble, du beans and rice, cuits séparément : ce n'est pas la même chose.",
     en:"Rice cooked in coconut milk with red beans, served with chicken stewed in recado. Belize distinguishes rice and beans, cooked together, from beans and rice, cooked apart: they are not the same dish."},
  i:[['long_grain_rice',500,'g'],['red_kidney_beans',300,'g'],['coconut_milk',600,'ml'],['chicken',1.4,'kg'],['recado_rojo',3,'tbsp'],['onion',3,'pc'],['garlic',8,'clove'],['thyme',4,'sprig'],['habanero',1,'pc'],['white_wine_vinegar',3,'tbsp'],['brown_sugar',2,'tbsp'],['peanut_oil',80,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites tremper les haricots une nuit, puis cuisez-les 1 heure avec l'ail, le thym et le piment entier.","Faites mariner le poulet au recado rojo, au vinaigre et à l'ail pendant 3 heures.","Faites caraméliser le sucre roux dans l'huile jusqu'à ce qu'il fume, et jetez-y le poulet : il prend une couleur d'acajou.","Mouillez à peine et laissez mijoter 45 minutes à couvert.","Versez le riz dans les haricots avec le lait de coco — deux volumes de liquide pour un de riz — et cuisez 25 minutes à couvert."],
     en:["Soak the beans overnight, then cook them for 1 hour with the garlic, thyme and whole chilli.","Marinate the chicken in recado rojo, vinegar and garlic for 3 hours.","Caramelise the brown sugar in the oil until it smokes, and drop in the chicken: it takes a mahogany colour.","Barely moisten and simmer covered for 45 minutes.","Pour the rice into the beans with the coconut milk — two parts liquid to one of rice — and cook covered for 25 minutes."]} },

{ id:'nacatamal', c:'na', lat:12.115, lon:-86.236, base:8, prep:180, cook:300, diff:3, tags:['pork','slow','festive'],
  art:{v:'leaf',bg:'#33291f',plate:'#f4ecd8',style:'cake',food:['#e8c46a','#8f5a3a','#c9402c','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Nacatamal',en:'Nacatamal'},
  p:{fr:'Managua, Nicaragua',en:'Managua, Nicaragua'},
  d:{fr:"Un très gros tamal de maïs farci de porc, de riz, de pomme de terre et d'olive, cuit cinq heures. On le mange le dimanche matin au petit-déjeuner, avec du café et du pain : un seul suffit largement pour deux.",
     en:"A very large maize tamal filled with pork, rice, potato and olive, cooked five hours. Eaten on Sunday morning at breakfast, with coffee and bread: one is ample for two."},
  i:[['corn_masa',1.5,'kg'],['lard',300,'g'],['pork_shoulder',1,'kg'],['sour_orange_juice',200,'ml'],['achiote_paste',3,'tbsp'],['potato',600,'g'],['long_grain_rice',200,'g'],['onion',3,'pc'],['ripe_tomato',400,'g'],['green_olives',100,'g'],['prunes',100,'g'],['mint',1,'bunch'],['banana_leaf',16,'pc'],['garlic',10,'clove'],['salt',null,'']],
  s:{fr:["Faites mariner le porc 12 heures dans l'orange amère, l'ail et le rocou.","Travaillez la masa avec le saindoux fondu et un peu de bouillon, longuement, jusqu'à ce qu'une boulette flotte dans l'eau.","Assouplissez les feuilles de bananier à la flamme et disposez-les en croix, sur deux épaisseurs.","Étalez une grosse louche de masa, puis le porc, le riz cru, la pomme de terre en rondelles, l'olive, le pruneau et la menthe.","Repliez en gros paquet carré, ficelez, et cuisez 5 heures à la vapeur. On l'ouvre sur l'assiette, jamais avant."],
     en:["Marinate the pork for 12 hours in sour orange, garlic and annatto.","Work the masa with melted lard and a little broth, at length, until a small ball floats in water.","Soften the banana leaves over a flame and lay them crosswise, two thicknesses deep.","Spread a large ladle of masa, then the pork, raw rice, sliced potato, olive, prune and mint.","Fold into a large square parcel, tie it, and steam for 5 hours. It is opened on the plate, never before."]} },

{ id:'sancocho-de-gallina-panama', c:'na', lat:8.983, lon:-79.517, base:6, prep:25, cook:90, diff:1, tags:['poultry','soup','comfort'],
  art:{v:'bowl',bg:'#33301f',plate:'#f4ecd8',style:'soup',food:['#e8c46a','#f0e8d0','#7fae5a','#e0b45a'],garnish:'#6fbf8f'},
  n:{fr:'Sancocho de gallina',en:'Sancocho de gallina'},
  p:{fr:'Chitré, Herrera, Panama',en:'Chitré, Herrera, Panama'},
  d:{fr:"Un bouillon de poule à l'igname et au culantro, mangé brûlant même par grande chaleur. À Panama, on le sert au petit matin après une nuit de fête, et l'on jure qu'il remet un homme d'aplomb.",
     en:"A hen broth with yam and culantro, drunk scalding even in great heat. In Panama it is served at daybreak after a night out, and it is sworn to set a man right."},
  i:[['hen',1.8,'kg'],['yam',800,'g'],['culantro',2,'bunch'],['onion',2,'pc'],['garlic',8,'clove'],['oregano',1,'tbsp'],['corn_cobs',3,'pc'],['long_grain_rice',400,'g'],['lime',3,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites mariner la poule découpée dans l'ail pilé, l'origan et le citron vert pendant une heure.","Mettez-la dans trois litres d'eau froide et portez lentement à frémissement, en écumant sans relâche.","Laissez cuire 1 heure : une poule de ferme demande ce temps, un poulet d'élevage bien moins.","Ajoutez l'igname en gros morceaux et le maïs, et poursuivez 30 minutes.","Ajoutez le culantro en fin de cuisson seulement, entier, et retirez-le avant de servir. Riz blanc à part."],
     en:["Marinate the jointed hen in pounded garlic, oregano and lime for an hour.","Put it in three litres of cold water and bring slowly to a simmer, skimming relentlessly.","Cook for 1 hour: a farm hen needs that long, a battery chicken far less.","Add the yam in large pieces and the corn, and continue for 30 minutes.","Add the culantro only at the end, whole, and lift it out before serving. White rice alongside."]} },

{ id:'gallo-en-chicha', c:'na', lat:13.699, lon:-89.191, base:8, prep:40, cook:180, diff:2, tags:['poultry','slow','festive'],
  art:{v:'pot',bg:'#33251c',plate:'#f4ecd8',style:'stew',food:['#8f5a3a','#c9754a','#e0913a','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Gallo en chicha',en:'Gallo en chicha'},
  p:{fr:'Suchitoto, Salvador',en:'Suchitoto, El Salvador'},
  d:{fr:"Un coq mijoté dans la chicha, la bière de maïs fermentée, avec des fruits secs et de la panela. Il se prépare pour la fête patronale ; la chicha demande huit jours de fermentation, on ne s'y prend pas la veille.",
     en:"A cockerel stewed in chicha, fermented maize beer, with dried fruit and panela. It is made for the patron saint's day; the chicha needs eight days to ferment, so nobody starts the day before."},
  i:[['hen',2,'kg'],['chicha_de_maiz',1,'l'],['panela',200,'g'],['prunes',150,'g'],['raisins',100,'g'],['onion',3,'pc'],['ripe_tomato',500,'g'],['garlic',8,'clove'],['bay_leaf',3,'pc'],['cinnamon',2,'pc'],['cloves',6,'pc'],['relajo_spices',2,'tbsp'],['peanut_oil',80,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites mariner le coq découpé 12 heures dans la chicha avec l'ail, le laurier et les épices.","Égouttez-le en gardant la marinade, épongez-le et faites-le colorer dans l'huile.","Grillez à sec les épices du relajo et moulez-les : c'est ce mélange salvadorien qui donne le parfum du plat.","Ajoutez oignon, tomate, marinade, panela et fruits secs, et laissez mijoter 2 h 30 à couvert.","La sauce doit devenir sombre et sirupeuse, franchement sucrée-acide. Servez avec du riz et du pain."],
     en:["Marinate the jointed cockerel for 12 hours in the chicha with garlic, bay and spices.","Drain it keeping the marinade, pat it dry and colour it in the oil.","Dry-toast the relajo spices and grind them: this Salvadoran blend is what perfumes the dish.","Add onion, tomato, marinade, panela and dried fruit, and simmer covered for 2½ hours.","The sauce should turn dark and syrupy, frankly sweet-sour. Serve with rice and bread."]} },

{ id:'run-down', c:'na', lat:18.011, lon:-76.798, base:4, prep:30, cook:50, diff:2, tags:['sea','comfort','spicy'],
  art:{v:'pot',bg:'#33251c',plate:'#f4ecd8',style:'stew',food:['#e8c46a','#f0e8d0','#c9402c','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Run down',en:'Run down'},
  p:{fr:'Port Antonio, Jamaïque',en:'Port Antonio, Jamaica'},
  d:{fr:"Du poisson mijoté dans du lait de coco réduit jusqu'à ce que l'huile se sépare. Le nom dit le procédé : on fait « courir » le lait de coco jusqu'à ce qu'il tombe en custard, avant même de mettre le poisson.",
     en:"Fish stewed in coconut milk reduced until the oil separates. The name describes the method: the coconut milk is 'run down' until it breaks into custard, before the fish even goes in."},
  i:[['mackerel',800,'g'],['coconut_milk',800,'ml'],['onion',2,'pc'],['ripe_tomato',400,'g'],['scotch_bonnet',1,'pc'],['thyme',5,'sprig'],['spring_onion',5,'pc'],['garlic',6,'clove'],['allspice',8,'pc'],['green_plantain',3,'pc'],['lime',3,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites bouillir le lait de coco à découvert 25 minutes en remuant, jusqu'à ce qu'il épaississe et que l'huile perle : c'est le run down.","N'ajoutez rien avant cette étape : mis trop tôt, les aromates empêchent le lait de se séparer.","Ajoutez l'oignon, l'ail, l'oignon vert, le thym et le piment de la Jamaïque écrasé.","Ajoutez la tomate et le piment scotch bonnet entier — non fendu — et laissez 10 minutes.","Glissez le poisson en tronçons et laissez pocher 12 minutes sans remuer. Servez avec du plantain vert bouilli."],
     en:["Boil the coconut milk uncovered for 25 minutes, stirring, until it thickens and the oil beads: that is the run down.","Add nothing before this step: put in too early, aromatics stop the milk separating.","Add the onion, garlic, spring onion, thyme and crushed allspice.","Add the tomato and the whole scotch bonnet — unsplit — and give it 10 minutes.","Slide in the fish in lengths and poach for 12 minutes without stirring. Serve with boiled green plantain."]} },

{ id:'conch-fritters', c:'na', lat:25.079, lon:-77.338, base:6, prep:35, cook:20, diff:2, tags:['sea','fry','street'],
  art:{v:'board',bg:'#26384a',plate:'#f4ead4',style:'pastry',food:['#e0b45a','#c9924a','#f2dfa8','#c9402c'],garnish:'#7fae6a'},
  n:{fr:'Beignets de lambi',en:'Conch fritters'},
  p:{fr:'Nassau, Bahamas',en:'Nassau, Bahamas'},
  d:{fr:"Des beignets de lambi haché, servis avec une sauce rose au citron. Le lambi se bat au maillet avant d'être haché : sans cela, il reste caoutchouteux quelle que soit la cuisson.",
     en:"Fritters of chopped conch, served with a pink lime sauce. The conch is beaten with a mallet before chopping: without that it stays rubbery whatever the cooking."},
  i:[['conch',600,'g'],['flour',300,'g'],['baking_powder',2,'tsp'],['egg',2,'pc'],['whole_milk',200,'ml'],['red_pepper',1,'pc'],['green_pepper',1,'pc'],['onion',2,'pc'],['celery',3,'stalk'],['goat_pepper',2,'pc'],['lime',3,'pc'],['mayonnaise',150,'g'],['ketchup',3,'tbsp'],['frying_oil',1,'l'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Battez le lambi au maillet jusqu'à l'attendrir, puis hachez-le au couteau en petits morceaux.","Faites-le mariner 20 minutes au citron vert : l'acide continue le travail du maillet.","Mêlez la farine, la levure, les œufs et le lait en une pâte épaisse, plus dense qu'une pâte à crêpes.","Incorporez le lambi égoutté, les légumes en tout petits dés et le piment.","Déposez par cuillerées dans l'huile à 175 °C et frisez 4 minutes en retournant. Servez avec mayonnaise, ketchup et citron."],
     en:["Beat the conch with a mallet to tenderise it, then chop it finely by knife.","Marinate it for 20 minutes in lime: the acid continues what the mallet began.","Mix the flour, baking powder, eggs and milk into a thick batter, denser than a pancake batter.","Fold in the drained conch, the finely diced vegetables and the chilli.","Drop spoonfuls into oil at 175°C and fry for 4 minutes, turning. Serve with mayonnaise, ketchup and lime."]} },

{ id:'fungee-and-pepperpot', c:'na', lat:17.118, lon:-61.845, base:4, prep:25, cook:40, diff:2, tags:['sea','comfort','sunday'],
  art:{v:'plate',bg:'#33301f',plate:'#f4ecd8',style:'stew',food:['#e8c46a','#f0e8d0','#8f5a3a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Fungee et pepperpot',en:'Fungee and pepperpot'},
  p:{fr:'Saint John’s, Antigua-et-Barbuda',en:'St. John’s, Antigua and Barbuda'},
  d:{fr:"Une polenta de maïs au gombo accompagnée d'un ragoût d'épinards et de viandes salées. Le plat national d'Antigua se mange le mercredi, jour où les écoles servaient historiquement le pepperpot.",
     en:"A maize polenta with okra alongside a stew of greens and salted meats. Antigua's national dish is eaten on Wednesdays, the day schools historically served pepperpot."},
  i:[['corn_flour',300,'g'],['spinach',600,'g'],['salted_pork',400,'g'],['smoked_pork_ribs',300,'g'],['eggplant',300,'g'],['pumpkin',400,'g'],['okra',200,'g'],['onion',2,'pc'],['thyme',4,'sprig'],['garlic',6,'clove'],['scotch_bonnet',1,'pc'],['butter',60,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites dessaler les viandes 8 heures, blanchissez-les, puis cuisez-les 1 heure dans l'eau claire.","Ajoutez la courge, l'aubergine et les gombos, et laissez 25 minutes : les légumes doivent se défaire et lier le ragoût.","Ajoutez les épinards et le piment entier pour les 10 dernières minutes.","Pour le fungee, cuisez les gombos émincés dans l'eau salée, retirez-les, et versez la farine de maïs en pluie.","Travaillez 20 minutes au bâton plat, remettez les gombos, beurrez, et moulez en dôme dans un bol mouillé."],
     en:["Soak the salted meats for 8 hours, blanch them, then cook them for 1 hour in clean water.","Add the squash, aubergine and okra, and give them 25 minutes: the vegetables should collapse and thicken the stew.","Add the spinach and the whole chilli for the last 10 minutes.","For the fungee, cook the sliced okra in salted water, lift it out, and rain in the maize flour.","Work it for 20 minutes with a flat stick, return the okra, beat in butter, and mould it in a wetted bowl."]} },

{ id:'callaloo-chicken-dominique', c:'na', lat:15.301, lon:-61.388, base:4, prep:30, cook:60, diff:2, tags:['poultry','comfort','slow'],
  art:{v:'pot',bg:'#33291f',plate:'#f4ecd8',style:'stew',food:['#e0b45a','#8f5a3a','#7fae5a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Poulet au callaloo',en:'Callaloo chicken'},
  p:{fr:'Roseau, Dominique',en:'Roseau, Dominica'},
  d:{fr:"Du poulet mijoté dans une purée de feuilles de dachine au lait de coco, épaisse et vert sombre. La feuille de dachine gratte la gorge si elle n'est pas assez cuite : quarante minutes est un minimum, pas une suggestion.",
     en:"Chicken stewed in a purée of dasheen leaves with coconut milk, thick and dark green. The dasheen leaf scratches the throat if undercooked: forty minutes is a minimum, not a suggestion."},
  i:[['chicken',1.4,'kg'],['callaloo',800,'g'],['coconut_milk',600,'ml'],['onion',3,'pc'],['garlic',8,'clove'],['thyme',5,'sprig'],['spring_onion',5,'pc'],['scotch_bonnet',1,'pc'],['okra',200,'g'],['lime',2,'pc'],['coconut_oil',80,'ml'],['long_grain_rice',400,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Lavez le poulet au citron vert selon l'usage caribéen, puis faites-le mariner à l'ail, au thym et à l'oignon vert.","Retirez les côtes des feuilles de dachine et hachez-les grossièrement : la côte reste dure et irritante.","Faites colorer le poulet dans l'huile de coco, puis ajoutez l'oignon et l'ail.","Ajoutez les feuilles, les gombos et un demi-litre d'eau, couvrez et laissez cuire 40 minutes.","Versez le lait de coco, écrasez les feuilles au fouet pour lier, et laissez 15 minutes sans bouillir. Servez avec du riz."],
     en:["Wash the chicken with lime as Caribbean custom requires, then marinate it in garlic, thyme and spring onion.","Strip the ribs from the dasheen leaves and chop them roughly: the rib stays tough and irritant.","Colour the chicken in coconut oil, then add the onion and garlic.","Add the leaves, okra and half a litre of water, cover and cook for 40 minutes.","Pour in the coconut milk, break down the leaves with a whisk to thicken, and give it 15 minutes without boiling. Serve with rice."]} },

{ id:'pepperpot-guyana', c:'sa', lat:6.802, lon:-58.155, base:8, prep:40, cook:240, diff:2, tags:['beef','slow','festive'],
  art:{v:'pot',bg:'#1e1a14',plate:'#f0e4c8',style:'stew',food:['#2a2018','#4a3a2a','#8f5a3a','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Pepperpot',en:'Pepperpot'},
  p:{fr:'Georgetown, Guyana',en:'Georgetown, Guyana'},
  d:{fr:"Un ragoût noir au cassareep, sirop de manioc amer qui conserve la viande sans réfrigération. Certains pepperpots familiaux se réchauffent depuis des générations : le cassareep est un antiseptique naturel, et le plat ne tourne pas.",
     en:"A black stew with cassareep, the bitter cassava syrup that preserves meat without refrigeration. Some family pepperpots have been reheated for generations: cassareep is a natural antiseptic, and the dish does not spoil."},
  i:[['beef_chuck',1.5,'kg'],['oxtail',800,'g'],['pork_trotters',600,'g'],['cassareep',300,'ml'],['cinnamon',3,'pc'],['cloves',10,'pc'],['brown_sugar',3,'tbsp'],['wiri_wiri_pepper',4,'pc'],['orange_zest',1,'pc'],['thyme',5,'sprig'],['onion',2,'pc'],['plait_bread',1,'pc'],['salt',null,'']],
  s:{fr:["Blanchissez toutes les viandes 15 minutes et jetez cette eau : le pepperpot doit rester net malgré sa couleur.","Remettez-les dans la marmite avec le cassareep, la cannelle, les clous et le zeste d'orange.","Mouillez d'eau à hauteur seulement : le cassareep ne doit pas être dilué, il fait la sauce.","Laissez mijoter 3 à 4 heures à feu très doux, jusqu'à ce que la viande se détache et que la sauce nappe.","Ajoutez les piments wiri wiri entiers en fin de cuisson. Servez avec du pain natté ; réchauffez chaque jour."],
     en:["Blanch all the meats for 15 minutes and discard that water: pepperpot must stay clean despite its colour.","Return them to the pot with the cassareep, cinnamon, cloves and orange peel.","Add water only to the level of the meat: cassareep must not be diluted, it is the sauce.","Simmer for 3 to 4 hours over very low heat, until the meat falls away and the sauce coats.","Add the whole wiri wiri peppers at the end. Serve with plait bread; reheat every day."]} },

{ id:'bouillon-d-awara', c:'sa', lat:4.933, lon:-52.330, base:6, prep:40, cook:90, diff:2, tags:['poultry','spicy','comfort'],
  art:{v:'pot',bg:'#33251c',plate:'#f4ecd8',style:'stew',food:['#e0913a','#c9402c','#f0e8d0','#8f5a3a'],garnish:'#7fae6a'},
  n:{fr:'Bouillon d’awara',en:'Awara broth'},
  p:{fr:'Cayenne, Guyane',en:'Cayenne, French Guiana'},
  d:{fr:"Un ragoût de pâte d'awara, de viandes fumées et de poisson, préparé à Pâques. Une croyance guyanaise dit que qui en mange reviendra en Guyane : il demande deux jours de cuisson et rassemble toute la famille.",
     en:"A stew of awara palm paste, smoked meats and fish, made at Easter. Guianese belief holds that whoever eats it will return to Guiana: it takes two days and gathers the whole family."},
  i:[['awara_paste',1,'kg'],['smoked_chicken',600,'g'],['smoked_fish',400,'g'],['shrimp',400,'g'],['pork_belly',400,'g'],['cabbage',400,'g'],['green_beans',300,'g'],['eggplant',300,'g'],['cucumber',2,'pc'],['garlic',10,'clove'],['scotch_bonnet',3,'pc'],['long_grain_rice',500,'g'],['salt',null,'']],
  s:{fr:["Délayez la pâte d'awara dans deux litres d'eau et faites-la réduire 4 heures à découvert, en remuant régulièrement.","Elle doit passer de l'orange vif au brun sombre et réduire de moitié : c'est cette longue cuisson qui fait tout.","Faites dessaler et blanchir les viandes fumées, et cuisez-les à part 40 minutes.","Ajoutez-les à la pâte avec le poisson fumé et les légumes, par ordre de fermeté.","Laissez mijoter 1 heure de plus, ajoutez les crevettes en fin de cuisson, et servez avec du riz blanc."],
     en:["Slake the awara paste in two litres of water and reduce it for 4 hours uncovered, stirring regularly.","It should go from bright orange to dark brown and halve in volume: that long cooking is everything.","Soak and blanch the smoked meats, and cook them separately for 40 minutes.","Add them to the paste with the smoked fish and the vegetables, in order of firmness.","Simmer for another hour, add the prawns at the end, and serve with white rice."]} },

{ id:'pato-no-tucupi', c:'sa', lat:-1.455, lon:-48.503, base:6, prep:40, cook:150, diff:3, tags:['poultry','slow','festive'],
  art:{v:'plate',bg:'#33301f',plate:'#f4ecd8',style:'stew',food:['#e8c46a','#8f5a3a','#4f8f4a','#f0e8d0'],garnish:'#6fbf8f'},
  n:{fr:'Pato no tucupi',en:'Pato no tucupi'},
  p:{fr:'Belém, Pará, Brésil',en:'Belém, Pará, Brazil'},
  d:{fr:"Du canard poché dans le tucupi avec du jambu, servi au Círio de Nazaré. Le canard est d'abord rôti puis bouilli : ce double traitement, contraire à toute logique culinaire européenne, est ce qui fait le plat.",
     en:"Duck poached in tucupi with jambu, served at the Círio de Nazaré. The duck is first roasted then boiled: that double treatment, contrary to all European culinary logic, is what makes the dish."},
  i:[['whole_duck',2,'kg'],['tucupi',2,'l'],['jambu_leaves',400,'g'],['garlic',12,'clove'],['chicory',1,'bunch'],['bird_eye_chili',4,'pc'],['lime',3,'pc'],['long_grain_rice',500,'g'],['cassava_flour',200,'g'],['basil',1,'bunch'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Frottez le canard d'ail pilé, de citron vert et de sel, et laissez-le 12 heures au frais.","Rôtissez-le 1 heure à 200 °C, jusqu'à ce que la peau soit bien colorée et que la graisse ait fondu.","Faites bouillir le tucupi 2 heures avec l'ail, la chicorée et le basilic, à découvert.","Découpez le canard rôti et plongez les morceaux dans le tucupi bouillant pour 40 minutes.","Blanchissez le jambu et ajoutez-le en fin de cuisson. Servez avec du riz et de la farofa."],
     en:["Rub the duck with pounded garlic, lime and salt, and leave it 12 hours in the cold.","Roast it for 1 hour at 200°C, until the skin is well coloured and the fat has rendered.","Boil the tucupi for 2 hours with the garlic, chicory and basil, uncovered.","Joint the roast duck and lower the pieces into the boiling tucupi for 40 minutes.","Blanch the jambu and add it at the end. Serve with rice and farofa."]} },

{ id:'guatita', c:'sa', lat:-2.203, lon:-79.897, base:6, prep:30, cook:150, diff:2, tags:['beef','slow','comfort'],
  art:{v:'bowl',bg:'#33291f',plate:'#f4ecd8',style:'stew',food:['#e8c46a','#f0e8d0','#c9924a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Guatita',en:'Guatita'},
  p:{fr:'Guayaquil, Équateur',en:'Guayaquil, Ecuador'},
  d:{fr:"Des tripes mijotées dans une sauce d'arachide et de pomme de terre, jaune de rocou. Le nom veut dire « petit ventre » ; c'est le plat de rue de Guayaquil, servi à toute heure et jamais à la carte des restaurants chics.",
     en:"Tripe stewed in a peanut and potato sauce, yellow with annatto. The name means 'little belly'; it is Guayaquil's street dish, served at all hours and never on a smart restaurant menu."},
  i:[['beef_tripe',1,'kg'],['peanut_butter',250,'g'],['potato',800,'g'],['whole_milk',400,'ml'],['onion',3,'pc'],['garlic',8,'clove'],['achiote_paste',2,'tbsp'],['cumin',1,'tbsp'],['ripe_tomato',300,'g'],['cilantro',1,'bunch'],['long_grain_rice',500,'g'],['ripe_plantain',3,'pc'],['avocado',2,'pc'],['salt',null,'']],
  s:{fr:["Frottez les tripes au gros sel et au citron, rincez-les longuement, puis blanchissez-les 15 minutes.","Cuisez-les 2 heures à l'eau frémissante jusqu'à ce qu'une fourchette y entre sans effort, et taillez-les en lanières.","Faites un refrito d'oignon, d'ail, de tomate, de cumin et de rocou, 20 minutes.","Délayez l'arachide dans le lait tiède et versez-la dans le refrito, avec les pommes de terre en cubes.","Ajoutez les tripes et laissez mijoter 30 minutes : les pommes de terre se défont et lient la sauce. Coriandre à la fin."],
     en:["Scrub the tripe with coarse salt and lemon, rinse it at length, then blanch it for 15 minutes.","Cook it for 2 hours at a bare simmer until a fork slides in easily, and cut it into strips.","Make a refrito of onion, garlic, tomato, cumin and annatto for 20 minutes.","Slake the peanut butter in warm milk and stir it into the refrito, with the diced potatoes.","Add the tripe and simmer for 30 minutes: the potatoes collapse and thicken the sauce. Coriander at the end."]} },

{ id:'chairo-paceno', c:'sa', lat:-16.500, lon:-68.150, base:6, prep:40, cook:150, diff:2, tags:['beef','soup','slow'],
  art:{v:'bowl',bg:'#33291f',plate:'#f4ecd8',style:'soup',food:['#e8dcb8','#8f5a3a','#f0e8d0','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Chairo paceño',en:'Chairo paceño'},
  p:{fr:'La Paz, Bolivie',en:'La Paz, Bolivia'},
  d:{fr:"Une soupe de chuño, la pomme de terre déshydratée par le gel andin, avec agneau et blé. Le chuño se fabrique en laissant geler les tubercules la nuit et en les piétinant le jour : la technique a mille ans.",
     en:"A soup of chuño, potato freeze-dried by Andean nights, with lamb and wheat. Chuño is made by letting tubers freeze overnight and treading them by day: the technique is a thousand years old."},
  i:[['chuno',300,'g'],['lamb_shoulder',600,'g'],['beef_chuck',400,'g'],['wheat_berries',200,'g'],['potato',500,'g'],['carrot',3,'pc'],['peas',200,'g'],['onion',3,'pc'],['aji_amarillo_paste',3,'tbsp'],['garlic',8,'clove'],['oregano',1,'tbsp'],['huacatay',2,'tbsp'],['cumin',1,'tbsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites tremper le chuño une nuit, puis frottez-le entre les mains pour ôter les peaux et rincez-le à plusieurs eaux.","Faites tremper le blé une nuit également, et cuisez-le 1 heure à part : il ne s'attendrit pas au même rythme.","Faites cuire les viandes 1 heure dans trois litres d'eau avec l'oignon et l'ail.","Faites un refrito d'ají amarillo, de cumin et d'origan, et versez-le dans le bouillon.","Ajoutez le chuño écrasé grossièrement, le blé et les légumes, et laissez 45 minutes. Huacatay hors du feu."],
     en:["Soak the chuño overnight, then rub it between your hands to remove the skins and rinse it in several changes of water.","Soak the wheat overnight too, and cook it separately for 1 hour: it does not soften at the same rate.","Cook the meats for 1 hour in three litres of water with the onion and garlic.","Make a refrito of ají amarillo, cumin and oregano, and stir it into the broth.","Add the roughly crushed chuño, the wheat and the vegetables, and give them 45 minutes. Huacatay off the heat."]} },

{ id:'silpancho', c:'sa', lat:-17.394, lon:-66.157, base:4, prep:30, cook:25, diff:2, tags:['beef','fry','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ecd8',style:'grill',food:['#e0b45a','#c9924a','#c9402c','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Silpancho',en:'Silpancho'},
  p:{fr:'Cochabamba, Bolivie',en:'Cochabamba, Bolivia'},
  d:{fr:"Une escalope panée aplatie jusqu'à couvrir toute l'assiette, sur un lit de riz et de pommes de terre. Cochabamba juge un silpancho à sa taille : s'il ne déborde pas de l'assiette, il n'est pas assez battu.",
     en:"A breaded steak flattened until it covers the whole plate, over rice and potatoes. Cochabamba judges a silpancho by its size: if it does not overhang the plate, it was not beaten enough."},
  i:[['beef_sirloin',600,'g'],['breadcrumbs',200,'g'],['egg',6,'pc'],['long_grain_rice',400,'g'],['potato',700,'g'],['ripe_tomato',400,'g'],['onion',3,'pc'],['locoto_pepper',2,'pc'],['parsley',3,'tbsp'],['white_wine_vinegar',3,'tbsp'],['frying_oil',300,'ml'],['garlic',4,'clove'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Battez les tranches de bœuf entre deux feuilles jusqu'à obtenir un disque de 3 mm et de 25 cm de diamètre.","Salez, poivrez, et pressez-les fermement dans la chapelure des deux côtés, sans passer par l'œuf : c'est la particularité locale.","Faites cuire le riz et les pommes de terre en rondelles, poêlées jusqu'à dorer.","Faites frire la viande 90 secondes par face dans l'huile bien chaude : plus longtemps, elle sèche.","Dressez riz, pommes de terre, viande, puis deux œufs au plat, et couronnez d'une salade crue de tomate, oignon et locoto."],
     en:["Beat the beef slices between two sheets into a 3 mm disc, 25 cm across.","Season, and press them firmly into the breadcrumbs on both sides, without egg wash: that is the local peculiarity.","Cook the rice, and fry the sliced potatoes until golden.","Fry the meat for 90 seconds a side in very hot oil: any longer and it dries out.","Plate rice, potatoes and meat, then two fried eggs, and crown with a raw salad of tomato, onion and locoto."]} },

{ id:'mbeju', c:'sa', lat:-25.516, lon:-54.617, base:6, prep:20, cook:20, diff:1, tags:['cheese','breakfast','fast'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'flat',food:['#f2dfa8','#e0b45a','#f0e8d0','#c9924a'],garnish:'#7fae6a'},
  n:{fr:'Mbejú',en:'Mbejú'},
  p:{fr:'Ciudad del Este, Paraguay',en:'Ciudad del Este, Paraguay'},
  d:{fr:"Une galette d'amidon de manioc et de fromage cuite à la poêle, sans farine ni levain. Elle ne se pétrit pas : la pâte reste en miettes sèches et se soude à la chaleur, ce qui déroute la première fois.",
     en:"A cake of cassava starch and cheese cooked in a pan, without flour or leavening. It is not kneaded: the mixture stays as dry crumbs and welds together in the heat, which disconcerts the first time."},
  i:[['cassava_starch',500,'g'],['queso_paraguay',400,'g'],['lard',150,'g'],['whole_milk',150,'ml'],['egg',2,'pc'],['salt',null,'']],
  s:{fr:["Travaillez le saindoux en pommade avec le sel, puis incorporez le fromage râpé et les œufs.","Ajoutez l'amidon de manioc et sablez du bout des doigts : la pâte doit rester en miettes, jamais former une boule.","Ajoutez le lait cuillère par cuillère, juste assez pour que la miette tienne quand on la presse dans la main.","Versez une couche de 1 cm dans une poêle chaude et pressez à peine avec le dos d'une cuillère.","Laissez souder 8 minutes à feu moyen, retournez d'un coup et cuisez 6 minutes. Servez brûlant."],
     en:["Cream the lard with the salt, then work in the grated cheese and the eggs.","Add the cassava starch and rub it in with your fingertips: the mixture must stay crumbly, never form a ball.","Add the milk a spoonful at a time, just enough that a crumb holds when squeezed in the hand.","Tip a 1 cm layer into a hot pan and press it only lightly with the back of a spoon.","Let it weld for 8 minutes over medium heat, flip it in one movement and cook 6 minutes. Serve scalding."]} },

{ id:'boston-baked-beans', c:'na', lat:42.360, lon:-71.059, base:8, prep:720, cook:420, diff:2, tags:['legume','slow','comfort'],
  art:{v:'pot',bg:'#2b2419',plate:'#f0e4c8',style:'stew',food:['#8f5a3a','#6f4a2a','#e8dcb8','#c9924a'],garnish:'#7fae6a'},
  n:{fr:'Boston baked beans',en:'Boston baked beans'},
  p:{fr:'Boston, Massachusetts, États-Unis',en:'Boston, Massachusetts, United States'},
  d:{fr:"Des haricots blancs cuits sept heures au four dans un pot de grès, à la mélasse et au lard salé. Boston fut surnommée Beantown à cause d'eux : la ville raffinait le sucre des Antilles, et la mélasse, sous-produit sans valeur, coûtait moins cher que le sucre.",
     en:"White beans baked seven hours in a stoneware pot with molasses and salt pork. Boston was nicknamed Beantown because of them: the city refined Caribbean sugar, and molasses, a worthless by-product, cost less than sugar."},
  i:[['white_beans',500,'g'],['salted_pork',150,'g'],['black_treacle',80,'ml'],['brown_sugar',40,'g'],['onion',1,'pc'],['mustard',1,'tsp'],['bay_leaf',2,'pc'],['water',1,'l'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites tremper les haricots une nuit entière, puis pochez-les 40 minutes jusqu'à ce que la peau se fende quand on souffle dessus.","Ne salez jamais l'eau de trempage ni celle de précuisson : le sel durcit la peau et sept heures de four ne la rattraperont pas.","Entaillez le lard salé en croisillons sans traverser la couenne, et enfouissez-le au centre du pot avec l'oignon entier.","Mêlez la mélasse, la cassonade et la moutarde sèche à un litre d'eau chaude, et versez jusqu'à couvrir les haricots d'un centimètre.","Cuisez à couvert 6 heures à 130 °C en complétant l'eau chaude si le niveau descend, puis découvrez la dernière heure pour laisser croûter le dessus."],
     en:["Soak the beans overnight, then simmer them 40 minutes until the skins split when you blow on them.","Never salt the soaking or parboiling water: salt hardens the skin and seven hours of oven will not undo it.","Score the salt pork in a lattice without cutting through the rind, and bury it in the centre of the pot with the whole onion.","Mix the molasses, brown sugar and dry mustard into a litre of hot water, and pour to cover the beans by a centimetre.","Bake covered 6 hours at 130°C, topping up with hot water if the level drops, then uncover for the last hour to let the top crust."]} },

{ id:'blueberry-pie-du-maine', c:'na', lat:44.715, lon:-67.461, base:8, prep:60, cook:55, diff:2, tags:['sweet','bake','fruit'],
  art:{v:'plate',bg:'#2c3440',plate:'#f4ead4',style:'pastry',food:['#4a4a7a','#e0b45a','#f2dfa8','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Tarte aux myrtilles du Maine',en:'Maine blueberry pie'},
  p:{fr:'Machias, Maine, États-Unis',en:'Machias, Maine, United States'},
  d:{fr:"Une tarte aux myrtilles sauvages, dessert officiel de l'État depuis 2011. Le Maine produit la quasi-totalité des myrtilles sauvages d'Amérique du Nord : elles sont deux fois plus petites que les cultivées, deux fois plus acides, et ne se ramassent qu'au râteau à main.",
     en:"A wild blueberry pie, the state's official dessert since 2011. Maine grows nearly all of North America's wild blueberries: half the size of cultivated ones, twice as sharp, and gathered only with a hand rake."},
  i:[['blueberries',800,'g'],['shortcrust_pastry',600,'g'],['sugar',120,'g'],['cornstarch',30,'g'],['lemon',1,'pc'],['cinnamon',1,'tsp'],['butter',30,'g'],['egg_yolk',1,'pc'],['salt',null,'']],
  s:{fr:["Mêlez les myrtilles au sucre, à la fécule, au zeste et au jus de citron, et laissez macérer 30 minutes pour qu'elles rendent leur jus.","Égouttez ce jus, faites-le réduire de moitié à la casserole et reversez-le sur les fruits : sans cela, la tarte inonde le fond.","Foncez le moule, garnissez en dôme et parsemez de noisettes de beurre.","Couvrez d'un second disque, soudez, dorez et entaillez cinq fentes larges — la vapeur doit sortir vite, une seule cheminée ne suffit pas.","Cuisez 15 minutes à 220 °C puis 40 minutes à 190 °C, jusqu'à ce que le jus bouillonne par les fentes. Laissez refroidir 4 heures avant de couper."],
     en:["Mix the blueberries with the sugar, cornstarch, zest and lemon juice, and macerate 30 minutes so they give up their juice.","Drain that juice, reduce it by half in a pan and pour it back over the fruit: without this the pie floods its base.","Line the tin, fill it in a dome and dot with butter.","Cover with a second disc, seal, glaze and cut five wide vents — the steam must escape fast, one chimney is not enough.","Bake 15 minutes at 220°C then 40 minutes at 190°C, until juice bubbles through the vents. Cool 4 hours before cutting."]} },

{ id:'whoopie-pie', c:'na', lat:44.100, lon:-70.215, base:8, prep:50, cook:12, diff:1, tags:['sweet','bake','comfort'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'cake',food:['#3a2a1a','#f4f0e6','#4f3a2a','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Whoopie pie',en:'Whoopie pie'},
  p:{fr:'Lewiston, Maine, États-Unis',en:'Lewiston, Maine, United States'},
  d:{fr:"Deux dômes de gâteau au cacao enfermant une crème de guimauve, ni tarte ni gâteau. Le Maine, la Pennsylvanie amish et le Massachusetts en revendiquent l'invention ; le nom viendrait du cri des fermiers découvrant le gâteau dans leur boîte-repas.",
     en:"Two cocoa cake domes enclosing a marshmallow cream, neither pie nor cake. Maine, the Pennsylvania Amish and Massachusetts all claim the invention; the name is said to come from the cry of farmers finding one in their lunch pail."},
  i:[['flour',250,'g'],['cocoa_powder',60,'g'],['butter',180,'g'],['brown_sugar',150,'g'],['egg',1,'pc'],['buttermilk',120,'ml'],['baking_soda',1,'tsp'],['marshmallow_fluff',200,'g'],['powdered_sugar',150,'g'],['vanilla',1,'pc'],['salt',null,'']],
  s:{fr:["Crémez 60 g de beurre avec la cassonade, ajoutez l'œuf, puis alternez farine cacaotée et babeurre en trois fois.","Le babeurre acide active le bicarbonate : la pâte gonfle aussitôt et il faut la dresser sans attendre.","Déposez des dômes d'une grosse cuillerée sur la plaque, très espacés — ils s'étalent de moitié en cuisant.","Cuisez 11 minutes à 180 °C : ils doivent rester souples et mats, un whoopie cuit croustille et ce n'est plus lui.","Fouettez le reste du beurre avec le sucre glace, la guimauve et la vanille, garnissez généreusement et pressez sans écraser."],
     en:["Cream 60 g of the butter with the brown sugar, add the egg, then alternate the cocoa flour and buttermilk in three additions.","The sour buttermilk activates the bicarbonate: the batter rises at once and must be piped without delay.","Drop generous spoonfuls onto the tray, well spaced — they spread by half as they bake.","Bake 11 minutes at 180°C: they must stay soft and matt, an overbaked whoopie crisps and is no longer one.","Whisk the remaining butter with the icing sugar, marshmallow and vanilla, fill generously and press without squashing."]} },

{ id:'louis-lunch-hamburger', c:'na', lat:41.308, lon:-72.928, base:4, prep:20, cook:10, diff:1, tags:['beef','street','fast'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'roll',food:['#8f5a3a','#f2dfa8','#e0b45a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Hamburger de Louis’ Lunch',en:'Louis’ Lunch hamburger'},
  p:{fr:'New Haven, Connecticut, États-Unis',en:'New Haven, Connecticut, United States'},
  d:{fr:"Un steak haché cuit debout dans un gril de fonte vertical, servi entre deux tranches de pain de mie grillé. Louis Lassen l'improvisa en 1900 pour un client pressé ; la maison sert toujours dans les mêmes grils de 1898, et refuse catégoriquement le ketchup.",
     en:"A beef patty cooked upright in a vertical cast-iron broiler, served between two slices of toasted white bread. Louis Lassen improvised it in 1900 for a customer in a hurry; the shop still uses the same 1898 broilers, and flatly refuses ketchup."},
  i:[['ground_beef',600,'g'],['white_bread',8,'slice'],['onion',1,'pc'],['ripe_tomato',2,'pc'],['cheddar_cheese',100,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Choisissez un haché à vingt pour cent de gras et ne le travaillez pas : formez les galettes du bout des doigts, sans tasser.","Une viande compressée devient dense à la cuisson ; c'est le seul geste qui distingue un bon hamburger d'un mauvais.","Salez et poivrez uniquement la surface, juste avant de cuire : salé à l'avance, le haché rend son eau et se soude.","Cuisez debout dans un gril vertical, ou à défaut sur une poêle en fonte brûlante, 4 minutes par face sans jamais écraser à la spatule.","Grillez le pain de mie, posez le steak, une lamelle de fromage fondue à la chaleur de la viande, l'oignon et la tomate. Rien d'autre — surtout pas de ketchup."],
     en:["Choose mince at twenty per cent fat and do not work it: shape the patties with your fingertips, without packing.","Compressed meat turns dense as it cooks; it is the one gesture that separates a good burger from a bad one.","Salt and pepper the surface only, just before cooking: salted ahead, mince weeps and welds together.","Cook upright in a vertical broiler, or failing that on a scalding cast-iron pan, 4 minutes a side, never pressing with a spatula.","Toast the bread, set the patty on it, a slice of cheese melted by the meat's heat, onion and tomato. Nothing else — certainly not ketchup."]} },

{ id:'toll-house-cookies', c:'na', lat:42.081, lon:-70.936, base:12, prep:40, cook:12, diff:1, tags:['sweet','bake','comfort'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#c9924a','#3a2a1a','#e0b45a','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Cookies Toll House',en:'Toll House cookies'},
  p:{fr:'Whitman, Massachusetts, États-Unis',en:'Whitman, Massachusetts, United States'},
  d:{fr:"Les premiers cookies aux pépites de chocolat, inventés en 1938 par Ruth Wakefield à l'auberge Toll House. À court de noix, elle coupa une tablette Nestlé en morceaux en pensant qu'ils fondraient : ils ne fondirent pas, et elle vendit sa recette à Nestlé contre un dollar et un stock de chocolat à vie.",
     en:"The first chocolate chip cookies, invented in 1938 by Ruth Wakefield at the Toll House Inn. Out of nuts, she chopped up a Nestlé bar expecting it to melt: it did not, and she sold the recipe to Nestlé for a dollar and a lifetime supply of chocolate."},
  i:[['flour',280,'g'],['butter',170,'g'],['brown_sugar',150,'g'],['sugar',100,'g'],['egg',2,'pc'],['dark_chocolate',200,'g'],['baking_soda',1,'tsp'],['vanilla',1,'pc'],['walnuts',80,'g'],['salt',null,'']],
  s:{fr:["Crémez le beurre mou avec les deux sucres 5 minutes, jusqu'à ce que le mélange pâlisse : c'est cette aération qui donne le bord croustillant.","Ajoutez les œufs un à un puis la vanille, et enfin la farine et le bicarbonate en mélangeant le moins possible.","Concassez le chocolat au couteau plutôt que d'employer des pépites : les éclats irréguliers font des coulées, les pépites restent des billes.","Réfrigérez la pâte 24 heures : la farine s'hydrate, le sucre caramélise mieux, et le cookie garde son épaisseur au four.","Cuisez 11 minutes à 190 °C. Sortez-les quand le centre paraît encore cru — ils finissent de prendre sur la plaque brûlante."],
     en:["Cream the softened butter with both sugars for 5 minutes, until it pales: that aeration gives the crisp edge.","Add the eggs one at a time then the vanilla, and finally the flour and bicarbonate, mixing as little as possible.","Chop the chocolate with a knife rather than using chips: irregular shards make seams, chips stay beads.","Chill the dough 24 hours: the flour hydrates, the sugar caramelises better, and the cookie keeps its thickness in the oven.","Bake 11 minutes at 190°C. Take them out while the centre still looks raw — they finish setting on the hot tray."]} },

{ id:'fluffernutter', c:'na', lat:42.388, lon:-71.100, base:4, prep:10, cook:0, diff:1, tags:['sweet','fast','street'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'flat',food:['#c9924a','#f4f0e6','#f2dfa8','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Fluffernutter',en:'Fluffernutter'},
  p:{fr:'Somerville, Massachusetts, États-Unis',en:'Somerville, Massachusetts, United States'},
  d:{fr:"Un sandwich au beurre de cacahuète et à la crème de guimauve, sur pain de mie blanc. Le Marshmallow Fluff fut inventé à Somerville en 1917 ; un sénateur du Massachusetts a proposé d'en faire le sandwich officiel de l'État, ce que le parlement discute encore.",
     en:"A peanut butter and marshmallow cream sandwich, on white bread. Marshmallow Fluff was invented in Somerville in 1917; a Massachusetts senator proposed making it the official state sandwich, which the legislature is still debating."},
  i:[['white_bread',8,'slice'],['peanut_butter',120,'g'],['marshmallow_fluff',120,'g'],['butter',20,'g'],['salt',null,'']],
  s:{fr:["Sortez le beurre de cacahuète une demi-heure à l'avance : froid, il déchire la mie au lieu de s'étaler.","Étalez-le sur une tranche en couche épaisse et régulière, jusqu'aux bords.","Étalez la crème de guimauve sur l'autre tranche, jamais sur la même : superposées, elles se mêlent et l'on perd le contraste des deux textures.","Fermez le sandwich sans presser — la guimauve fuit sous la moindre pression.","Coupez en diagonale avec un couteau passé sous l'eau chaude et essuyé. Se mange dans l'heure, avant que la mie ne s'imbibe."],
     en:["Take the peanut butter out half an hour ahead: cold, it tears the crumb instead of spreading.","Spread it on one slice in a thick, even layer, right to the edges.","Spread the marshmallow cream on the other slice, never on the same one: layered together they merge and the contrast of textures is lost.","Close the sandwich without pressing — marshmallow escapes under the least pressure.","Cut on the diagonal with a knife run under hot water and wiped. Eaten within the hour, before the bread goes damp."]} },

{ id:'pancakes-au-sirop-derable', c:'na', lat:44.465, lon:-72.687, base:4, prep:20, cook:20, diff:1, tags:['sweet','breakfast','fast'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'flat',food:['#e0b45a','#8f5a3a','#f2dfa8','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Pancakes au babeurre et sirop d’érable',en:'Buttermilk pancakes with maple syrup'},
  p:{fr:'Stowe, Vermont, États-Unis',en:'Stowe, Vermont, United States'},
  d:{fr:"Des pancakes épais au babeurre, noyés de sirop d'érable du Vermont. Les Abénaquis entaillaient déjà les érables avant l'arrivée des colons ; il faut quarante litres de sève pour un litre de sirop, ce qui explique le prix et interdit les imitations à l'arôme.",
     en:"Thick buttermilk pancakes drowned in Vermont maple syrup. The Abenaki were tapping maples before the settlers arrived; forty litres of sap make one of syrup, which explains the price and rules out flavoured imitations."},
  i:[['flour',250,'g'],['egg',2,'pc'],['buttermilk',400,'ml'],['butter',60,'g'],['baking_soda',1,'tsp'],['baking_powder',1,'tsp'],['sugar',2,'tbsp'],['maple_syrup',200,'ml'],['heavy_cream',100,'ml'],['salt',null,'']],
  s:{fr:["Mêlez les ingrédients secs d'un côté, les liquides de l'autre, puis réunissez en une dizaine de tours seulement.","La pâte doit rester grumeleuse : une pâte lisse a développé son gluten et donne des pancakes élastiques et plats.","Laissez reposer 15 minutes, le temps que le bicarbonate réagisse avec le babeurre et que des bulles apparaissent en surface.","Chauffez une poêle à feu moyen et graissez-la au chiffon beurré. Versez une louche et attendez que les bulles éclatent et que les bords sèchent avant de retourner — une seule fois.","Faites tiédir le sirop d'érable avant de servir : froid, il fige le beurre et glisse au lieu de pénétrer."],
     en:["Mix the dry ingredients on one side, the wet on the other, then combine in ten turns only.","The batter must stay lumpy: a smooth batter has developed its gluten and gives flat, rubbery pancakes.","Rest it 15 minutes, while the bicarbonate reacts with the buttermilk and bubbles rise to the surface.","Heat a pan over medium heat and grease it with a buttered cloth. Pour a ladleful and wait for the bubbles to burst and the edges to dry before turning — once only.","Warm the maple syrup before serving: cold, it sets the butter and slides off instead of soaking in."]} },

{ id:'apple-pie-nouvelle-angleterre', c:'na', lat:44.476, lon:-73.212, base:8, prep:70, cook:60, diff:2, tags:['sweet','bake','fruit'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#e0b45a','#f2dfa8','#c9924a','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Apple pie de Nouvelle-Angleterre',en:'New England apple pie'},
  p:{fr:'Burlington, Vermont, États-Unis',en:'Burlington, Vermont, United States'},
  d:{fr:"Une tarte aux pommes à double croûte, servie tiède avec une tranche de cheddar fort du Vermont. L'association surprend hors de Nouvelle-Angleterre ; un dicton local dit qu'une tarte aux pommes sans fromage est comme un baiser sans étreinte.",
     en:"A double-crust apple pie, served warm with a slice of sharp Vermont cheddar. The pairing startles outside New England; a local saying has it that apple pie without cheese is like a kiss without a squeeze."},
  i:[['apple',1.2,'kg'],['shortcrust_pastry',650,'g'],['sugar',150,'g'],['flour',20,'g'],['cinnamon',1,'tsp'],['nutmeg',0.5,'tsp'],['butter',30,'g'],['lemon',1,'pc'],['cheddar_cheese',200,'g'],['egg_yolk',1,'pc'],['salt',null,'']],
  s:{fr:["Employez deux variétés : une qui tient, une qui se défait. La première donne les morceaux, la seconde la compote qui les lie.","Coupez les pommes en quartiers épais, citronnez-les et mêlez-les au sucre, à la farine et aux épices.","Laissez-les dégorger 45 minutes dans une passoire et faites réduire le jus recueilli en sirop avant de le reverser : c'est ce qui évite le vide sous la croûte.","Garnissez en dôme haut, parsemez de beurre, couvrez, soudez en pinçant et entaillez quatre fentes.","Cuisez 20 minutes à 220 °C puis 40 minutes à 190 °C. Servez tiède, avec du cheddar affiné coupé en tranches épaisses."],
     en:["Use two varieties: one that holds, one that collapses. The first gives the pieces, the second the purée that binds them.","Cut the apples into thick wedges, squeeze lemon over and mix with the sugar, flour and spices.","Let them drain 45 minutes in a colander and reduce the collected juice to a syrup before pouring it back: that is what stops the gap forming under the crust.","Fill in a high dome, dot with butter, cover, seal by pinching and cut four vents.","Bake 20 minutes at 220°C then 40 minutes at 190°C. Serve warm, with aged cheddar cut in thick slices."]} },

{ id:'bagel-lox-schmear', c:'na', lat:40.718, lon:-73.988, base:4, prep:15, cook:0, diff:1, tags:['sea','breakfast','street'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'roll',food:['#e0a8a0','#f4f0e6','#e0b45a','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Bagel au saumon fumé',en:'Bagel with lox and schmear'},
  p:{fr:'Lower East Side, New York, États-Unis',en:'Lower East Side, New York, United States'},
  d:{fr:"Un bagel fendu, tartiné de cream cheese et couvert de saumon salé, d'oignon rouge et de câpres. Le bagel est arrivé de Pologne avec les Juifs ashkénazes vers 1880 ; le lox n'est pas fumé mais saumuré, et le mot vient du yiddish laks, le saumon.",
     en:"A split bagel spread with cream cheese and covered with cured salmon, red onion and capers. The bagel came from Poland with Ashkenazi Jews around 1880; lox is not smoked but brined, and the word comes from Yiddish laks, salmon."},
  i:[['bagels',4,'pc'],['cured_salmon',200,'g'],['cream_cheese',200,'g'],['red_onion',1,'pc'],['capers',2,'tbsp'],['dill',1,'bunch'],['lemon',1,'pc'],['pepper',null,'']],
  s:{fr:["Choisissez un bagel du jour, à croûte luisante : un bagel bouilli avant cuisson a une croûte brillante, un bagel simplement cuit n'en a pas.","Fendez-le et grillez-le uniquement s'il date de la veille — un bagel frais grillé perd son moelleux caractéristique.","Sortez le cream cheese vingt minutes à l'avance et travaillez-le à la spatule pour qu'il devienne lisse.","Étalez-le en couche épaisse, presque autant que la mie : le schmear n'est pas une fine couche, c'est un des deux ingrédients principaux.","Couchez le saumon en plis lâches, ajoutez l'oignon en rondelles très fines, les câpres, l'aneth et du poivre. Refermez et mangez aussitôt."],
     en:["Choose a bagel baked that day, with a glossy crust: a bagel boiled before baking shines, one merely baked does not.","Split it and toast it only if it is a day old — toasting a fresh bagel destroys its characteristic chew.","Take the cream cheese out twenty minutes ahead and work it with a spatula until smooth.","Spread it thickly, almost as thick as the crumb: the schmear is not a thin layer, it is one of the two main ingredients.","Lay the salmon in loose folds, add very thin onion rings, capers, dill and pepper. Close and eat at once."]} },

{ id:'dirty-water-hot-dog', c:'na', lat:40.759, lon:-73.985, base:4, prep:20, cook:15, diff:1, tags:['beef','street','fast'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'roll',food:['#8f5a3a','#e8c46a','#e0b45a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Hot-dog du chariot new-yorkais',en:'New York cart hot dog'},
  p:{fr:'New York, États-Unis',en:'New York, United States'},
  d:{fr:"Une saucisse de bœuf tenue au chaud dans l'eau frémissante d'un chariot, servie avec de la choucroute et une sauce à l'oignon. Les New-Yorkais l'appellent dirty water dog : l'eau du bac n'est jamais renouvelée de la journée, et c'est réputé faire le goût.",
     en:"A beef frankfurter kept hot in the simmering water of a cart, served with sauerkraut and onion sauce. New Yorkers call it a dirty water dog: the water in the tank is never changed all day, and that is reckoned to make the flavour."},
  i:[['beef_sausage',8,'pc'],['hot_dog_buns',8,'pc'],['sauerkraut',200,'g'],['onion',3,'pc'],['tomato_paste',2,'tbsp'],['white_vinegar',2,'tbsp'],['sugar',1,'tbsp'],['cinnamon',1,'pinch'],['mustard',60,'g'],['salt',null,'']],
  s:{fr:["Faites la sauce à l'oignon : oignons émincés fondus 25 minutes, puis concentré de tomate, vinaigre, sucre et une pointe de cannelle, mouillés d'eau.","Laissez-la réduire 20 minutes jusqu'à ce qu'elle nappe : c'est elle qui distingue un hot-dog new-yorkais de tous les autres.","Chauffez de l'eau à 85 °C et laissez-y les saucisses au moins 15 minutes, sans jamais bouillir — l'ébullition fait éclater la peau.","Réchauffez les pains à la vapeur au-dessus du bac, jamais au grille-pain : le pain doit être mou et humide.","Garnissez dans cet ordre : moutarde jaune, saucisse, choucroute pressée, sauce à l'oignon. Se mange debout, dans les deux minutes."],
     en:["Make the onion sauce: sliced onions melted for 25 minutes, then tomato purée, vinegar, sugar and a pinch of cinnamon, let down with water.","Reduce it 20 minutes until it coats: it is what separates a New York hot dog from every other.","Heat water to 85°C and hold the frankfurters in it at least 15 minutes, never boiling — a boil splits the skin.","Warm the buns in the steam above the tank, never in a toaster: the bread must be soft and damp.","Dress in this order: yellow mustard, frankfurter, pressed sauerkraut, onion sauce. Eaten standing, within two minutes."]} },

{ id:'black-and-white-cookie', c:'na', lat:40.777, lon:-73.951, base:10, prep:60, cook:15, diff:2, tags:['sweet','bake','street'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'cake',food:['#f4f0e6','#3a2a1a','#f2dfa8','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Black and white cookie',en:'Black and white cookie'},
  p:{fr:'Yorkville, New York, États-Unis',en:'Yorkville, New York, United States'},
  d:{fr:"Un large biscuit moelleux glacé pour moitié de vanille, pour moitié de chocolat, sur sa face plate. Né vers 1902 dans une boulangerie allemande de Yorkville, il est devenu à New York un emblème de coexistence — et se mange toujours en commençant par le côté noir.",
     en:"A large soft cookie iced half vanilla, half chocolate, on its flat side. Born around 1902 in a German bakery in Yorkville, it became a New York emblem of coexistence — and is always eaten starting from the dark side."},
  i:[['flour',300,'g'],['sugar',150,'g'],['butter',100,'g'],['egg',2,'pc'],['whole_milk',100,'ml'],['powdered_sugar',300,'g'],['cocoa_powder',30,'g'],['vanilla',1,'pc'],['baking_powder',1,'tsp'],['lemon',1,'pc'],['salt',null,'']],
  s:{fr:["Crémez le beurre et le sucre, ajoutez les œufs puis alternez farine et lait : la pâte doit être celle d'un gâteau, pas d'un biscuit.","Déposez de grosses cuillerées très espacées et lissez-les en disques de 10 cm avec le dos d'une cuillère mouillée.","Cuisez 14 minutes à 190 °C jusqu'aux bords à peine dorés, et laissez refroidir complètement à l'envers, face plate en haut.","C'est la face plate qui se glace, jamais la bombée : c'est la règle new-yorkaise et elle ne souffre pas d'exception.","Faites un glaçage épais au sucre glace, à l'eau chaude et au citron ; glacez une moitié en blanc, cacaotez le reste et glacez l'autre, en traçant la frontière à la règle."],
     en:["Cream the butter and sugar, add the eggs then alternate flour and milk: this is a cake batter, not a biscuit dough.","Drop large spoonfuls well apart and smooth them into 10 cm discs with the back of a wet spoon.","Bake 14 minutes at 190°C until the edges barely colour, and cool completely upside down, flat side up.","It is the flat side that is iced, never the domed one: that is the New York rule and it admits no exception.","Make a thick icing of icing sugar, hot water and lemon; ice one half white, add cocoa to the rest and ice the other, drawing the border with a straight edge."]} },

{ id:'pork-roll-taylor-ham', c:'na', lat:40.217, lon:-74.743, base:4, prep:15, cook:15, diff:1, tags:['pork','breakfast','fast'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'roll',food:['#e0a8a0','#e8c46a','#f2dfa8','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Pork roll, œuf et fromage',en:'Pork roll, egg and cheese'},
  p:{fr:'Trenton, New Jersey, États-Unis',en:'Trenton, New Jersey, United States'},
  d:{fr:"Des tranches de charcuterie de porc grillées avec un œuf et du fromage dans un muffin anglais. Le New Jersey se divise sur le nom : Taylor ham au nord, pork roll au sud, et la frontière traverse l'État à la hauteur de Trenton — le débat n'a jamais été tranché.",
     en:"Slices of cured pork griddled with an egg and cheese in an English muffin. New Jersey is split over the name: Taylor ham in the north, pork roll in the south, with the border crossing the state at Trenton — the argument has never been settled."},
  i:[['pork_roll',400,'g'],['egg',4,'pc'],['american_cheese',4,'slice'],['english_muffins',4,'pc'],['butter',30,'g'],['ketchup',40,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Taillez le pork roll en tranches de 6 mm et entaillez chacune de quatre coups de couteau depuis le bord vers le centre.","Ces entailles ne sont pas décoratives : sans elles, la tranche se bombe en cuisant et ne touche plus la plaque que par les bords.","Faites-les griller 3 minutes par face sur une plaque sèche, jusqu'à ce que les bords brunissent et croustillent.","Cuisez les œufs à la plaque dans le gras rendu, jaune ferme ou coulant selon le goût, et posez le fromage dessus pour qu'il fonde à la chaleur.","Grillez le muffin, empilez pork roll, œuf et fromage, et refermez. Ketchup, sel, poivre — la seule combinaison que le New Jersey admette."],
     en:["Cut the pork roll into 6 mm slices and make four cuts in each from the edge toward the centre.","Those cuts are not decorative: without them the slice domes as it cooks and touches the griddle only at the edges.","Griddle them 3 minutes a side on a dry plate, until the edges brown and crisp.","Cook the eggs on the griddle in the rendered fat, yolk firm or runny to taste, and lay the cheese on so it melts in the heat.","Toast the muffin, stack pork roll, egg and cheese, and close. Ketchup, salt, pepper — the only combination New Jersey allows."]} },

{ id:'biscuits-and-gravy', c:'na', lat:38.253, lon:-85.759, base:4, prep:30, cook:30, diff:2, tags:['pork','breakfast','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f4f0e6',style:'other',food:['#f4f0e6','#e8dcb8','#8f5a3a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Biscuits and gravy',en:'Biscuits and gravy'},
  p:{fr:'Louisville, Kentucky, États-Unis',en:'Louisville, Kentucky, United States'},
  d:{fr:"Des scones salés au babeurre noyés d'une sauce blanche à la chair à saucisse. C'est le petit-déjeuner des Appalaches depuis le début du XIXᵉ siècle : deux ingrédients bon marché, la farine et le lait, tenaient un homme jusqu'au soir dans les mines.",
     en:"Savoury buttermilk scones drowned in a white sausage gravy. It has been the Appalachian breakfast since the early 19th century: two cheap ingredients, flour and milk, kept a man going until evening in the mines."},
  i:[['flour',300,'g'],['butter',150,'g'],['buttermilk',250,'ml'],['baking_powder',1,'tbsp'],['pork_sausage',400,'g'],['whole_milk',500,'ml'],['black_peppercorns',1,'tbsp'],['baking_soda',0.5,'tsp'],['salt',null,'']],
  s:{fr:["Congelez le beurre une demi-heure et râpez-le dans la farine : les copeaux glacés fondent au four et créent les feuillets qui font monter le biscuit.","Versez le babeurre froid et rassemblez la pâte en quelques gestes, sans la pétrir — un biscuit travaillé devient un caillou.","Repliez la pâte en trois deux fois, comme un feuilletage, puis découpez à l'emporte-pièce d'un coup net et vertical.","Un emporte-pièce qu'on tourne soude les tranches et le biscuit ne lève plus d'un côté. Cuisez 14 minutes à 220 °C, les biscuits se touchant.","Faites revenir la chair à saucisse émiettée, singez de deux cuillerées de farine, mouillez du lait chaud et poivrez très généreusement : le poivre est le troisième ingrédient de la sauce, pas un assaisonnement."],
     en:["Freeze the butter for half an hour and grate it into the flour: the frozen shreds melt in the oven and create the leaves that lift the biscuit.","Pour in the cold buttermilk and bring the dough together in a few movements, without kneading — a worked biscuit turns to stone.","Fold the dough in three twice, like puff pastry, then cut with a cutter pressed straight down in one clean movement.","A cutter that is twisted seals the layers and the biscuit rises lopsided. Bake 14 minutes at 220°C with the biscuits touching.","Fry the crumbled sausage meat, dust with two spoonfuls of flour, moisten with hot milk and pepper very generously: pepper is the gravy's third ingredient, not a seasoning."]} },

{ id:'pulled-pork-caroline-du-nord', c:'na', lat:35.824, lon:-80.253, base:8, prep:60, cook:600, diff:3, tags:['pork','slow','grill'],
  art:{v:'board',bg:'#2b2419',plate:'#f4ead4',style:'roll',food:['#8f5a3a','#c9754a','#f2dfa8','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Pulled pork de Caroline du Nord',en:'North Carolina pulled pork'},
  p:{fr:'Lexington, Caroline du Nord, États-Unis',en:'Lexington, North Carolina, United States'},
  d:{fr:"Une épaule de porc fumée dix heures puis effilochée, arrosée d'une sauce au vinaigre de cidre. La Caroline du Nord se divise en deux écoles : l'Est fume le cochon entier avec une sauce au vinaigre pur, l'Ouest ne prend que l'épaule et tolère une pointe de tomate.",
     en:"A pork shoulder smoked for ten hours then pulled, dressed with a cider vinegar sauce. North Carolina divides into two schools: the East smokes the whole hog with pure vinegar sauce, the West takes only the shoulder and tolerates a touch of tomato."},
  i:[['pork_shoulder',2,'kg'],['sweet_paprika',2,'tbsp'],['brown_sugar',2,'tbsp'],['cider_vinegar',300,'ml'],['ketchup',3,'tbsp'],['chili_flakes',1,'tbsp'],['bread_roll',8,'pc'],['green_cabbage',400,'g'],['mayonnaise',80,'g'],['black_peppercorns',1,'tbsp'],['salt',null,'']],
  s:{fr:["Frottez l'épaule d'un mélange de sel, de poivre, de paprika et de cassonade, et laissez-la douze heures au froid, à découvert.","Le séchage à l'air découvert forme une pellicule collante à la surface : c'est elle qui retient la fumée, et une viande humide n'en prend aucune.","Fumez à 110 °C au bois de hickory ou de chêne, dix heures, jusqu'à 95 °C à cœur — la température, pas l'horloge, décide.","Vers 70 °C, la température cesse de monter pendant deux heures : c'est le palier, le collagène qui fond. N'augmentez pas le feu, attendez.","Laissez reposer une heure enveloppée, puis effilochez à la main, à deux fourchettes. Arrosez de la sauce au vinaigre et servez en sandwich avec un coleslaw."],
     en:["Rub the shoulder with a mix of salt, pepper, paprika and brown sugar, and leave it twelve hours in the cold, uncovered.","Uncovered drying forms a tacky film on the surface: that film holds the smoke, and wet meat takes none.","Smoke at 110°C over hickory or oak for ten hours, to 95°C at the centre — temperature, not the clock, decides.","Around 70°C the temperature stops rising for two hours: that is the stall, collagen melting. Do not raise the heat, wait.","Rest it an hour wrapped, then pull it by hand with two forks. Dress with the vinegar sauce and serve in a bun with coleslaw."]} },

{ id:'southern-mac-and-cheese', c:'na', lat:33.749, lon:-84.388, base:8, prep:30, cook:45, diff:2, tags:['cheese','bake','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#e8c46a','#e0b45a','#f2dfa8','#c9924a'],garnish:'#7fae6a'},
  n:{fr:'Mac and cheese du Sud',en:'Southern mac and cheese'},
  p:{fr:'Atlanta, Géorgie, États-Unis',en:'Atlanta, Georgia, United States'},
  d:{fr:"Des macaronis liés aux œufs et au lait concentré, gratinés jusqu'à pouvoir se couper en parts. Thomas Jefferson rapporta la recette de France en 1790, mais c'est James Hemings, son cuisinier esclave formé à Paris, qui l'a mise au point en Amérique.",
     en:"Macaroni bound with egg and evaporated milk, baked until it can be cut in squares. Thomas Jefferson brought the recipe back from France in 1790, but it was James Hemings, his enslaved cook trained in Paris, who worked it out in America."},
  i:[['macaroni',400,'g'],['cheddar_cheese',500,'g'],['mozzarella',200,'g'],['evaporated_milk',500,'ml'],['egg',3,'pc'],['butter',60,'g'],['mustard',1,'tsp'],['cayenne',1,'pinch'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Cuisez les macaronis deux minutes de moins que le paquet : ils finiront de cuire au four et boiront l'appareil.","Râpez le fromage vous-même : le fromage pré-râpé est enrobé d'amidon anti-agglomérant, qui rend le gratin granuleux.","Battez les œufs avec le lait concentré, la moutarde et le cayenne — c'est un appareil à flan, pas une béchamel, et c'est ce qui fait qu'on peut le couper.","Alternez pâtes et fromage en trois couches dans un plat beurré, en gardant un tiers du cheddar pour le dessus.","Versez l'appareil, laissez reposer dix minutes qu'il s'infiltre, et cuisez 45 minutes à 180 °C. Laissez tiédir 20 minutes avant de couper."],
     en:["Cook the macaroni two minutes less than the packet says: it finishes in the oven and drinks the custard.","Grate the cheese yourself: pre-grated cheese is coated in anti-caking starch, which makes the bake grainy.","Beat the eggs with the evaporated milk, mustard and cayenne — this is a custard, not a béchamel, and it is what lets you cut it.","Layer pasta and cheese in three tiers in a buttered dish, keeping a third of the cheddar for the top.","Pour over the custard, rest ten minutes so it seeps through, and bake 45 minutes at 180°C. Cool 20 minutes before cutting."]} },

{ id:'fried-green-tomatoes', c:'na', lat:32.081, lon:-81.091, base:4, prep:25, cook:15, diff:1, tags:['veg','fry','comfort'],
  art:{v:'plate',bg:'#28331f',plate:'#f4ecd8',style:'flat',food:['#7fae5a','#e0b45a','#f2dfa8','#f0e8d0'],garnish:'#6fbf8f'},
  n:{fr:'Tomates vertes frites',en:'Fried green tomatoes'},
  p:{fr:'Savannah, Géorgie, États-Unis',en:'Savannah, Georgia, United States'},
  d:{fr:"Des rondelles de tomates non mûres panées à la semoule de maïs et frites, servies avec une rémoulade. La recette apparaît dans des livres du Nord dès 1877 ; le Sud l'a adoptée pendant la Grande Dépression, quand attendre que la tomate mûrisse était un luxe.",
     en:"Slices of unripe tomato crumbed in cornmeal and fried, served with a remoulade. The recipe appears in northern books as early as 1877; the South adopted it during the Depression, when waiting for a tomato to ripen was a luxury."},
  i:[['green_tomatoes',4,'pc'],['flour',100,'g'],['egg',2,'pc'],['cornmeal',150,'g'],['buttermilk',100,'ml'],['sunflower_oil',400,'ml'],['mayonnaise',120,'g'],['sweet_paprika',1,'tsp'],['pickles',3,'pc'],['cayenne',1,'pinch'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Choisissez des tomates franchement vertes et dures, jamais rosissantes : une tomate qui commence à mûrir se défait dans la friture.","Taillez-les en rondelles de 8 mm, salez-les et laissez-les dégorger 20 minutes sur du papier, puis épongez-les.","Farinez, passez au babeurre battu à l'œuf, puis à la semoule de maïs : la semoule seule, sans farine dessous, ne tient pas sur une tomate humide.","Frites 3 minutes par face dans deux centimètres d'huile à 180 °C, sans surcharger la poêle.","Égouttez debout et salez aussitôt. Servez avec une rémoulade de mayonnaise, cornichons hachés, paprika et cayenne."],
     en:["Choose frankly green, hard tomatoes, never blushing: one that has begun to ripen collapses in the fryer.","Cut them into 8 mm rounds, salt them and drain them 20 minutes on paper, then blot them.","Flour, dip in buttermilk beaten with egg, then cornmeal: cornmeal alone, without flour beneath, will not cling to a wet tomato.","Fry 3 minutes a side in two centimetres of oil at 180°C, without crowding the pan.","Drain upright and salt at once. Serve with a remoulade of mayonnaise, chopped gherkin, paprika and cayenne."]} },

{ id:'pimento-cheese', c:'na', lat:33.952, lon:-83.358, base:6, prep:20, cook:0, diff:1, tags:['cheese','fast','fresh'],
  art:{v:'bowl',bg:'#33291f',plate:'#f4ecd8',style:'other',food:['#e8621f','#e8c46a','#f2dfa8','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Pimento cheese',en:'Pimento cheese'},
  p:{fr:'Athens, Géorgie, États-Unis',en:'Athens, Georgia, United States'},
  d:{fr:"Une tartinade de cheddar orange, de poivrons doux et de mayonnaise, appelée le caviar du Sud. Elle naquit à New York vers 1910, de la rencontre du cream cheese de fabrication récente et des piments doux espagnols en conserve, mais le Sud se l'est appropriée sans retour.",
     en:"A spread of orange cheddar, sweet peppers and mayonnaise, called the caviar of the South. It was born in New York around 1910, from newly made cream cheese meeting tinned Spanish sweet peppers, but the South has claimed it beyond recall."},
  i:[['cheddar_cheese',400,'g'],['pimentos',100,'g'],['mayonnaise',80,'g'],['cream_cheese',40,'g'],['cayenne',1,'pinch'],['onion',1,'pc'],['white_bread',8,'slice'],['black_peppercorns',1,'tsp'],['salt',null,'']],
  s:{fr:["Râpez le cheddar au gros trou et non au robot : les copeaux doivent rester distincts, une purée de fromage n'est plus du pimento cheese.","Choisissez un cheddar orange bien affiné : le colorant au rocou ne change pas le goût mais il fait la couleur attendue.","Égouttez les piments doux et hachez-les au couteau, en gardant des morceaux visibles.","Mêlez à la fourchette avec la mayonnaise, le cream cheese, l'oignon râpé, le cayenne et beaucoup de poivre.","Laissez reposer une nuit au réfrigérateur : le fromage absorbe la mayonnaise et la tartinade se raffermit. Sortez-la une heure avant de servir."],
     en:["Grate the cheddar on the coarse holes, not in a processor: the shreds must stay distinct, a cheese purée is no longer pimento cheese.","Choose a well-aged orange cheddar: the annatto colouring changes nothing in the taste but gives the expected colour.","Drain the sweet peppers and chop them by knife, keeping visible pieces.","Mix with a fork with the mayonnaise, cream cheese, grated onion, cayenne and plenty of pepper.","Rest it overnight in the fridge: the cheese absorbs the mayonnaise and the spread firms up. Take it out an hour before serving."]} },

{ id:'skillet-cornbread', c:'na', lat:32.076, lon:-81.098, base:8, prep:20, cook:25, diff:1, tags:['bread','bake','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'flat',food:['#e8c46a','#e0b45a','#f2dfa8','#c9924a'],garnish:'#7fae6a'},
  n:{fr:'Cornbread à la poêle',en:'Skillet cornbread'},
  p:{fr:'Savannah, Géorgie, États-Unis',en:'Savannah, Georgia, United States'},
  d:{fr:"Un pain de maïs cuit dans une poêle de fonte brûlante, à la croûte foncée et craquante. Le Sud n'y met pas de sucre et le dit fermement : un cornbread sucré est du gâteau, et c'est le signe qu'on a affaire à une recette du Nord.",
     en:"A cornbread baked in a scalding cast-iron skillet, with a dark, crackling crust. The South puts no sugar in it and says so firmly: a sweetened cornbread is cake, and a sure sign of a northern recipe."},
  i:[['cornmeal',200,'g'],['flour',100,'g'],['buttermilk',300,'ml'],['egg',2,'pc'],['lard',60,'g'],['baking_soda',1,'tsp'],['baking_powder',1,'tsp'],['salt',null,'']],
  s:{fr:["Mettez la poêle de fonte avec le saindoux au four à 230 °C vingt minutes avant : elle doit être fumante quand la pâte arrive.","C'est le choc de la pâte froide sur la fonte brûlante qui forme la croûte : dans une poêle tiède, on obtient un gâteau pâle et mou.","Mêlez la semoule, la farine, le bicarbonate, la levure et le sel, puis le babeurre et les œufs, en une vingtaine de tours seulement.","Sortez la poêle, faites tourner la graisse fumante pour en enduire les parois, et versez la pâte d'un coup : elle doit grésiller aussitôt.","Enfournez 22 minutes. Démoulez sur une planche et servez tiède, avec du beurre — ou émietté dans un verre de babeurre, comme au Sud."],
     en:["Put the cast-iron skillet with the lard in a 230°C oven twenty minutes ahead: it must be smoking when the batter arrives.","It is the shock of cold batter on scalding iron that forms the crust: in a warm pan you get a pale, soft cake.","Mix the cornmeal, flour, bicarbonate, baking powder and salt, then the buttermilk and eggs, in twenty turns only.","Take out the skillet, swirl the smoking fat up the sides, and pour the batter in at once: it must sizzle immediately.","Bake 22 minutes. Turn out onto a board and serve warm with butter — or crumbled into a glass of buttermilk, as in the South."]} },

{ id:'etouffee-aux-ecrevisses', c:'na', lat:30.274, lon:-91.900, base:4, prep:30, cook:40, diff:2, tags:['sea','stew','comfort'],
  art:{v:'pot',bg:'#33251c',plate:'#f0e4c8',style:'stew',food:['#c9532c','#e0913a','#e8dcb8','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Étouffée aux écrevisses',en:'Crawfish étouffée'},
  p:{fr:'Breaux Bridge, Louisiane, États-Unis',en:'Breaux Bridge, Louisiana, United States'},
  d:{fr:"Des queues d'écrevisses mijotées à couvert dans un roux blond, servies sur du riz. Étouffer, en français d'Acadie, veut dire cuire à couvert dans peu de liquide ; Breaux Bridge se proclame capitale mondiale de l'écrevisse depuis 1959 et lui consacre un festival.",
     en:"Crawfish tails smothered in a blond roux and served over rice. Étouffer, in Acadian French, means to cook covered in little liquid; Breaux Bridge has proclaimed itself the crawfish capital of the world since 1959 and holds a festival for it."},
  i:[['crawfish_tails',600,'g'],['butter',60,'g'],['flour',40,'g'],['onion',1,'pc'],['celery',2,'pc'],['green_pepper',1,'pc'],['garlic',4,'clove'],['fish_broth',250,'ml'],['cayenne',1,'tsp'],['spring_onion',4,'pc'],['parsley',3,'tbsp'],['long_grain_rice',300,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites un roux au beurre et à la farine et cuisez-le jusqu'à la couleur du beurre de cacahuète, en remuant sans arrêt 10 minutes.","Un roux d'étouffée est blond, pas brun : le roux noir appartient au gumbo, et confondre les deux change complètement le plat.","Jetez d'un coup la trinité — oignon, céleri, poivron vert — dans le roux brûlant : le choc arrête la cuisson du roux net.","Ajoutez l'ail, le bouillon et le cayenne, et laissez épaissir 15 minutes à découvert.","Incorporez les queues d'écrevisses et couvrez : elles cuisent en 5 minutes et deviennent caoutchouteuses au-delà de huit. Persillez et servez sur du riz."],
     en:["Make a butter and flour roux and cook it to the colour of peanut butter, stirring without pause for 10 minutes.","An étouffée roux is blond, not brown: the dark roux belongs to gumbo, and confusing the two changes the dish entirely.","Throw in the trinity — onion, celery, green pepper — all at once into the scalding roux: the shock stops the roux cooking dead.","Add the garlic, broth and cayenne, and let it thicken 15 minutes uncovered.","Fold in the crawfish tails and cover: they cook in 5 minutes and turn rubbery beyond eight. Add parsley and serve over rice."]} },

{ id:'muffuletta', c:'na', lat:29.958, lon:-90.063, base:6, prep:1470, cook:0, diff:2, tags:['pork','street','fresh'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'roll',food:['#7fae5a','#e0a8a0','#f2dfa8','#f0e8d0'],garnish:'#6fbf8f'},
  n:{fr:'Muffuletta',en:'Muffuletta'},
  p:{fr:'La Nouvelle-Orléans, Louisiane, États-Unis',en:'New Orleans, Louisiana, United States'},
  d:{fr:"Un pain rond au sésame garni de charcuteries, de provolone et d'une salade d'olives marinées. Salvatore Lupo l'inventa en 1906 pour les débardeurs siciliens du French Market ; il se mange froid et gagne à être pressé plusieurs heures avant d'être coupé.",
     en:"A round sesame loaf filled with cured meats, provolone and a marinated olive salad. Salvatore Lupo invented it in 1906 for the Sicilian dockers of the French Market; it is eaten cold and is better for being pressed for hours before cutting."},
  i:[['sesame_roll',1,'pc'],['bologna',150,'g'],['salami',150,'g'],['ham',150,'g'],['provolone',200,'g'],['green_olives',200,'g'],['black_olives',100,'g'],['giardiniera',150,'g'],['garlic',3,'clove'],['olive_oil',120,'ml'],['oregano',1,'tbsp'],['capers',2,'tbsp'],['pepper',null,'']],
  s:{fr:["Préparez la salade d'olives la veille : olives vertes et noires hachées, giardiniera, ail, câpres, origan, noyés dans l'huile d'olive.","Elle doit macérer vingt-quatre heures au minimum — c'est elle le plat, les charcuteries ne sont qu'un support.","Fendez le pain rond à l'horizontale et creusez légèrement la mie du chapeau pour faire de la place.","Arrosez les deux faces de l'huile de la salade, puis montez : olives, provolone, charcuteries, provolone, olives.","Refermez, enveloppez serré et pressez sous un poids 3 heures au moins. Coupez en quatre au moment de servir, jamais avant."],
     en:["Make the olive salad the day before: green and black olives chopped, giardiniera, garlic, capers, oregano, drowned in olive oil.","It must macerate at least twenty-four hours — it is the dish, the cured meats are only a support.","Split the round loaf horizontally and hollow the crumb of the lid slightly to make room.","Moisten both faces with oil from the salad, then build: olives, provolone, meats, provolone, olives.","Close, wrap tightly and press under a weight for at least 3 hours. Cut in quarters at the moment of serving, never before."]} },

{ id:'boudin-cajun', c:'na', lat:30.224, lon:-92.020, base:8, prep:90, cook:90, diff:3, tags:['pork','rice','street'],
  art:{v:'board',bg:'#2b2419',plate:'#f4ead4',style:'roll',food:['#c9a878','#8f5a3a','#e8dcb8','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Boudin cajun',en:'Cajun boudin'},
  p:{fr:'Lafayette, Louisiane, États-Unis',en:'Lafayette, Louisiana, United States'},
  d:{fr:"Une saucisse de porc, de foie et de riz cuit, héritée du boudin blanc français par les Acadiens déportés. On l'achète à la boucherie et on le mange debout sur le parking, en pressant le boyau entre les dents pour n'avaler que la farce — le boyau se jette.",
     en:"A sausage of pork, liver and cooked rice, inherited from French boudin blanc by the deported Acadians. It is bought at the butcher's and eaten standing in the car park, squeezing the casing between the teeth to take only the filling — the casing is thrown away."},
  i:[['pork_shoulder',400,'g'],['pork_liver',200,'g'],['long_grain_rice',300,'g'],['onion',2,'pc'],['green_pepper',1,'pc'],['celery',2,'pc'],['spring_onion',6,'pc'],['parsley',4,'tbsp'],['cayenne',1,'tbsp'],['sausage_casings',null,''],['black_peppercorns',1,'tbsp'],['salt',null,'']],
  s:{fr:["Pochez le porc, le foie et la trinité 1 heure dans l'eau salée, et gardez précieusement le bouillon.","Hachez viande et foie à la grille moyenne, en gardant du grain : un boudin cajun n'est pas une mousse.","Mêlez au riz cuit dans le bouillon, à l'oignon vert, au persil, au cayenne et à beaucoup de poivre noir.","La proportion tient à peu près à moitié riz, moitié viande : plus de riz et le boudin devient pâteux, moins et il se défait.","Embossez sans serrer et pochez 20 minutes à 75 °C, sans jamais bouillir — au-delà, le boyau éclate et tout le riz s'échappe."],
     en:["Poach the pork, liver and trinity 1 hour in salted water, and keep the broth carefully.","Mince the meat and liver on the medium plate, keeping some grain: a Cajun boudin is not a mousse.","Mix with the rice cooked in that broth, the spring onion, parsley, cayenne and plenty of black pepper.","The proportion is roughly half rice, half meat: more rice and the boudin turns pasty, less and it falls apart.","Fill the casings loosely and poach 20 minutes at 75°C, never boiling — beyond that the casing splits and all the rice escapes."]} },

{ id:'king-cake', c:'na', lat:29.951, lon:-90.072, base:10, prep:180, cook:30, diff:2, tags:['sweet','bake','festive'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'roll',food:['#e0b45a','#7f4a9a','#e8c46a','#4f8f4a'],garnish:'#c9754a'},
  n:{fr:'King cake',en:'King cake'},
  p:{fr:'La Nouvelle-Orléans, Louisiane, États-Unis',en:'New Orleans, Louisiana, United States'},
  d:{fr:"Une couronne briochée à la cannelle, glacée aux trois couleurs du Mardi gras — violet, or et vert. La fève française est devenue un bébé de plastique caché dessous : celui qui le trouve devra offrir le king cake suivant, ce qui entretient la coutume jusqu'au Carême.",
     en:"A cinnamon brioche crown iced in the three Mardi Gras colours — purple, gold and green. The French bean has become a plastic baby hidden underneath: whoever finds it must provide the next king cake, which keeps the custom going until Lent."},
  i:[['flour',500,'g'],['sugar',100,'g'],['butter',150,'g'],['egg',3,'pc'],['fresh_yeast',20,'g'],['whole_milk',200,'ml'],['cinnamon',2,'tbsp'],['brown_sugar',120,'g'],['powdered_sugar',300,'g'],['lemon',1,'pc'],['cream_cheese',150,'g'],['salt',null,'']],
  s:{fr:["Pétrissez une pâte briochée avec la farine, le lait tiède, la levure, les œufs, le sucre et le sel, puis incorporez le beurre mou.","Laissez lever 1 h 30, abaissez en grand rectangle et couvrez de beurre, de cassonade, de cannelle et de cream cheese battu.","Roulez serré dans la longueur, puis joignez les deux bouts en couronne en pinçant fermement la jonction.","Entaillez le dessus de la couronne en biais tous les cinq centimètres, pour laisser voir la spirale de garniture.","Laissez pousser 1 heure et cuisez 30 minutes à 180 °C. Glacez au sucre et au citron, et sucrez en trois bandes violette, or et verte."],
     en:["Knead a brioche dough with the flour, warm milk, yeast, eggs, sugar and salt, then work in the softened butter.","Prove 1½ hours, roll into a large rectangle and cover with butter, brown sugar, cinnamon and beaten cream cheese.","Roll it up tightly lengthwise, then join the two ends into a crown, pinching the join firmly.","Cut the top of the crown on the bias every five centimetres, to let the spiral of filling show.","Prove for an hour and bake 30 minutes at 180°C. Ice with sugar and lemon, and sprinkle in three bands of purple, gold and green."]} },

{ id:'chili-con-carne-texas', c:'na', lat:29.424, lon:-98.494, base:6, prep:60, cook:180, diff:2, tags:['beef','slow','spicy'],
  art:{v:'pot',bg:'#33251c',plate:'#f0e4c8',style:'stew',food:['#8f2a2a','#c9532c','#6f2a2a','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Chili con carne texan',en:'Texas chili con carne'},
  p:{fr:'San Antonio, Texas, États-Unis',en:'San Antonio, Texas, United States'},
  d:{fr:"Un ragoût de cubes de bœuf dans une purée de piments séchés, sans un seul haricot. Les Chili Queens le vendaient sur la Plaza de San Antonio dès 1880 ; au Texas, mettre des haricots dans un chili est une faute qu'aucun concours n'admet.",
     en:"A stew of beef cubes in a purée of dried chillies, without a single bean. The Chili Queens sold it on San Antonio's Plaza from 1880; in Texas, putting beans in a chili is an offence no competition admits."},
  i:[['beef_chuck',1,'kg'],['ancho_chili',60,'g'],['guajillo_chili',40,'g'],['onion',2,'pc'],['garlic',6,'clove'],['beef_broth',500,'ml'],['cumin',1,'tbsp'],['oregano',1,'tbsp'],['lard',60,'g'],['masa_harina',2,'tbsp'],['white_vinegar',2,'tbsp'],['dark_chocolate',10,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Épépinez les piments secs, faites-les griller 30 secondes par face à la poêle sèche, puis trempez-les 30 minutes dans l'eau chaude.","Ce grillage court réveille les huiles ; brûlés une seconde de trop, ils rendent tout le chili amer et il n'y a pas de rattrapage.","Mixez-les avec l'eau de trempage en une purée lisse et passez-la au tamis pour retenir les peaux.","Taillez le bœuf en cubes de 2 cm — jamais haché — et saisissez-les au saindoux par petites quantités.","Ajoutez la purée de piments, l'ail, le cumin, l'origan et le bouillon, et laissez mijoter 2 h 30. Liez à la masa harina délayée dans les vingt dernières minutes."],
     en:["Seed the dried chillies, toast them 30 seconds a side in a dry pan, then soak them 30 minutes in hot water.","That brief toasting wakes the oils; burnt a second too long, they make the whole chili bitter and nothing rescues it.","Blend them with the soaking water into a smooth purée and pass it through a sieve to hold back the skins.","Cut the beef into 2 cm cubes — never minced — and sear them in lard in small batches.","Add the chilli purée, garlic, cumin, oregano and broth, and simmer 2½ hours. Thicken with slaked masa harina in the last twenty minutes."]} },

{ id:'breakfast-tacos', c:'na', lat:30.267, lon:-97.743, base:4, prep:25, cook:20, diff:1, tags:['breakfast','fast','street'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'roll',food:['#e8c46a','#c9402c','#e0b45a','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Breakfast tacos',en:'Breakfast tacos'},
  p:{fr:'Austin, Texas, États-Unis',en:'Austin, Texas, United States'},
  d:{fr:"Des tortillas de blé garnies d'œufs brouillés, de chorizo et de pommes de terre, mangées au volant. Austin et San Antonio se disputent l'invention avec la même mauvaise foi ; la seule chose qui fasse consensus, c'est que la tortilla doit être de blé et faite le matin même.",
     en:"Flour tortillas filled with scrambled egg, chorizo and potato, eaten at the wheel. Austin and San Antonio dispute the invention with equal bad faith; the one point of agreement is that the tortilla must be flour and made that morning."},
  i:[['flour_tortillas',8,'pc'],['egg',6,'pc'],['chorizo',150,'g'],['potato',200,'g'],['cheddar_cheese',100,'g'],['black_beans',150,'g'],['jalapeno',2,'pc'],['ripe_tomato',2,'pc'],['cilantro',1,'bunch'],['lime',1,'pc'],['sunflower_oil',40,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Coupez les pommes de terre en petits dés et faites-les rissoler 12 minutes à la poêle, jusqu'à ce qu'elles soient dorées et tendres.","Faites revenir le chorizo mexicain émietté à part et gardez sa graisse rouge : c'est elle qui colorera les œufs.","Battez les œufs sans lait ni crème et cuisez-les dans cette graisse à feu doux, en remuant sans arrêt — ils doivent rester crémeux et sous-cuits.","Réchauffez les tortillas trente secondes par face sur une plaque sèche : passées au micro-ondes, elles deviennent caoutchouteuses.","Garnissez, ajoutez le fromage qui fondra à la chaleur, la salsa de tomate et jalapeño, la coriandre et un trait de citron vert. Pliez et mangez aussitôt."],
     en:["Dice the potatoes small and fry them 12 minutes, until golden and tender.","Fry the crumbled Mexican chorizo separately and keep its red fat: it is what will colour the eggs.","Beat the eggs with no milk or cream and cook them in that fat over low heat, stirring without pause — they must stay creamy and underdone.","Warm the tortillas thirty seconds a side on a dry griddle: microwaved, they turn rubbery.","Fill, add cheese to melt in the heat, the tomato and jalapeño salsa, coriander and a squeeze of lime. Fold and eat at once."]} },

{ id:'kolaches-texan', c:'na', lat:31.803, lon:-97.091, base:12, prep:180, cook:20, diff:2, tags:['pork','bake','street'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'roll',food:['#e0b45a','#c9924a','#f2dfa8','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Klobasnek de West',en:'West kolaches'},
  p:{fr:'West, Texas, États-Unis',en:'West, Texas, United States'},
  d:{fr:"Une brioche moelleuse enroulée autour d'une saucisse fumée, vendue sur l'autoroute entre Dallas et Austin. Les Tchèques de Moravie s'installèrent à West en 1880 ; le vrai koláč est sucré et ouvert, et la version salée à la saucisse s'appelle en réalité klobasnek.",
     en:"A soft brioche wrapped around a smoked sausage, sold on the highway between Dallas and Austin. Moravian Czechs settled in West in 1880; a true koláč is sweet and open, and the savoury sausage version is properly called a klobasnek."},
  i:[['flour',500,'g'],['sugar',80,'g'],['butter',100,'g'],['egg',2,'pc'],['fresh_yeast',20,'g'],['whole_milk',250,'ml'],['smoked_sausage',12,'pc'],['cheddar_cheese',150,'g'],['jalapeno',3,'pc'],['salt',null,'']],
  s:{fr:["Faites un levain avec la levure, le lait tiède et un peu de farine, et attendez qu'il double avant d'aller plus loin.","Pétrissez avec le reste, puis incorporez le beurre mou : la pâte tchèque est plus riche qu'une pâte à pain et plus légère qu'une brioche.","Laissez lever 1 h 30, puis aplatissez des morceaux de 60 g en rectangles.","Épongez soigneusement les saucisses : une saucisse humide fait décoller la pâte à la cuisson et le klobasnek s'ouvre.","Enroulez la saucisse avec une lamelle de fromage et de jalapeño, soudure dessous, laissez pousser 40 minutes et cuisez 18 minutes à 190 °C."],
     en:["Make a starter with the yeast, warm milk and a little flour, and wait for it to double before going further.","Knead with the rest, then work in the softened butter: Czech dough is richer than bread dough and lighter than brioche.","Prove 1½ hours, then flatten 60 g pieces into rectangles.","Blot the sausages carefully: a wet sausage makes the dough lift as it bakes and the klobasnek opens.","Roll the sausage up with a strip of cheese and jalapeño, seam underneath, prove 40 minutes and bake 18 minutes at 190°C."]} },

{ id:'chicken-fried-steak', c:'na', lat:32.738, lon:-101.951, base:4, prep:30, cook:20, diff:2, tags:['beef','fry','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f4f0e6',style:'flat',food:['#c9924a','#f4f0e6','#e0b45a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Chicken fried steak',en:'Chicken fried steak'},
  p:{fr:'Lamesa, Texas, États-Unis',en:'Lamesa, Texas, United States'},
  d:{fr:"Un steak attendri, pané et frit comme du poulet, noyé d'une sauce blanche au poivre. C'est le schnitzel viennois passé par les immigrants allemands et tchèques du Texas ; Lamesa en revendique l'invention en 1911 et lui consacre une fête annuelle.",
     en:"A tenderised steak, crumbed and fried like chicken, drowned in a white pepper gravy. It is the Viennese schnitzel filtered through Texas's German and Czech immigrants; Lamesa claims the invention in 1911 and holds an annual festival for it."},
  i:[['beef_steak',4,'pc'],['flour',250,'g'],['egg',2,'pc'],['whole_milk',600,'ml'],['sunflower_oil',500,'ml'],['black_peppercorns',1,'tbsp'],['sweet_paprika',1,'tsp'],['cayenne',1,'pinch'],['baking_powder',1,'tsp'],['salt',null,'']],
  s:{fr:["Faites attendrir les steaks au maillet cranté jusqu'à 8 mm : le tissu conjonctif doit être rompu, sans quoi la viande se rétracte dans l'huile.","Farinez, passez à l'œuf battu au lait, puis à la farine additionnée de levure chimique et de paprika.","La levure dans la panure est l'astuce texane : elle fait gonfler la croûte et lui donne son aspect boursouflé.","Laissez reposer les steaks panés 15 minutes sur une grille : la panure s'hydrate et adhère, au lieu de se détacher en plaques.","Frites 4 minutes par face à 175 °C, réservez, et faites la sauce dans trois cuillerées de graisse de friture avec farine, lait chaud et beaucoup de poivre noir."],
     en:["Tenderise the steaks with a toothed mallet to 8 mm: the connective tissue must be broken, or the meat shrinks in the oil.","Flour them, dip in egg beaten with milk, then in flour mixed with baking powder and paprika.","The baking powder in the coating is the Texan trick: it puffs the crust and gives it its blistered look.","Rest the crumbed steaks 15 minutes on a rack: the coating hydrates and grips, instead of peeling off in sheets.","Fry 4 minutes a side at 175°C, set aside, and make the gravy in three spoonfuls of the frying fat with flour, hot milk and plenty of black pepper."]} },

{ id:'chile-con-queso', c:'na', lat:30.274, lon:-97.740, base:6, prep:20, cook:20, diff:1, tags:['cheese','spicy','fast'],
  art:{v:'bowl',bg:'#33251c',plate:'#f4ecd8',style:'other',food:['#e8a032','#e8c46a','#c9402c','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Chile con queso',en:'Chile con queso'},
  p:{fr:'Austin, Texas, États-Unis',en:'Austin, Texas, United States'},
  d:{fr:"Une fondue de fromage fondu aux piments et à la tomate, servie brûlante avec des chips de maïs. Né à San Antonio dans les années 1920, il doit sa fluidité aux sels de fonte du fromage industriel : un cheddar fermier, lui, se sépare en huile et en fils.",
     en:"A melted cheese dip with chillies and tomato, served scalding with corn chips. Born in San Antonio in the 1920s, it owes its fluidity to the emulsifying salts of processed cheese: a farmhouse cheddar would split into oil and strings."},
  i:[['processed_cheese',400,'g'],['ripe_tomato',200,'g'],['green_chili',3,'pc'],['chorizo',100,'g'],['onion',1,'pc'],['whole_milk',100,'ml'],['cilantro',1,'bunch'],['tortilla_chips',300,'g'],['cumin',1,'tsp'],['salt',null,'']],
  s:{fr:["Faites griller les piments verts jusqu'à ce que la peau noircisse, enfermez-les 15 minutes dans un sac, pelez-les et hachez-les.","Faites revenir l'oignon et le chorizo émietté, puis ajoutez la tomate concassée et laissez réduire 10 minutes.","Coupez le fromage en dés et faites-le fondre au bain-marie avec le lait, jamais sur le feu direct : au-delà de 70 °C il tranche.","Incorporez la garniture au fromage fondu, hors du feu, et ajoutez le cumin et la coriandre.","Servez immédiatement dans un plat chauffé : le queso fige en cinq minutes, et le réchauffer une seconde fois le rend granuleux."],
     en:["Roast the green chillies until the skin blackens, shut them in a bag for 15 minutes, peel and chop them.","Fry the onion and crumbled chorizo, then add the crushed tomato and reduce for 10 minutes.","Dice the cheese and melt it over a bain-marie with the milk, never over direct heat: above 70°C it splits.","Fold the garnish into the melted cheese off the heat, and add the cumin and coriander.","Serve at once in a warmed dish: queso sets within five minutes, and reheating it a second time turns it grainy."]} },

{ id:'kansas-city-ribs', c:'na', lat:39.100, lon:-94.579, base:6, prep:60, cook:330, diff:3, tags:['pork','slow','grill'],
  art:{v:'board',bg:'#2b2419',plate:'#f4ead4',style:'grill',food:['#6f2a2a','#8f3b2a','#c9754a','#e0b45a'],garnish:'#7fae6a'},
  n:{fr:'Travers de Kansas City',en:'Kansas City ribs'},
  p:{fr:'Kansas City, Missouri, États-Unis',en:'Kansas City, Missouri, United States'},
  d:{fr:"Des travers de porc fumés cinq heures et laqués d'une sauce épaisse à la mélasse. Henry Perry, né au Tennessee, ouvrit son premier stand en 1908 et fonda l'école de Kansas City ; la ville compte aujourd'hui plus d'une centaine de barbecues.",
     en:"Pork ribs smoked five hours and lacquered with a thick molasses sauce. Henry Perry, born in Tennessee, opened his first stand in 1908 and founded the Kansas City school; the city now counts over a hundred barbecue houses."},
  i:[['pork_ribs',2,'kg'],['brown_sugar',80,'g'],['sweet_paprika',3,'tbsp'],['black_peppercorns',1,'tbsp'],['ketchup',300,'ml'],['black_treacle',80,'ml'],['cider_vinegar',80,'ml'],['mustard',1,'tbsp'],['garlic_powder',1,'tbsp'],['cayenne',1,'tsp'],['apple_juice',200,'ml'],['salt',null,'']],
  s:{fr:["Retirez la membrane blanche au dos du travers en la soulevant au couteau puis en tirant avec un torchon : elle ne fond jamais et empêche la fumée d'entrer.","Frottez d'un mélange de cassonade, paprika, sel et poivre, et laissez douze heures au froid.","Fumez à 110 °C au bois de pommier, trois heures à découvert, en vaporisant du jus de pomme toutes les heures.","Enveloppez d'aluminium avec un peu de jus et poursuivez deux heures : c'est cette étape qui attendrit sans dessécher.","Découvrez, badigeonnez de sauce et remettez trente minutes pour la laquer. La viande doit se détacher sous la dent, mais pas tomber de l'os."],
     en:["Remove the white membrane from the back of the rack by lifting it with a knife then pulling with a cloth: it never melts and blocks the smoke.","Rub with a mix of brown sugar, paprika, salt and pepper, and leave twelve hours in the cold.","Smoke at 110°C over applewood, three hours uncovered, spraying apple juice every hour.","Wrap in foil with a little juice and continue two hours: that stage tenderises without drying.","Unwrap, brush with sauce and return for thirty minutes to lacquer it. The meat should give under the tooth, but not fall off the bone."]} },

{ id:'cincinnati-chili', c:'na', lat:39.103, lon:-84.512, base:6, prep:30, cook:150, diff:2, tags:['beef','noodles','comfort'],
  art:{v:'plate',bg:'#33251c',plate:'#f4ecd8',style:'noodle',food:['#8f5a3a','#f2dfa8','#e8c46a','#c9532c'],garnish:'#7fae6a'},
  n:{fr:'Chili de Cincinnati',en:'Cincinnati chili'},
  p:{fr:'Cincinnati, Ohio, États-Unis',en:'Cincinnati, Ohio, United States'},
  d:{fr:"Une sauce de bœuf à la cannelle et au cacao servie sur des spaghettis, sous une montagne de cheddar râpé. Les frères Kiradjieff, immigrés macédoniens, l'ont créée en 1922 en adaptant un ragoût des Balkans ; on la commande en trois, quatre ou cinq étages selon les garnitures.",
     en:"A beef sauce with cinnamon and cocoa served over spaghetti, under a mountain of grated cheddar. The Kiradjieff brothers, Macedonian immigrants, created it in 1922 by adapting a Balkan stew; you order it three, four or five ways depending on the toppings."},
  i:[['ground_beef',500,'g'],['water',1,'l'],['onion',2,'pc'],['tomato_paste',3,'tbsp'],['chili_powder',30,'g'],['cinnamon',1,'tbsp'],['cumin',1,'tsp'],['cocoa_powder',1,'tbsp'],['allspice',0.5,'tsp'],['cider_vinegar',2,'tbsp'],['spaghetti',400,'g'],['cheddar_cheese',300,'g'],['red_kidney_beans',200,'g'],['salt',null,'']],
  s:{fr:["Ne faites jamais revenir la viande : délayez le bœuf haché cru dans l'eau froide à la fourchette, jusqu'à ce qu'il n'y ait plus un grumeau.","C'est ce qui distingue le chili de Cincinnati de tous les autres : la viande bouillie reste en grains fins et la sauce n'est pas grasse.","Portez à ébullition, ajoutez l'oignon râpé, le concentré et toutes les épices, et laissez frémir 2 h 30 à découvert.","Laissez reposer une nuit au froid et retirez la graisse figée en surface : c'est la seule façon d'obtenir la texture attendue.","Servez sur des spaghettis, avec du cheddar râpé en montagne, des haricots rouges et de l'oignon cru selon le nombre d'étages voulu."],
     en:["Never brown the meat: whisk the raw minced beef into cold water with a fork, until not a lump remains.","That is what sets Cincinnati chili apart from every other: boiled meat stays in fine grains and the sauce is not greasy.","Bring to the boil, add the grated onion, tomato purée and every spice, and simmer 2½ hours uncovered.","Rest it overnight in the cold and lift off the set fat: it is the only way to reach the expected texture.","Serve over spaghetti, with grated cheddar piled high, kidney beans and raw onion according to how many ways you want it."]} },

{ id:'toasted-ravioli', c:'na', lat:38.627, lon:-90.199, base:4, prep:30, cook:15, diff:1, tags:['fry','street','comfort'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#e0b45a','#c9402c','#f2dfa8','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Toasted ravioli',en:'Toasted ravioli'},
  p:{fr:'The Hill, Saint-Louis, Missouri, États-Unis',en:'The Hill, St. Louis, Missouri, United States'},
  d:{fr:"Des raviolis panés et frits, trempés dans une sauce tomate, spécialité du quartier italien de Saint-Louis. La légende dit qu'un cuisinier laissa tomber des raviolis dans la friteuse au lieu de la casserole vers 1940 ; on les appelle toasted alors qu'ils sont frits, ce que personne n'explique.",
     en:"Breaded, fried ravioli dipped in tomato sauce, the speciality of St. Louis's Italian quarter. Legend has a cook dropping ravioli into the fryer instead of the pot around 1940; they are called toasted although they are fried, which nobody explains."},
  i:[['ravioli',24,'pc'],['egg',2,'pc'],['breadcrumbs',150,'g'],['parmesan',60,'g'],['whole_milk',60,'ml'],['sunflower_oil',700,'ml'],['tomato_sauce',300,'ml'],['oregano',1,'tsp'],['salt',null,'']],
  s:{fr:["Employez des raviolis frais et non cuits : des raviolis pochés au préalable se déchirent à la panure et laissent fuir la farce.","Battez les œufs avec le lait et passez les raviolis d'abord dans ce mélange, puis dans la chapelure additionnée de parmesan.","Laissez-les sécher 15 minutes sur une grille avant de frire : la panure adhère et ne se détache pas en plaques dans l'huile.","Frites 2 minutes par face à 180 °C, six à la fois, pour que la température ne chute pas.","Égouttez, salez et parsemez de parmesan tant qu'ils sont brûlants. Servez avec une sauce tomate chaude, à tremper."],
     en:["Use fresh uncooked ravioli: pre-poached ones tear during crumbing and let the filling escape.","Beat the eggs with the milk and pass the ravioli first through that, then through breadcrumbs mixed with parmesan.","Let them dry 15 minutes on a rack before frying: the coating grips and does not peel off in the oil.","Fry 2 minutes a side at 180°C, six at a time, so the temperature does not fall.","Drain, salt and scatter parmesan while they are scalding. Serve with hot tomato sauce, for dipping."]} },

{ id:'corn-dog', c:'na', lat:39.782, lon:-89.650, base:4, prep:30, cook:15, diff:2, tags:['pork','fry','street'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'skewer',food:['#e0b45a','#c9924a','#8f5a3a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Corn dog',en:'Corn dog'},
  p:{fr:'Springfield, Illinois, États-Unis',en:'Springfield, Illinois, United States'},
  d:{fr:"Une saucisse embrochée, trempée dans une pâte à cornbread et frite. Brevetée en 1929 à Springfield sous le nom de crusty cur, elle a trouvé son public aux foires d'État du Midwest ; c'est le bâton, plus que la pâte, qui en a fait le premier repas américain qui se mange en marchant.",
     en:"A sausage on a stick, dipped in cornbread batter and fried. Patented in 1929 in Springfield as the crusty cur, it found its public at Midwest state fairs; it is the stick, more than the batter, that made it the first American meal eaten walking."},
  i:[['pork_sausage',8,'pc'],['cornmeal',150,'g'],['flour',100,'g'],['sugar',2,'tbsp'],['egg',1,'pc'],['whole_milk',250,'ml'],['baking_powder',1,'tbsp'],['sunflower_oil',1.2,'l'],['mustard',60,'g'],['salt',null,'']],
  s:{fr:["Épongez les saucisses et roulez-les dans un voile de farine sèche : sans cela la pâte glisse et découvre la saucisse dans l'huile.","Embrochez-les sur des bâtons de bois en les enfonçant aux deux tiers seulement.","Mêlez la pâte et versez-la dans un verre haut et étroit : c'est la seule façon de tremper le corn dog d'un seul geste vertical.","La pâte doit être épaisse comme une pâte à gaufres — trop fluide, elle coule ; trop épaisse, elle reste crue au centre.","Trempez, égouttez deux secondes et plongez dans l'huile à 180 °C en tenant le bâton dix secondes avant de lâcher, pour que la croûte se forme."],
     en:["Blot the sausages and roll them in a film of dry flour: without it the batter slides off and bares the sausage in the oil.","Skewer them on wooden sticks, pushing them in only two-thirds of the way.","Mix the batter and pour it into a tall narrow glass: the only way to dip a corn dog in one vertical movement.","The batter should be as thick as waffle batter — too thin it runs, too thick it stays raw in the centre.","Dip, drain for two seconds and lower into oil at 180°C, holding the stick for ten seconds before letting go, so the crust sets."]} },

{ id:'brownies-palmer-house', c:'na', lat:41.878, lon:-87.630, base:10, prep:30, cook:35, diff:2, tags:['sweet','bake','comfort'],
  art:{v:'board',bg:'#2b2419',plate:'#f4ead4',style:'cake',food:['#3a2a1a','#6f4a2a','#c9924a','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Brownies du Palmer House',en:'Palmer House brownies'},
  p:{fr:'Chicago, Illinois, États-Unis',en:'Chicago, Illinois, United States'},
  d:{fr:"Le premier brownie connu, créé en 1893 à l'hôtel Palmer House pour l'Exposition universelle. Bertha Palmer voulait un dessert que les dames puissent emporter dans leur panier-repas : plus petit qu'une part de gâteau, plus solide qu'une tarte, glacé à l'abricot pour se conserver.",
     en:"The first known brownie, created in 1893 at the Palmer House hotel for the World's Fair. Bertha Palmer wanted a dessert ladies could carry in a lunch box: smaller than a slice of cake, sturdier than a tart, apricot-glazed to keep."},
  i:[['dark_chocolate',200,'g'],['butter',150,'g'],['sugar',200,'g'],['egg',3,'pc'],['flour',100,'g'],['walnuts',100,'g'],['apricot_jam',100,'g'],['water',60,'ml'],['vanilla',1,'pc'],['salt',null,'']],
  s:{fr:["Faites fondre le chocolat et le beurre au bain-marie, sans dépasser 45 °C, et laissez tiédir avant d'ajouter les œufs.","Fouettez les œufs et le sucre séparément 5 minutes jusqu'au ruban : cette mousse donne la fine croûte brillante du dessus.","Incorporez le chocolat tiède, puis la farine et le sel en une dizaine de tours — trop mélangée, la pâte donne un gâteau et non un brownie.","Versez dans un moule chemisé et couvrez de cerneaux de noix entiers, largement, comme au Palmer House.","Cuisez 35 minutes à 175 °C : le centre doit encore trembler. Nappez du glaçage à l'abricot délayé à l'eau chaude dès la sortie du four."],
     en:["Melt the chocolate and butter over a bain-marie, never above 45°C, and let it cool before the eggs go in.","Whisk the eggs and sugar separately for 5 minutes to the ribbon: that foam gives the thin shiny crust on top.","Fold in the warm chocolate, then the flour and salt in ten turns — overmixed, the batter gives a cake and not a brownie.","Pour into a lined tin and cover with whole walnut halves, generously, as at the Palmer House.","Bake 35 minutes at 175°C: the centre should still tremble. Coat with apricot glaze let down with hot water as it leaves the oven."]} },

{ id:'navajo-taco', c:'na', lat:35.680, lon:-109.054, base:4, prep:70, cook:20, diff:2, tags:['beef','fry','street'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'flat',food:['#e0b45a','#8f5a3a','#7fae5a','#c9402c'],garnish:'#6fbf8f'},
  n:{fr:'Navajo taco',en:'Navajo taco'},
  p:{fr:'Window Rock, Arizona, États-Unis',en:'Window Rock, Arizona, United States'},
  d:{fr:"Une galette de pain frit couverte de haricots, de viande et de crudités. Le fry bread naquit en 1864 pendant la Longue Marche, quand l'armée distribua aux Navajos déportés de la farine et du saindoux au lieu de leurs cultures : un plat né d'une déportation, devenu emblème et sujet de débat.",
     en:"A round of fried bread topped with beans, meat and raw vegetables. Fry bread was born in 1864 during the Long Walk, when the army issued deported Navajos flour and lard in place of their crops: a dish born of a deportation, now both emblem and subject of argument."},
  i:[['flour',300,'g'],['baking_powder',1,'tbsp'],['warm_water',250,'ml'],['lard',400,'g'],['ground_beef',400,'g'],['pinto_beans',300,'g'],['lettuce',1,'pc'],['ripe_tomato',2,'pc'],['cheddar_cheese',150,'g'],['sour_cream',150,'g'],['chili_powder',1,'tbsp'],['onion',1,'pc'],['salt',null,'']],
  s:{fr:["Mêlez la farine, la levure chimique et le sel, versez l'eau tiède et rassemblez la pâte sans pétrir : le fry bread ne demande aucun gluten développé.","Laissez-la reposer 30 minutes sous un linge — c'est le repos, non le travail, qui la rend souple à étirer.","Étirez chaque boule à la main jusqu'à 20 cm et percez un trou au centre du bout du doigt : sans lui, la galette gonfle en ballon et cuit inégalement.","Frites dans deux centimètres de saindoux à 190 °C, 90 secondes par face, jusqu'à ce qu'elle boursoufle et dore.","Égouttez et garnissez brûlante de haricots pinto écrasés, de viande épicée, de salade, de tomate, de fromage et de crème. Se mange à la main, pliée en deux."],
     en:["Mix the flour, baking powder and salt, pour in the warm water and bring the dough together without kneading: fry bread needs no developed gluten.","Rest it 30 minutes under a cloth — it is the rest, not the working, that makes it supple to stretch.","Stretch each ball by hand to 20 cm and pierce a hole at the centre with a fingertip: without it the round balloons and cooks unevenly.","Fry in two centimetres of lard at 190°C, 90 seconds a side, until it blisters and browns.","Drain and top it scalding with crushed pinto beans, spiced meat, lettuce, tomato, cheese and sour cream. Eaten by hand, folded in two."]} },

{ id:'chimichanga', c:'na', lat:32.223, lon:-110.975, base:4, prep:40, cook:20, diff:2, tags:['beef','fry','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'roll',food:['#e0b45a','#c9924a','#8f5a3a','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Chimichanga',en:'Chimichanga'},
  p:{fr:'Tucson, Arizona, États-Unis',en:'Tucson, Arizona, United States'},
  d:{fr:"Un burrito frit jusqu'à devenir croustillant, nappé de sauce et de fromage fondu. Monica Flin, du restaurant El Charro à Tucson, aurait laissé tomber un burrito dans la friteuse en 1922 et retenu de justesse un juron devant ses neveux : chimichanga est le mot qu'elle a inventé à la place.",
     en:"A burrito fried until crisp, coated with sauce and melted cheese. Monica Flin of El Charro in Tucson is said to have dropped a burrito in the fryer in 1922 and swallowed a curse in front of her nephews: chimichanga is the word she invented instead."},
  i:[['flour_tortillas',4,'pc'],['beef_chuck',500,'g'],['refried_beans',200,'g'],['cheddar_cheese',150,'g'],['onion',1,'pc'],['green_chili',2,'pc'],['cumin',1,'tsp'],['tomato_sauce',300,'ml'],['sunflower_oil',1,'l'],['sour_cream',150,'g'],['cilantro',1,'bunch'],['salt',null,'']],
  s:{fr:["Braisez le paleron 3 heures avec l'oignon, le cumin et les piments verts, puis effilochez-le et laissez-le refroidir.","Une farce tiède fait ramollir la tortilla et le chimichanga s'ouvre dans l'huile : c'est la faute la plus fréquente.","Réchauffez les tortillas pour les assouplir, garnissez le tiers inférieur, repliez les côtés puis roulez très serré.","Fixez le rabat avec un pique en bois ou avec un peu de pâte de haricot, qui colle en cuisant.","Frites 3 minutes à 190 °C en arrosant le dessus, puis nappez de sauce et de fromage et passez sous le gril. Retirez le pique avant de servir."],
     en:["Braise the chuck 3 hours with the onion, cumin and green chillies, then shred it and let it cool.","A warm filling softens the tortilla and the chimichanga opens in the oil: the commonest failure.","Warm the tortillas to make them pliable, fill the lower third, fold the sides in then roll very tightly.","Fix the flap with a wooden pick or a smear of bean paste, which glues as it cooks.","Fry 3 minutes at 190°C, spooning oil over the top, then coat with sauce and cheese and pass under the grill. Remove the pick before serving."]} },

{ id:'carne-adovada', c:'na', lat:35.078, lon:-106.640, base:6, prep:60, cook:210, diff:2, tags:['pork','slow','spicy'],
  art:{v:'pot',bg:'#33251c',plate:'#f0e4c8',style:'stew',food:['#8f2a2a','#c9532c','#6f2a2a','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Carne adovada',en:'Carne adovada'},
  p:{fr:'Albuquerque, Nouveau-Mexique, États-Unis',en:'Albuquerque, New Mexico, United States'},
  d:{fr:"Du porc mariné une nuit dans une purée de piments rouges du Nouveau-Mexique, puis braisé jusqu'à s'effilocher. Adovada vient d'adobado, mariné : la marinade au piment était d'abord une conservation, avant le froid, et le plat se sert traditionnellement à Noël.",
     en:"Pork marinated overnight in a purée of New Mexico red chillies, then braised until it shreds. Adovada comes from adobado, marinated: the chilli marinade was first a preservation, before refrigeration, and the dish is traditionally served at Christmas."},
  i:[['pork_shoulder',1,'kg'],['dried_chili',200,'g'],['garlic',8,'clove'],['oregano',1,'tbsp'],['cumin',1,'tsp'],['white_vinegar',3,'tbsp'],['honey',1,'tbsp'],['onion',1,'pc'],['chicken_broth',400,'ml'],['flour_tortillas',8,'pc'],['salt',null,'']],
  s:{fr:["Ôtez les queues et les graines des piments rouges séchés, puis faites-les tremper 30 minutes dans l'eau bouillante.","Ne les grillez pas comme on ferait pour un chili texan : le piment du Nouveau-Mexique est doux et fruité, et le grillage le rend amer.","Mixez-les avec l'eau de trempage, l'ail, l'origan, le cumin, le vinaigre et le miel, et passez au tamis.","Taillez le porc en cubes de 4 cm et laissez-le mariner une nuit entière dans cette purée, au froid.","Braisez à couvert 3 heures à 160 °C, sans rien ajouter d'autre que le bouillon si la sauce serre trop. Servez avec des tortillas de blé."],
     en:["Remove the stems and seeds from the dried red chillies, then soak them 30 minutes in boiling water.","Do not toast them as you would for a Texas chili: New Mexico chilli is sweet and fruity, and toasting turns it bitter.","Blend them with the soaking water, garlic, oregano, cumin, vinegar and honey, and pass through a sieve.","Cut the pork into 4 cm cubes and marinate it overnight in that purée, in the cold.","Braise covered 3 hours at 160°C, adding nothing but broth if the sauce tightens too far. Serve with flour tortillas."]} },

{ id:'salsa-verde-du-desert', c:'na', lat:35.687, lon:-105.938, base:6, prep:25, cook:20, diff:1, tags:['veg','spicy','fresh'],
  art:{v:'bowl',bg:'#28331f',plate:'#f4ecd8',style:'other',food:['#4f8f4a','#7fae5a','#e8dcb8','#f0e8d0'],garnish:'#6fbf8f'},
  n:{fr:'Salsa verde du désert',en:'Desert salsa verde'},
  p:{fr:'Santa Fe, Nouveau-Mexique, États-Unis',en:'Santa Fe, New Mexico, United States'},
  d:{fr:"Une sauce verte de tomatilles grillées, de jalapeños et de coriandre. La tomatille n'est pas une tomate verte mais un fruit à enveloppe de papier, cultivé par les Aztèques bien avant elle ; c'est son acidité, et non celle du citron, qui donne son mordant à la sauce.",
     en:"A green sauce of roasted tomatillos, jalapeños and coriander. The tomatillo is not a green tomato but a husked fruit, grown by the Aztecs long before it; its acidity, not the lime's, is what gives the sauce its bite."},
  i:[['tomatillos',500,'g'],['jalapeno',2,'pc'],['onion',1,'pc'],['garlic',4,'clove'],['cilantro',1,'bunch'],['lime',1,'pc'],['tortilla_chips',300,'g'],['salt',null,'']],
  s:{fr:["Retirez l'enveloppe papyracée des tomatilles et lavez-les à l'eau chaude : elles sont recouvertes d'une pellicule collante et amère.","Faites-les griller entières à sec sur une plaque brûlante, avec l'oignon, l'ail en chemise et les jalapeños, en les retournant.","Elles sont prêtes quand la peau noircit par plaques et que la chair s'affaisse — comptez 12 minutes, pas davantage.","Mixez à peine, par à-coups : une salsa verde mixée trop longtemps devient mousseuse et pâle au lieu de rester vert sombre.","Ajoutez la coriandre, le jus de citron vert et le sel hors du mixeur, à la fourchette. Laissez reposer une heure avant de servir."],
     en:["Remove the papery husks from the tomatillos and wash them in hot water: they are covered in a sticky, bitter film.","Roast them whole on a dry scalding griddle with the onion, unpeeled garlic and jalapeños, turning them.","They are ready when the skin blackens in patches and the flesh slumps — allow 12 minutes, no more.","Blend barely, in pulses: a salsa verde blended too long turns foamy and pale instead of staying dark green.","Add the coriander, lime juice and salt outside the blender, with a fork. Rest an hour before serving."]} },

{ id:'california-roll', c:'na', lat:34.050, lon:-118.240, base:4, prep:70, cook:20, diff:3, tags:['sea','fresh','fast'],
  art:{v:'plate',bg:'#2c3440',plate:'#f4f0e6',style:'other',food:['#f4f0e6','#e07a6a','#7fae5a','#3a3a2a'],garnish:'#6fbf8f'},
  n:{fr:'California roll',en:'California roll'},
  p:{fr:'Little Tokyo, Los Angeles, Californie, États-Unis',en:'Little Tokyo, Los Angeles, California, United States'},
  d:{fr:"Un maki roulé à l'envers, riz à l'extérieur, garni de crabe, d'avocat et de concombre. Ichiro Mashita l'inventa dans les années soixante au Tokyo Kaikan pour des Américains rebutés par le poisson cru et par l'algue apparente : le riz à l'extérieur cachait le nori.",
     en:"An inside-out maki, rice outside, filled with crab, avocado and cucumber. Ichiro Mashita invented it in the sixties at the Tokyo Kaikan for Americans put off by raw fish and by visible seaweed: rice on the outside hid the nori."},
  i:[['sushi_rice',300,'g'],['nori',4,'sheet'],['crab_meat',200,'g'],['avocado',1,'pc'],['cucumber',1,'pc'],['rice_vinegar',60,'ml'],['sugar',2,'tbsp'],['sesame_seeds',3,'tbsp'],['mayonnaise',40,'g'],['soy_sauce',60,'ml'],['salt',null,'']],
  s:{fr:["Lavez le riz sept fois jusqu'à ce que l'eau soit claire, cuisez-le et assaisonnez-le au vinaigre sucré en le coupant à la spatule, jamais en remuant.","Étalez le riz froid sur toute la feuille de nori, puis retournez l'ensemble : le nori se retrouve dessous et le riz au contact du tapis.","Couvrez le tapis de film alimentaire avant de retourner, sinon le riz y adhère et le rouleau se déchire.","Alignez le crabe, l'avocat et le concombre sur le tiers inférieur, et roulez en pressant régulièrement, sans écraser.","Roulez le boudin dans les graines de sésame et coupez en huit avec un couteau mouillé, en essuyant la lame entre chaque tranche."],
     en:["Wash the rice seven times until the water runs clear, cook it and season it with sweetened vinegar, cutting it in with a spatula and never stirring.","Spread the cold rice over the whole nori sheet, then turn the lot over: the nori ends up underneath and the rice against the mat.","Cover the mat with cling film before turning, otherwise the rice sticks to it and the roll tears.","Line up the crab, avocado and cucumber along the lower third, and roll pressing evenly, without crushing.","Roll the log in sesame seeds and cut into eight with a wetted knife, wiping the blade between each slice."]} },

{ id:'avocado-toast', c:'na', lat:33.985, lon:-118.470, base:2, prep:15, cook:5, diff:1, tags:['veg','breakfast','fresh'],
  art:{v:'board',bg:'#28331f',plate:'#f4ead4',style:'flat',food:['#7fae5a','#4f8f4a','#e0b45a','#f0e8d0'],garnish:'#6fbf8f'},
  n:{fr:'Avocado toast',en:'Avocado toast'},
  p:{fr:'Venice, Los Angeles, Californie, États-Unis',en:'Venice, Los Angeles, California, United States'},
  d:{fr:"Une tranche de pain au levain couverte d'avocat écrasé, de citron et de flocons de piment. Popularisé à Sydney dans les années 1990, il a explosé à Venice vers 2010 ; la Californie produit presque tout l'avocat américain, et l'écraser à la fourchette plutôt qu'à la moulinette est la seule règle qui compte.",
     en:"A slice of sourdough covered with crushed avocado, lemon and chilli flakes. Popularised in Sydney in the 1990s, it exploded in Venice around 2010; California grows nearly all American avocados, and crushing rather than blending is the one rule that matters."},
  i:[['rustic_bread',2,'slice'],['avocado',1,'pc'],['lemon',1,'pc'],['chili_flakes',1,'tsp'],['olive_oil',20,'ml'],['egg',2,'pc'],['coarse_salt',1,'tsp'],['pepper',null,'']],
  s:{fr:["Choisissez un avocat Hass qui cède sous le pouce près du pédoncule mais reste ferme au milieu : trop mûr, il devient filandreux et gris.","Grillez le pain au levain jusqu'à ce qu'il soit franchement brun : un pain pâle se détrempe sous l'avocat en deux minutes.","Écrasez l'avocat à la fourchette dans un bol, avec le jus de citron et du gros sel, en laissant des morceaux — jamais au mixeur.","Le citron n'est pas là pour le goût mais pour l'oxydation : sans lui l'avocat brunit avant d'arriver à table.","Étalez sur le pain encore chaud, arrosez d'huile d'olive, poivrez, ajoutez les flocons de piment et, si vous voulez, un œuf poché."],
     en:["Choose a Hass avocado that yields under the thumb near the stem but stays firm in the middle: overripe, it turns stringy and grey.","Toast the sourdough until frankly brown: pale bread goes soggy under avocado within two minutes.","Crush the avocado with a fork in a bowl, with lemon juice and coarse salt, leaving pieces — never in a blender.","The lemon is not there for flavour but against oxidation: without it the avocado browns before it reaches the table.","Spread on the still-warm bread, trickle olive oil, pepper, add the chilli flakes and, if you like, a poached egg."]} },

{ id:'sourdough-san-francisco', c:'na', lat:37.808, lon:-122.410, base:8, prep:1440, cook:45, diff:3, tags:['bread','bake','slow'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'roll',food:['#c9924a','#e8dcb8','#f2dfa8','#8f6a4a'],garnish:'#7fae6a'},
  n:{fr:'Pain au levain de San Francisco',en:'San Francisco sourdough'},
  p:{fr:'Fisherman’s Wharf, San Francisco, Californie, États-Unis',en:'Fisherman’s Wharf, San Francisco, California, United States'},
  d:{fr:"Un pain au levain sauvage à la croûte épaisse et à la mie franchement acide. Le levain arriva avec les chercheurs d'or de 1849 ; une bactérie propre à la baie, baptisée Lactobacillus sanfranciscensis, lui donne son acidité, et les mêmes levains tournent depuis le séisme de 1906.",
     en:"A wild-leavened bread with a thick crust and a frankly sour crumb. The starter arrived with the gold rushers of 1849; a bacterium peculiar to the bay, named Lactobacillus sanfranciscensis, gives it its acidity, and the same starters have run since the 1906 earthquake."},
  i:[['sourdough_starter',100,'g'],['flour',400,'g'],['whole_wheat_flour',100,'g'],['water',350,'ml'],['coarse_salt',10,'g']],
  s:{fr:["Rafraîchissez le levain douze heures avant : il doit tripler et retomber légèrement, signe qu'il est à son maximum d'activité.","Mêlez farines et eau seules et laissez-les une heure en autolyse — l'hydratation avant le sel rend la pâte extensible sans pétrissage.","Ajoutez le levain puis le sel, et faites six séries de rabats espacées de trente minutes au lieu de pétrir.","Laissez fermenter 4 heures à 24 °C, façonnez en boule serrée et mettez au froid pour une nuit : c'est le froid qui développe l'acidité.","Cuisez dans une cocotte préchauffée à 250 °C, 20 minutes à couvert puis 25 à découvert à 230 °C. Attendez deux heures avant de couper."],
     en:["Refresh the starter twelve hours ahead: it must triple and just begin to fall, the sign it is at peak activity.","Mix the flours and water alone and leave them an hour to autolyse — hydration before salt makes the dough extensible without kneading.","Add the starter then the salt, and give it six sets of folds thirty minutes apart instead of kneading.","Ferment 4 hours at 24°C, shape into a tight round and chill overnight: it is the cold that develops the acidity.","Bake in a pot preheated to 250°C, 20 minutes covered then 25 uncovered at 230°C. Wait two hours before cutting."]} },

{ id:'in-n-out-double-double', c:'na', lat:34.085, lon:-117.961, base:2, prep:20, cook:10, diff:1, tags:['beef','fast','street'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'roll',food:['#8f5a3a','#e8c46a','#7fae5a','#c9402c'],garnish:'#7fae6a'},
  n:{fr:'Double-Double',en:'Double-Double'},
  p:{fr:'Baldwin Park, Californie, États-Unis',en:'Baldwin Park, California, United States'},
  d:{fr:"Deux galettes fines et deux tranches de fromage dans un pain moelleux, avec une sauce rose. Harry et Esther Snyder ouvrirent le premier drive californien à Baldwin Park en 1948 ; le style animal, oignons caramélisés et galette cuite dans la moutarde, ne figure sur aucune carte depuis soixante ans.",
     en:"Two thin patties and two slices of cheese in a soft bun, with a pink sauce. Harry and Esther Snyder opened California's first drive-through in Baldwin Park in 1948; animal style, with caramelised onions and a mustard-cooked patty, has never appeared on a menu in sixty years."},
  i:[['ground_beef',240,'g'],['bread_roll',1,'pc'],['american_cheese',2,'slice'],['lettuce',1,'pc'],['ripe_tomato',1,'pc'],['onion',1,'pc'],['mayonnaise',40,'g'],['ketchup',20,'g'],['pickles',2,'pc'],['mustard',1,'tsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites la sauce : mayonnaise, ketchup, cornichons hachés très fin et une cuillerée de leur vinaigre, mêlés et laissés une heure au froid.","Formez deux galettes de 60 g et aplatissez-les entre deux films jusqu'à 12 cm de diamètre : elles doivent être plus larges que le pain, car elles se rétractent d'un quart.","Grillez l'intérieur du pain au beurre sur la plaque jusqu'à ce qu'il soit brun : c'est cette couche grillée qui l'empêche de se détremper.","Saisissez les galettes sur une plaque brûlante, 90 secondes par face, et badigeonnez la face crue de moutarde avant de les retourner.","Empilez : sauce, laitue, tomate, oignon, galette, fromage, galette, fromage. Servez dans la minute."],
     en:["Make the sauce: mayonnaise, ketchup, very finely chopped gherkins and a spoonful of their vinegar, mixed and chilled an hour.","Shape two 60 g patties and press them between films to 12 cm across: they must be wider than the bun, because they shrink by a quarter.","Griddle the cut faces of the bun in butter until brown: that toasted layer is what keeps it from going soggy.","Sear the patties on a scalding griddle, 90 seconds a side, brushing the raw face with mustard before turning them.","Stack: sauce, lettuce, tomato, onion, patty, cheese, patty, cheese. Serve within the minute."]} },

{ id:'mission-burrito', c:'na', lat:37.760, lon:-122.419, base:2, prep:40, cook:30, diff:2, tags:['beef','rice','street'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'roll',food:['#f4f0e6','#e0b45a','#8f5a3a','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Mission burrito',en:'Mission burrito'},
  p:{fr:'Mission District, San Francisco, Californie, États-Unis',en:'Mission District, San Francisco, California, United States'},
  d:{fr:"Un burrito géant contenant riz, haricots, viande, fromage, guacamole et crème, enveloppé de papier d'aluminium. Il naquit en 1961 dans le Mission District : la nouveauté fut la tortilla passée à la vapeur, assez souple pour envelopper tout un repas d'un seul tenant.",
     en:"A giant burrito holding rice, beans, meat, cheese, guacamole and sour cream, wrapped in foil. It was born in 1961 in the Mission District: the innovation was the steamed tortilla, supple enough to wrap a whole meal in one piece."},
  i:[['flour_tortillas',2,'pc'],['long_grain_rice',150,'g'],['pinto_beans',150,'g'],['beef_steak',300,'g'],['cheddar_cheese',100,'g'],['avocado',1,'pc'],['sour_cream',80,'g'],['ripe_tomato',2,'pc'],['cilantro',1,'bunch'],['lime',2,'pc'],['jalapeno',1,'pc'],['cumin',1,'tsp'],['salt',null,'']],
  s:{fr:["Faites mariner le steak au citron vert, à l'ail et au cumin une heure, puis grillez-le à feu vif et laissez-le reposer avant de le tailler en dés.","Passez la grande tortilla dix secondes à la vapeur, ou trente secondes dans un torchon humide au micro-ondes : elle doit devenir molle et élastique.","Une tortilla sèche craque au pliage, et un burrito qui craque perd tout, c'est mécanique.","Garnissez en une bande épaisse au centre, riz et haricots au fond pour absorber les jus, viande et éléments humides au-dessus.","Repliez les deux côtés vers l'intérieur, puis roulez en serrant fermement à chaque tour. Enveloppez d'aluminium immédiatement : c'est le papier qui tient l'ensemble."],
     en:["Marinate the steak in lime, garlic and cumin for an hour, then grill it over high heat and rest it before dicing.","Steam the large tortilla for ten seconds, or thirty in a damp cloth in the microwave: it must go soft and elastic.","A dry tortilla cracks when folded, and a burrito that cracks loses everything; it is simple mechanics.","Fill it in a thick band down the centre, rice and beans at the bottom to absorb the juices, meat and wet items above.","Fold both sides inward, then roll, tightening firmly at every turn. Wrap in foil immediately: the foil is what holds it together."]} },

{ id:'cobb-salad', c:'na', lat:34.093, lon:-118.329, base:4, prep:35, cook:20, diff:1, tags:['fresh','poultry','fast'],
  art:{v:'bowl',bg:'#28331f',plate:'#f4f0e6',style:'salad',food:['#7fae5a','#e8c46a','#c9402c','#f4f0e6'],garnish:'#6fbf8f'},
  n:{fr:'Salade Cobb',en:'Cobb salad'},
  p:{fr:'Hollywood, Los Angeles, Californie, États-Unis',en:'Hollywood, Los Angeles, California, United States'},
  d:{fr:"Une salade composée en bandes parallèles de poulet, bacon, œuf, avocat et roquefort. Bob Cobb, patron du Brown Derby, l'improvisa une nuit de 1937 avec ce qui restait au réfrigérateur ; le lendemain, Sid Grauman en commanda une, et elle entra à la carte pour trente ans.",
     en:"A salad composed in parallel stripes of chicken, bacon, egg, avocado and Roquefort. Bob Cobb, who ran the Brown Derby, improvised it one night in 1937 from what was left in the fridge; the next day Sid Grauman ordered one, and it stayed on the menu for thirty years."},
  i:[['lettuce',1,'pc'],['chicken_breast',300,'g'],['smoked_bacon',150,'g'],['egg',3,'pc'],['avocado',1,'pc'],['roquefort_cheese',100,'g'],['cherry_tomato',200,'g'],['chives',3,'tbsp'],['red_wine_vinegar',40,'ml'],['olive_oil',100,'ml'],['dijon_mustard',1,'tsp'],['lemon',1,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Hachez toute la verdure très finement — c'est une salade hachée, non une salade de feuilles entières, et c'est ce qui permet de la manger à la cuillère.","Faites griller le bacon jusqu'à ce qu'il craque, égouttez-le sur du papier et hachez-le une fois froid, sinon il s'écrase.","Cuisez les œufs 9 minutes, rafraîchissez-les à l'eau glacée et hachez-les séparément.","Disposez chaque élément en bande parallèle sur le lit de verdure, sans les mêler : la présentation en rangs est la définition même du plat.","Fouettez la vinaigrette au vinaigre de vin rouge et à la moutarde, et versez-la à table, devant les convives, avant de mélanger."],
     en:["Chop all the greens very finely — this is a chopped salad, not a leaf salad, and that is what lets it be eaten with a spoon.","Grill the bacon until it snaps, drain it on paper and chop it once cold, otherwise it squashes.","Boil the eggs 9 minutes, refresh them in iced water and chop them separately.","Lay each element in a parallel stripe over the bed of greens, without mixing: the arrangement in rows is the definition of the dish.","Whisk a red wine vinegar and mustard dressing, and pour it at the table, in front of your guests, before tossing."]} },

{ id:'french-dip', c:'na', lat:34.058, lon:-118.237, base:4, prep:30, cook:120, diff:2, tags:['beef','comfort','street'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'roll',food:['#8f5a3a','#f2dfa8','#6f4a2a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'French dip',en:'French dip'},
  p:{fr:'Los Angeles, Californie, États-Unis',en:'Los Angeles, California, United States'},
  d:{fr:"Un sandwich de rôti de bœuf dans un pain trempé dans le jus de cuisson, servi avec un bol de jus à part. Deux maisons de Los Angeles s'en disputent l'invention depuis 1908 ; l'une dit qu'un pain tomba dans la lèchefrite, l'autre qu'un client aux gencives douloureuses le demanda ainsi.",
     en:"A roast beef sandwich in a bun dipped in the roasting juices, served with a bowl of jus on the side. Two Los Angeles houses have disputed the invention since 1908; one says a roll fell into the dripping pan, the other that a customer with sore gums asked for it that way."},
  i:[['beef_chuck',1,'kg'],['beef_broth',800,'ml'],['onion',2,'pc'],['garlic',4,'clove'],['thyme',4,'sprig'],['bay_leaf',2,'pc'],['baguette',4,'pc'],['mustard',40,'g'],['gruyere_cheese',150,'g'],['sunflower_oil',30,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Saisissez le rôti sur toutes ses faces, puis braisez-le 2 heures avec l'oignon, l'ail et les herbes dans le bouillon.","Laissez-le refroidir entièrement dans son jus : c'est la seule façon de le trancher assez fin, un rôti chaud s'effiloche sous la lame.","Filtrez le jus, dégraissez-le et gardez-le brûlant : c'est lui le plat, et un jus tiède ruine tout.","Tranchez le bœuf au couteau long, presque translucide, et réchauffez-le trente secondes dans le jus avant de garnir.","Trempez la face coupée du pain dans le jus — le dessus reste sec pour qu'on puisse tenir le sandwich — garnissez et servez un bol de jus à part."],
     en:["Sear the joint on every face, then braise it 2 hours with the onion, garlic and herbs in the broth.","Cool it completely in its juices: the only way to slice it thinly enough, a hot joint shreds under the blade.","Strain the juices, skim them and keep them scalding: they are the dish, and lukewarm jus ruins everything.","Slice the beef with a long knife, almost translucent, and warm it thirty seconds in the jus before filling.","Dip the cut face of the roll in the jus — the top stays dry so the sandwich can be held — fill it and serve a bowl of jus alongside."]} },

{ id:'donuts-glazed-la', c:'na', lat:33.945, lon:-118.371, base:12, prep:150, cook:20, diff:2, tags:['sweet','fry','street'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'roll',food:['#f4f0e6','#e0b45a','#f2dfa8','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Donut glacé de Los Angeles',en:'Los Angeles glazed donut'},
  p:{fr:'Inglewood, Los Angeles, Californie, États-Unis',en:'Inglewood, Los Angeles, California, United States'},
  d:{fr:"Un anneau de pâte levée frit et glacé au sucre, encore tiède. Los Angeles compte plus de boutiques de donuts que toute autre ville américaine, en grande partie tenues par des réfugiés cambodgiens arrivés après 1975 ; le glaçage doit être posé sur un donut chaud, pour qu'il devienne transparent.",
     en:"A ring of yeasted dough fried and sugar-glazed, still warm. Los Angeles has more donut shops than any other American city, largely run by Cambodian refugees who arrived after 1975; the glaze must go onto a hot donut, so that it turns transparent."},
  i:[['flour',400,'g'],['sugar',60,'g'],['egg',2,'pc'],['whole_milk',200,'ml'],['fresh_yeast',15,'g'],['butter',60,'g'],['sunflower_oil',1.5,'l'],['powdered_sugar',300,'g'],['vanilla',1,'pc'],['salt',null,'']],
  s:{fr:["Pétrissez une pâte levée souple avec le lait tiède, la levure, les œufs, le sucre et le sel, puis incorporez le beurre mou.","Laissez lever 1 heure, abaissez à 1 cm et découpez les anneaux à l'emporte-pièce ; ne repétrissez les chutes qu'une seule fois.","Laissez pousser 45 minutes sur des carrés de papier huilé, à découvert : un donut trop poussé s'affaisse dans l'huile.","Frites à 175 °C, 60 secondes par face, en les faisant glisser dans l'huile depuis leur papier pour ne pas les déformer.","Trempez-les dans le glaçage au sucre glace et au lait dès la sortie, encore brûlants : sur un donut froid, le glaçage reste blanc et opaque."],
     en:["Knead a soft yeasted dough with warm milk, yeast, eggs, sugar and salt, then work in the softened butter.","Prove for an hour, roll to 1 cm and cut the rings; re-roll the trimmings once only.","Prove 45 minutes on squares of oiled paper, uncovered: an over-proved donut collapses in the oil.","Fry at 175°C, 60 seconds a side, sliding them into the oil off their paper so as not to distort them.","Dip them in a glaze of icing sugar and milk as they come out, still scalding: on a cold donut the glaze stays white and opaque."]} },

{ id:'cedar-plank-salmon', c:'na', lat:47.609, lon:-122.342, base:4, prep:120, cook:25, diff:2, tags:['sea','grill','fresh'],
  art:{v:'board',bg:'#26384a',plate:'#f4ead4',style:'fish',food:['#e0a8a0','#c9754a','#7fae5a','#f0e8d0'],garnish:'#6fbf8f'},
  n:{fr:'Saumon sur planche de cèdre',en:'Cedar plank salmon'},
  p:{fr:'Pike Place, Seattle, Washington, États-Unis',en:'Pike Place, Seattle, Washington, United States'},
  d:{fr:"Un filet de saumon sockeye cuit sur une planche de cèdre rouge posée sur les braises. Les peuples du Puget Sound pratiquent cette cuisson depuis un millénaire : la planche mouillée fume sans brûler et le bois transmet une résine que ni la marinade ni le fumoir ne reproduisent.",
     en:"A sockeye salmon fillet cooked on a red cedar plank set over coals. The peoples of Puget Sound have cooked this way for a thousand years: the wet plank smoulders without burning and the wood gives a resin no marinade or smoker reproduces."},
  i:[['salmon',800,'g'],['cedar_plank',1,'pc'],['brown_sugar',2,'tbsp'],['dijon_mustard',1,'tbsp'],['dill',1,'bunch'],['lemon',2,'pc'],['olive_oil',30,'ml'],['coarse_salt',1,'tbsp'],['pepper',null,'']],
  s:{fr:["Faites tremper la planche de cèdre au moins 2 heures dans l'eau, lestée d'une assiette : une planche sèche s'enflamme en trois minutes.","Employez uniquement du cèdre rouge non traité, vendu pour la cuisine — les planches de bricolage sont imprégnées de produits.","Salez le saumon une demi-heure à l'avance, épongez-le, puis badigeonnez-le de moutarde et de cassonade.","Posez la planche seule sur les braises jusqu'à ce qu'elle craque et fume, puis retournez-la et couchez le saumon sur la face chaude.","Couvrez et comptez 20 minutes sans jamais retourner le poisson : il est prêt quand la chair se sépare en feuillets sous une pointe. Servez sur la planche."],
     en:["Soak the cedar plank at least 2 hours in water, weighted with a plate: a dry plank catches fire within three minutes.","Use only untreated red cedar sold for cooking — hardware-store boards are impregnated with chemicals.","Salt the salmon half an hour ahead, blot it, then brush it with mustard and brown sugar.","Set the plank alone on the coals until it crackles and smokes, then turn it over and lay the salmon on the hot face.","Cover and allow 20 minutes without ever turning the fish: it is ready when the flesh parts into flakes under a point. Serve on the plank."]} },

{ id:'dungeness-crab', c:'na', lat:47.602, lon:-122.339, base:4, prep:20, cook:20, diff:2, tags:['sea','fast','festive'],
  art:{v:'board',bg:'#26485c',plate:'#f4f0e6',style:'other',food:['#c9532c','#f4f0e6','#e8c46a','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Crabe dormeur du Pacifique',en:'Dungeness crab'},
  p:{fr:'Seattle, Washington, États-Unis',en:'Seattle, Washington, United States'},
  d:{fr:"Un crabe entier bouilli en eau de mer, servi avec du beurre clarifié et du citron. Il porte le nom d'un hameau de l'État de Washington où on le pêchait dès 1848 ; il est devenu crustacé officiel de l'État en 2009, et sa saison va de novembre à juin.",
     en:"A whole crab boiled in seawater, served with clarified butter and lemon. It takes its name from a hamlet in Washington State where it was fished from 1848; it became the state crustacean in 2009, and its season runs November to June."},
  i:[['dungeness_crab',2,'pc'],['coarse_salt',4,'tbsp'],['butter',150,'g'],['lemon',3,'pc'],['garlic',3,'clove'],['parsley',3,'tbsp'],['bay_leaf',2,'pc'],['bread',300,'g']],
  s:{fr:["Achetez-les vivants et vigoureux : un crabe mort depuis plus d'une heure développe une amertume que la cuisson n'efface pas.","Portez une grande eau à 35 g de sel par litre — la salinité de la mer — à ébullition franche avec le laurier.","Plongez les crabes tête la première et comptez 12 minutes pour huit cents grammes, à partir de la reprise de l'ébullition.","Refroidissez-les aussitôt dans l'eau glacée : sans ce choc, ils continuent de cuire dans leur carapace et la chair devient filandreuse.","Détachez le tablier, ouvrez la carapace, ôtez les branchies et cassez les pinces au dos du couteau. Beurre clarifié à l'ail et citron, rien d'autre."],
     en:["Buy them alive and lively: a crab dead more than an hour develops a bitterness cooking does not remove.","Bring a large pot of water salted to 35 g per litre — the salinity of the sea — to a rolling boil with the bay.","Drop the crabs in head first and allow 12 minutes for eight hundred grams, from the return to the boil.","Chill them at once in iced water: without that shock they keep cooking inside the shell and the meat turns stringy.","Pull off the apron, lift the carapace, remove the gills and crack the claws with the back of a knife. Garlic clarified butter and lemon, nothing else."]} },

{ id:'smoked-salmon-chowder', c:'na', lat:47.601, lon:-122.336, base:6, prep:30, cook:40, diff:2, tags:['sea','soup','comfort'],
  art:{v:'bowl',bg:'#26384a',plate:'#f4f0e6',style:'soup',food:['#f4f0e6','#e0a8a0','#e8c46a','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Chowder au saumon fumé',en:'Smoked salmon chowder'},
  p:{fr:'Seattle, Washington, États-Unis',en:'Seattle, Washington, United States'},
  d:{fr:"Une soupe crémeuse au saumon fumé à l'aulne, aux pommes de terre et au maïs. C'est la version du Pacifique Nord-Ouest du chowder de Nouvelle-Angleterre : on y remplace la palourde par le saumon, et l'aulne remplace le hickory du Sud, ce qui donne une fumée plus douce.",
     en:"A creamy soup of alder-smoked salmon, potato and corn. It is the Pacific Northwest version of the New England chowder: salmon replaces the clam, and alder replaces southern hickory, which gives a gentler smoke."},
  i:[['smoked_trout',300,'g'],['potato',400,'g'],['sweetcorn',200,'g'],['onion',1,'pc'],['celery',2,'pc'],['heavy_cream',400,'ml'],['fish_broth',600,'ml'],['butter',60,'g'],['flour',30,'g'],['dill',1,'bunch'],['smoked_bacon',100,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites fondre le lard en dés, retirez-le et faites suer l'oignon et le céleri dans sa graisse, sans coloration.","Singez de farine, laissez cuire deux minutes puis mouillez du bouillon de poisson chaud en fouettant.","Ajoutez les pommes de terre en dés et laissez cuire 15 minutes, jusqu'à ce qu'elles s'écrasent contre la paroi sous la cuillère.","Écrasez un quart des pommes de terre dans la soupe pour la lier : un chowder ne se lie ni à la fécule ni à la crème seule.","Ajoutez la crème, le maïs et le saumon fumé émietté hors du feu, et ne faites plus bouillir — le saumon fumé se rétracte et devient sec en une minute."],
     en:["Render the diced bacon, lift it out and sweat the onion and celery in its fat, without colour.","Dust with flour, cook it two minutes then whisk in the hot fish broth.","Add the diced potatoes and cook 15 minutes, until they crush against the side of the pot under a spoon.","Crush a quarter of the potatoes into the soup to bind it: a chowder is thickened with neither starch nor cream alone.","Add the cream, corn and flaked smoked salmon off the heat, and do not boil again — smoked salmon shrinks and dries within a minute."]} },

{ id:'marionberry-pie', c:'na', lat:45.515, lon:-122.678, base:8, prep:60, cook:55, diff:2, tags:['sweet','bake','fruit'],
  art:{v:'plate',bg:'#2c3440',plate:'#f4ead4',style:'pastry',food:['#5a2a4a','#e0b45a','#f2dfa8','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Tarte aux marionberries',en:'Marionberry pie'},
  p:{fr:'Portland, Oregon, États-Unis',en:'Portland, Oregon, United States'},
  d:{fr:"Une tarte à la mûre marionberry, créée par croisement en 1956 dans le comté de Marion. C'est la baie officieuse de l'Oregon, qui en produit la quasi-totalité mondiale : plus juteuse et plus acide que la mûre commune, elle exige davantage d'épaississant qu'aucune autre.",
     en:"A pie of marionberry, a blackberry bred in 1956 in Marion County. It is Oregon's unofficial berry, and the state grows nearly the world's entire crop: juicier and sharper than a common blackberry, it needs more thickener than any other."},
  i:[['blackberries',700,'g'],['shortcrust_pastry',600,'g'],['sugar',150,'g'],['tapioca',30,'g'],['lemon',1,'pc'],['butter',30,'g'],['egg_yolk',1,'pc'],['salt',null,'']],
  s:{fr:["Mêlez les baies au sucre, au tapioca et au jus de citron, et laissez macérer 30 minutes pour que le tapioca s'hydrate.","Le tapioca vaut mieux que la fécule pour cette baie : il supporte les longues cuissons acides sans se liquéfier, ce que la fécule de maïs ne fait pas.","Garnissez le fond de pâte en dôme, parsemez de beurre et couvrez d'un treillis de bandes plutôt que d'un disque plein.","Le treillis n'est pas décoratif : cette baie rend tant de jus qu'il faut le laisser s'évaporer en cuisant.","Cuisez 15 minutes à 220 °C puis 40 minutes à 190 °C, jusqu'à ce que le jus bouillonne au centre et non seulement aux bords. Refroidissez 4 heures."],
     en:["Mix the berries with the sugar, tapioca and lemon juice, and macerate 30 minutes so the tapioca hydrates.","Tapioca beats cornstarch for this berry: it survives long acidic cooking without breaking down, which cornstarch does not.","Fill the pastry case in a dome, dot with butter and cover with a lattice of strips rather than a solid disc.","The lattice is not decorative: this berry gives up so much juice that it must be allowed to evaporate as it bakes.","Bake 15 minutes at 220°C then 40 minutes at 190°C, until the juice bubbles at the centre and not only at the edges. Cool 4 hours."]} },

{ id:'seattle-teriyaki', c:'na', lat:47.615, lon:-122.320, base:4, prep:90, cook:25, diff:2, tags:['poultry','grill','fast'],
  art:{v:'plate',bg:'#33291f',plate:'#f4f0e6',style:'grill',food:['#6f4a2a','#f4f0e6','#7fae5a','#e0b45a'],garnish:'#7fae6a'},
  n:{fr:'Teriyaki de Seattle',en:'Seattle teriyaki'},
  p:{fr:'Seattle, Washington, États-Unis',en:'Seattle, Washington, United States'},
  d:{fr:"Des cuisses de poulet grillées et laquées, servies sur du riz avec une salade de chou. Toshihiro Nakae ouvrit Toshi's en 1976 et créa ce format : la ville compte aujourd'hui plusieurs centaines de boutiques de teriyaki, un plat de Seattle plus que du Japon.",
     en:"Grilled, lacquered chicken thighs served on rice with a cabbage salad. Toshihiro Nakae opened Toshi's in 1976 and created the format: the city now has several hundred teriyaki shops, a Seattle dish more than a Japanese one."},
  i:[['chicken_thighs',700,'g'],['soy_sauce',120,'ml'],['sugar',60,'g'],['mirin',60,'ml'],['garlic',4,'clove'],['ginger',30,'g'],['long_grain_rice',300,'g'],['green_cabbage',300,'g'],['carrot',1,'pc'],['rice_vinegar',30,'ml'],['sesame_oil',10,'ml'],['salt',null,'']],
  s:{fr:["Employez des cuisses désossées avec la peau : le blanc sèche et le teriyaki de Seattle ne se fait pas autrement.","Faites réduire soja, sucre, mirin, ail et gingembre de moitié : la sauce doit napper le dos d'une cuillère, sinon elle glisse sur la viande.","Marinez le poulet une heure dans un tiers de cette sauce, et gardez le reste pour laquer.","Grillez peau vers le bas d'abord, à feu moyen, dix minutes, sans badigeonner : le sucre brûlerait avant que la chair soit cuite.","Ne laquez que dans les trois dernières minutes, en deux couches. Servez sur du riz, avec un chou râpé au vinaigre de riz."],
     en:["Use boneless thighs with the skin: breast dries out and Seattle teriyaki is not made otherwise.","Reduce the soy, sugar, mirin, garlic and ginger by half: the sauce must coat the back of a spoon, or it slides off the meat.","Marinate the chicken an hour in a third of that sauce, and keep the rest for lacquering.","Grill skin down first over medium heat for ten minutes, without basting: the sugar would burn before the flesh cooked.","Lacquer only in the last three minutes, in two coats. Serve on rice, with cabbage shredded and dressed with rice vinegar."]} },

{ id:'spam-musubi', c:'na', lat:21.305, lon:-157.860, base:4, prep:40, cook:20, diff:1, tags:['pork','rice','street'],
  art:{v:'board',bg:'#2c3440',plate:'#f4f0e6',style:'other',food:['#e0a8a0','#f4f0e6','#3a3a2a','#c9754a'],garnish:'#6fbf8f'},
  n:{fr:'Spam musubi',en:'Spam musubi'},
  p:{fr:'Honolulu, Hawaï, États-Unis',en:'Honolulu, Hawaii, United States'},
  d:{fr:"Une tranche de Spam laquée posée sur un bloc de riz et ceinturée d'algue nori. Le Spam arriva avec les rations de l'armée pendant la guerre du Pacifique et n'est jamais reparti : Hawaï en consomme plus par habitant que tout autre État, et Barbara Funamura mit au point ce format vers 1980.",
     en:"A lacquered slice of Spam on a block of rice, belted with nori. Spam arrived with army rations during the Pacific war and never left: Hawaii eats more of it per head than any other state, and Barbara Funamura settled this format around 1980."},
  i:[['spam',1,'can'],['sushi_rice',400,'g'],['nori',3,'sheet'],['soy_sauce',60,'ml'],['sugar',3,'tbsp'],['mirin',30,'ml'],['sesame_seeds',2,'tbsp'],['salt',null,'']],
  s:{fr:["Cuisez le riz à sushi et laissez-le tiédir sans le vinaigrer : à Hawaï le riz du musubi est nature, seul le Spam est assaisonné.","Taillez le Spam en huit tranches d'un centimètre et faites-les griller à sec jusqu'à ce que les bords brunissent et croustillent.","Déglacez la poêle au soja, au sucre et au mirin, et laissez le sirop enrober chaque tranche 2 minutes par face.","Employez la boîte de Spam vide comme moule : tassez le riz au fond, posez la tranche dessus, et démoulez d'un coup.","Ceinturez d'une bande de nori en humectant l'extrémité pour la coller. Se mange à la main, tiède ou froid, dans les six heures."],
     en:["Cook the sushi rice and let it cool without vinegar: in Hawaii the musubi rice is plain, only the Spam is seasoned.","Cut the Spam into eight one-centimetre slices and griddle them dry until the edges brown and crisp.","Deglaze the pan with soy, sugar and mirin, and let the syrup coat each slice 2 minutes a side.","Use the empty Spam tin as a mould: press the rice into the bottom, set the slice on top, and push it out in one movement.","Belt it with a strip of nori, damping the end to stick it. Eaten by hand, warm or cold, within six hours."]} },

{ id:'loco-moco', c:'na', lat:19.730, lon:-155.090, base:4, prep:25, cook:30, diff:1, tags:['beef','rice','comfort'],
  art:{v:'bowl',bg:'#33291f',plate:'#f4f0e6',style:'other',food:['#8f5a3a','#f4f0e6','#e8c46a','#6f4a2a'],garnish:'#7fae6a'},
  n:{fr:'Loco moco',en:'Loco moco'},
  p:{fr:'Hilo, Hawaï, États-Unis',en:'Hilo, Hawaii, United States'},
  d:{fr:"Un bol de riz surmonté d'un steak haché, d'un œuf au plat et d'une sauce brune à l'oignon. Inventé en 1949 au Lincoln Grill de Hilo pour des adolescents affamés au sortir du surf, qui voulaient autre chose qu'un sandwich et n'avaient pas de quoi payer un vrai repas.",
     en:"A bowl of rice topped with a beef patty, a fried egg and brown onion gravy. Invented in 1949 at the Lincoln Grill in Hilo for hungry teenagers coming off the surf, who wanted something other than a sandwich and could not afford a proper meal."},
  i:[['ground_beef',600,'g'],['long_grain_rice',300,'g'],['egg',4,'pc'],['onion',2,'pc'],['beef_broth',400,'ml'],['flour',30,'g'],['butter',50,'g'],['soy_sauce',20,'ml'],['worcestershire',1,'tbsp'],['spring_onion',3,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Cuisez un riz blanc court et collant, plus humide qu'un riz pilaf : il doit se tenir en dôme dans le bol et boire la sauce.","Formez des galettes épaisses de 150 g sans tasser, et creusez le centre au pouce pour qu'elles ne gonflent pas en cuisant.","Saisissez-les 4 minutes par face, retirez-les et faites blondir l'oignon dans la graisse rendue, 15 minutes.","Singez de farine, mouillez du bouillon, ajoutez soja et worcestershire, et laissez épaissir jusqu'à napper.","Montez : riz, galette, sauce, puis l'œuf au plat au dernier moment, jaune coulant. C'est le jaune qui lie tout dans le bol."],
     en:["Cook a short, sticky white rice, wetter than a pilaf: it must hold a dome in the bowl and drink the gravy.","Shape thick 150 g patties without packing, and press a hollow in the centre with your thumb so they do not dome as they cook.","Sear them 4 minutes a side, lift them out and soften the onion in the rendered fat for 15 minutes.","Dust with flour, moisten with broth, add soy and Worcestershire, and let it thicken to a coating consistency.","Build: rice, patty, gravy, then the fried egg at the last moment, yolk runny. It is the yolk that binds everything in the bowl."]} },

{ id:'shave-ice-hawaienne', c:'na', lat:21.593, lon:-158.103, base:4, prep:20, cook:10, diff:1, tags:['sweet','fresh','fast'],
  art:{v:'glass',bg:'#2c3440',plate:'#f4f0e6',style:'other',food:['#e07a9a','#e8c46a','#7fae5a','#f4f0e6'],garnish:'#c9754a'},
  n:{fr:'Shave ice hawaïenne',en:'Hawaiian shave ice'},
  p:{fr:'Haleiwa, Oahu, Hawaï, États-Unis',en:'Haleiwa, Oahu, Hawaii, United States'},
  d:{fr:"De la glace rasée en flocons, arrosée de sirops de fruits tropicaux, sur une boule de glace et des haricots azuki. Les ouvriers japonais des plantations l'apportèrent vers 1900 sous le nom de kakigori ; la glace est rasée, jamais pilée, et c'est toute la différence.",
     en:"Ice shaved into flakes, doused with tropical fruit syrups, over a scoop of ice cream and azuki beans. Japanese plantation workers brought it around 1900 as kakigori; the ice is shaved, never crushed, and that is the whole difference."},
  i:[['ice',1,'kg'],['sugar',300,'g'],['water',300,'ml'],['passion_fruit',4,'pc'],['mango',1,'pc'],['lychee',200,'g'],['condensed_milk',150,'g'],['azuki_beans',150,'g'],['vanilla_ice_cream',200,'g'],['lime',1,'pc']],
  s:{fr:["Faites un sirop simple à parts égales de sucre et d'eau, divisez-le en trois et parfumez chaque part d'un fruit différent, mixé et filtré.","Laissez les sirops refroidir entièrement : versés tièdes sur la glace, ils la font fondre avant d'arriver à table.","Congelez un bloc d'eau et non des glaçons : c'est un bloc qu'on rase, et des glaçons donnent des éclats au lieu de flocons.","Rasez la glace en couches très fines et entassez-la sans tasser, en dôme haut : la neige doit rester aérienne et fondre au contact de la langue.","Posez la boule de glace et les haricots azuki au fond du gobelet, sous la neige, et versez les sirops en trois secteurs. Lait concentré par-dessus."],
     en:["Make a simple syrup of equal sugar and water, divide it in three and flavour each part with a different fruit, blended and strained.","Cool the syrups completely: poured warm over the ice they melt it before it reaches the table.","Freeze a block of water rather than cubes: it is a block that is shaved, and cubes give shards instead of flakes.","Shave the ice in very thin layers and pile it without pressing, into a high dome: the snow must stay airy and melt on the tongue.","Set the scoop of ice cream and the azuki beans at the bottom of the cup, under the snow, and pour the syrups in three sectors. Condensed milk over the top."]} },

{ id:'malasada-hawaienne', c:'na', lat:21.290, lon:-157.822, base:12, prep:150, cook:20, diff:2, tags:['sweet','fry','street'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'roll',food:['#e0b45a','#f2dfa8','#c9924a','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Malasada hawaïenne',en:'Hawaiian malasada'},
  p:{fr:'Honolulu, Hawaï, États-Unis',en:'Honolulu, Hawaii, United States'},
  d:{fr:"Un beignet portugais sans trou ni garniture, roulé dans le sucre. Les ouvriers madériens et açoriens l'apportèrent aux plantations dès 1878 ; on le mangeait le mardi gras pour vider les réserves de saindoux, et Honolulu appelle encore ce jour-là le Malasada Day.",
     en:"A Portuguese doughnut with no hole and no filling, rolled in sugar. Madeiran and Azorean workers brought it to the plantations from 1878; it was eaten on Shrove Tuesday to use up the lard, and Honolulu still calls that day Malasada Day."},
  i:[['flour',400,'g'],['sugar',180,'g'],['egg',3,'pc'],['whole_milk',200,'ml'],['fresh_yeast',20,'g'],['butter',60,'g'],['sunflower_oil',1.5,'l'],['lemon_zest',1,'pc'],['salt',null,'']],
  s:{fr:["Délayez la levure dans le lait tiède avec une cuillerée de sucre et attendez qu'elle mousse franchement.","Pétrissez avec la farine, les œufs, 60 g de sucre, le zeste et le sel 15 minutes, puis incorporez le beurre mou.","La pâte doit rester très molle et collante : c'est ce qui donne la mie filante, et l'on travaille les mains huilées.","Laissez lever 1 h 30, prélevez des boules à la cuillère huilée sans les façonner — une malasada est irrégulière par définition.","Frites 90 secondes par face à 175 °C et roulez-les dans le sucre restant tant qu'elles sont brûlantes. Se mangent dans l'heure."],
     en:["Dissolve the yeast in warm milk with a spoonful of sugar and wait until it foams properly.","Knead with the flour, eggs, 60 g of the sugar, the zest and salt for 15 minutes, then work in the softened butter.","The dough must stay very soft and sticky: that is what gives the stringy crumb, and it is handled with oiled hands.","Prove 1½ hours, scoop out balls with an oiled spoon without shaping them — a malasada is irregular by definition.","Fry 90 seconds a side at 175°C and roll them in the remaining sugar while scalding. Eaten within the hour."]} },

{ id:'huli-huli-chicken', c:'na', lat:21.312, lon:-157.865, base:6, prep:250, cook:60, diff:2, tags:['poultry','grill','festive'],
  art:{v:'board',bg:'#2b2419',plate:'#f0e4c8',style:'grill',food:['#c9754a','#8f5a3a','#e0b45a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Huli huli chicken',en:'Huli huli chicken'},
  p:{fr:'Honolulu, Hawaï, États-Unis',en:'Honolulu, Hawaii, United States'},
  d:{fr:"Un poulet mariné au soja, à l'ananas et au gingembre, grillé entre deux grilles qu'on retourne sans cesse. Ernest Morgado le créa en 1955 pour une collecte de fonds agricole ; huli veut dire tourner en hawaïen, et le cuisinier le criait pour que les aides retournent les grilles en même temps.",
     en:"A chicken marinated in soy, pineapple and ginger, grilled between two racks turned over and over. Ernest Morgado created it in 1955 for a farm fundraiser; huli means turn in Hawaiian, and the cook shouted it so the helpers flipped the racks together."},
  i:[['chicken',1.5,'kg'],['soy_sauce',100,'ml'],['ketchup',80,'ml'],['brown_sugar',60,'g'],['pineapple_juice',150,'ml'],['ginger',40,'g'],['garlic',6,'clove'],['sesame_oil',15,'ml'],['rice_vinegar',30,'ml'],['spring_onion',4,'pc'],['salt',null,'']],
  s:{fr:["Fendez le poulet en crapaudine en retirant l'échine : à plat, il cuit uniformément entre deux grilles.","Mêlez soja, ketchup, cassonade, jus d'ananas, gingembre râpé et ail, et prélevez un tiers pour laquer.","Marinez trois heures au maximum : l'ananas contient une enzyme qui dissout les protéines, et une nuit entière transformerait la chair en bouillie.","Grillez à chaleur indirecte, os vers le bas d'abord, en retournant toutes les cinq minutes pendant quarante minutes.","Ne badigeonnez que dans les dix dernières minutes, en trois couches, en retournant à chaque fois : appliqué trop tôt, le sucre carbonise."],
     en:["Spatchcock the chicken by removing the backbone: laid flat, it cooks evenly between two racks.","Mix the soy, ketchup, brown sugar, pineapple juice, grated ginger and garlic, and set aside a third for glazing.","Marinate three hours at most: pineapple holds an enzyme that dissolves protein, and a whole night would turn the flesh to mush.","Grill over indirect heat, bone side down first, turning every five minutes for forty minutes.","Baste only in the last ten minutes, in three coats, turning each time: applied earlier, the sugar carbonises."]} },

{ id:'saimin', c:'na', lat:21.300, lon:-157.850, base:4, prep:40, cook:180, diff:2, tags:['noodles','soup','comfort'],
  art:{v:'bowl',bg:'#33291f',plate:'#f0e4c8',style:'noodle',food:['#e8dcb8','#c9754a','#7fae5a','#f4f0e6'],garnish:'#7fae6a'},
  n:{fr:'Saimin',en:'Saimin'},
  p:{fr:'Honolulu, Hawaï, États-Unis',en:'Honolulu, Hawaii, United States'},
  d:{fr:"Une soupe de nouilles au bouillon de dashi et de porc, garnie de char siu, d'œuf et de kamaboko. Elle est née dans les camps de plantation où Japonais, Chinois, Philippins et Portugais partageaient les cuisines : personne ne peut en revendiquer l'origine, et c'est exactement ce qu'elle raconte.",
     en:"A noodle soup in dashi and pork broth, topped with char siu, egg and kamaboko. It was born in the plantation camps where Japanese, Chinese, Filipinos and Portuguese shared kitchens: nobody can claim its origin, which is precisely what it says."},
  i:[['ramen_noodles',400,'g'],['pork_bones',500,'g'],['dried_shrimp',20,'g'],['kombu',15,'g'],['char_siu',200,'g'],['egg',2,'pc'],['kamaboko',150,'g'],['spring_onion',5,'pc'],['soy_sauce',40,'ml'],['ginger',20,'g'],['salt',null,'']],
  s:{fr:["Faites blanchir les os de porc cinq minutes, jetez l'eau et rincez-les : c'est ce qui donne un bouillon clair au lieu d'un bouillon gris.","Remettez-les à l'eau froide avec le gingembre et laissez frémir 2 h 30 sans jamais bouillir.","Faites tremper le kombu et les crevettes séchées à froid pendant ce temps, et ne les chauffez qu'à 60 °C en fin de cuisson.","Un kombu porté à ébullition devient visqueux et amer : il se retire dès que l'eau frémit, c'est la règle du dashi.","Réunissez les deux bouillons, assaisonnez au soja, et versez sur des nouilles cuites à part. Garnissez de char siu, d'œuf, de kamaboko et d'oignon vert."],
     en:["Blanch the pork bones five minutes, throw the water away and rinse them: that is what gives a clear broth instead of a grey one.","Return them to cold water with the ginger and simmer 2½ hours without ever boiling.","Meanwhile soak the kombu and dried shrimp cold, and heat them only to 60°C at the end.","Kombu brought to the boil turns slimy and bitter: it is lifted out the moment the water trembles, the rule of dashi.","Combine both broths, season with soy, and pour over noodles cooked separately. Top with char siu, egg, kamaboko and spring onion."]} },

{ id:'japadog', c:'na', lat:49.283, lon:-123.121, base:4, prep:25, cook:15, diff:1, tags:['pork','street','fast'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'roll',food:['#8f5a3a','#f4f0e6','#4f6f3a','#e0b45a'],garnish:'#7fae6a'},
  n:{fr:'Japadog',en:'Japadog'},
  p:{fr:'Vancouver, Colombie-Britannique, Canada',en:'Vancouver, British Columbia, Canada'},
  d:{fr:"Un hot-dog garni à la japonaise : mayonnaise japonaise, sauce teriyaki, radis daikon râpé et algue nori émincée. Un couple d'immigrés japonais ouvrit son chariot sur Burrard Street en 2005 ; la file d'attente qu'ils créèrent a fait naître une demi-douzaine d'imitateurs dans la ville.",
     en:"A hot dog dressed the Japanese way: Japanese mayonnaise, teriyaki sauce, grated daikon and shredded nori. A Japanese couple opened their cart on Burrard Street in 2005; the queue they created has spawned half a dozen imitators in the city."},
  i:[['pork_sausage',4,'pc'],['hot_dog_buns',4,'pc'],['mayonnaise',80,'g'],['soy_sauce',40,'ml'],['sugar',20,'g'],['mirin',20,'ml'],['daikon',150,'g'],['nori',1,'sheet'],['spring_onion',3,'pc'],['sesame_seeds',1,'tbsp'],['salt',null,'']],
  s:{fr:["Faites réduire le soja, le sucre et le mirin de moitié pour obtenir une sauce teriyaki qui nappe : trop liquide, elle coule au fond du pain.","Râpez le daikon au dernier moment et pressez-le légèrement — non essoré, il détrempe le pain en deux minutes.","Grillez les saucisses à la plaque plutôt qu'à l'eau : le japadog se distingue par la peau croustillante, contrairement au hot-dog nord-américain classique.","Réchauffez les pains à la vapeur, puis garnissez dans cet ordre : mayonnaise, saucisse, teriyaki, daikon.","Terminez par le nori taillé en fils très fins et les graines de sésame. L'algue doit rester sèche : ajoutée sous la sauce, elle devient molle."],
     en:["Reduce the soy, sugar and mirin by half to a teriyaki that coats: too thin and it runs to the bottom of the bun.","Grate the daikon at the last moment and press it lightly — undrained, it soaks the bread within two minutes.","Griddle the sausages rather than boiling them: a japadog is known by its crisp skin, unlike the classic North American hot dog.","Steam the buns, then dress in this order: mayonnaise, sausage, teriyaki, daikon.","Finish with nori cut into fine threads and sesame seeds. The seaweed must stay dry: put under the sauce, it goes limp."]} },

{ id:'bison-burger', c:'na', lat:51.045, lon:-114.057, base:4, prep:25, cook:12, diff:2, tags:['beef','grill','fast'],
  art:{v:'board',bg:'#2b2419',plate:'#f4ead4',style:'roll',food:['#6f4a3a','#e8c46a','#7fae5a','#c9402c'],garnish:'#7fae6a'},
  n:{fr:'Burger de bison',en:'Bison burger'},
  p:{fr:'Calgary, Alberta, Canada',en:'Calgary, Alberta, Canada'},
  d:{fr:"Un burger de bison des Prairies, viande maigre et légèrement sucrée. Le bison a nourri les Premières Nations pendant des millénaires avant d'être exterminé à la fin du XIXᵉ siècle ; les troupeaux reconstitués de l'Alberta en fournissent aujourd'hui, et sa maigreur impose une cuisson courte.",
     en:"A burger of prairie bison, a lean and faintly sweet meat. Bison fed the First Nations for millennia before being wiped out in the late 19th century; Alberta's rebuilt herds now supply it, and its leanness demands short cooking."},
  i:[['bison',500,'g'],['bread_roll',4,'pc'],['onion',1,'pc'],['cheddar_cheese',100,'g'],['lettuce',1,'pc'],['ripe_tomato',2,'pc'],['pickles',4,'pc'],['butter',40,'g'],['mustard',20,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Le bison ne contient que deux à trois pour cent de gras : mêlez-lui une cuillerée de beurre fondu froid par galette, ou il sera sec.","Formez les galettes sans tasser et creusez le centre au pouce pour qu'elles ne se bombent pas.","Saisissez-les sur une plaque brûlante 3 minutes par face, pas davantage : à point, le bison est encore bon ; bien cuit, il est irrécupérable.","N'appuyez jamais à la spatule — le peu de jus qu'il contient partirait d'un coup.","Laissez reposer 3 minutes avant de garnir, le temps que le jus se redistribue, et montez le burger sur un pain grillé au beurre."],
     en:["Bison holds only two or three per cent fat: mix a spoonful of cold melted butter into each patty, or it will be dry.","Shape the patties without packing and press a hollow in the centre so they do not dome.","Sear them on a scalding griddle 3 minutes a side, no longer: medium, bison is still good; well done, it is beyond saving.","Never press with a spatula — the little juice it holds would go at once.","Rest 3 minutes before assembling, while the juices redistribute, and build the burger on a butter-toasted bun."]} },

{ id:'green-onion-cake', c:'na', lat:53.546, lon:-113.494, base:6, prep:70, cook:20, diff:2, tags:['veg','fry','street'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'flat',food:['#e0b45a','#7fae5a','#f2dfa8','#c9924a'],garnish:'#6fbf8f'},
  n:{fr:'Green onion cake',en:'Green onion cake'},
  p:{fr:'Edmonton, Alberta, Canada',en:'Edmonton, Alberta, Canada'},
  d:{fr:"Une galette feuilletée à l'oignon vert, frite à la poêle et coupée en parts. Siu To l'introduisit à Edmonton en 1979 ; la ville l'a adoptée au point d'en faire son plat officieux, et l'on en vend à chaque festival albertain depuis quarante ans.",
     en:"A layered spring onion pancake, pan-fried and cut into wedges. Siu To introduced it to Edmonton in 1979; the city adopted it so completely that it became its unofficial dish, and it has been sold at every Alberta festival for forty years."},
  i:[['flour',500,'g'],['warm_water',300,'ml'],['spring_onion',10,'pc'],['sunflower_oil',150,'ml'],['sesame_oil',20,'ml'],['soy_sauce',40,'ml'],['rice_vinegar',20,'ml'],['salt',null,'']],
  s:{fr:["Versez l'eau bouillante sur la farine et travaillez à la cuillère : c'est une pâte échaudée, qui devient extensible et ne se déchire pas à l'étirage.","Pétrissez cinq minutes une fois tiède, puis laissez reposer une heure sous un linge humide.","Abaissez très fin, badigeonnez d'huile et couvrez d'oignon vert émincé, puis roulez en boudin serré dans la longueur.","Enroulez le boudin sur lui-même en escargot et écrasez-le doucement : c'est cette spirale, et non un feuilletage au beurre, qui crée les couches.","Poêlez à l'huile 4 minutes par face à feu moyen, puis écrasez la galette entre deux spatules pour séparer les feuillets. Servez avec une sauce soja-vinaigre."],
     en:["Pour boiling water onto the flour and work it with a spoon: this is a scalded dough, which turns extensible and will not tear when stretched.","Knead five minutes once cool enough, then rest an hour under a damp cloth.","Roll very thin, brush with oil and cover with sliced spring onion, then roll it up tightly lengthwise.","Coil the rope into a spiral and press it gently flat: that spiral, not butter lamination, is what creates the layers.","Fry in oil 4 minutes a side over medium heat, then crush the cake between two spatulas to separate the leaves. Serve with a soy and vinegar dip."]} },

{ id:'fat-boy-winnipeg', c:'na', lat:49.895, lon:-97.138, base:4, prep:30, cook:20, diff:1, tags:['beef','street','fast'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'roll',food:['#8f5a3a','#c9532c','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Fat boy de Winnipeg',en:'Winnipeg fat boy'},
  p:{fr:'Winnipeg, Manitoba, Canada',en:'Winnipeg, Manitoba, Canada'},
  d:{fr:"Un burger noyé d'une sauce à la viande et au chili, avec du chou et de la mayonnaise. Il naquit dans les cafés grecs de Winnipeg dans les années soixante ; la sauce, épaisse et cuminée, se sert à la louche et le sandwich s'emballe aussitôt dans du papier pour qu'il tienne.",
     en:"A burger drowned in a chilli meat sauce, with shredded cabbage and mayonnaise. It came out of Winnipeg's Greek cafés in the sixties; the sauce, thick and cumin-scented, is ladled on and the sandwich wrapped in paper at once so it holds together."},
  i:[['ground_beef',600,'g'],['bread_roll',4,'pc'],['onion',2,'pc'],['tomato_paste',3,'tbsp'],['chili_powder',1,'tbsp'],['cumin',1,'tsp'],['beef_broth',300,'ml'],['green_cabbage',200,'g'],['mayonnaise',80,'g'],['cheddar_cheese',100,'g'],['sunflower_oil',20,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Pour la sauce, délayez la moitié du bœuf haché cru dans le bouillon froid avant de chauffer : la viande reste en grains fins et la sauce n'est pas grasse.","Ajoutez l'oignon râpé, le concentré, le chili et le cumin, et laissez mijoter 45 minutes jusqu'à ce qu'elle nappe la louche.","Formez des galettes plates avec le reste du bœuf et saisissez-les sur une plaque brûlante, 3 minutes par face.","Émincez le chou très finement et mêlez-le à la mayonnaise juste avant de servir — préparé d'avance, il rend son eau.","Montez : pain grillé, mayonnaise, galette, fromage, une bonne louche de sauce, chou. Enveloppez de papier et laissez une minute avant de mordre."],
     en:["For the sauce, whisk half the raw minced beef into cold broth before heating: the meat stays in fine grains and the sauce is not greasy.","Add the grated onion, tomato purée, chilli and cumin, and simmer 45 minutes until it coats the ladle.","Shape flat patties from the remaining beef and sear them on a scalding griddle, 3 minutes a side.","Shred the cabbage very finely and mix it with the mayonnaise just before serving — made ahead, it weeps.","Build: toasted bun, mayonnaise, patty, cheese, a good ladle of sauce, cabbage. Wrap in paper and wait a minute before biting."]} },

{ id:'honey-dill-sauce', c:'na', lat:49.900, lon:-97.145, base:6, prep:10, cook:0, diff:1, tags:['fast','fresh','comfort'],
  art:{v:'bowl',bg:'#33291f',plate:'#f4f0e6',style:'other',food:['#f4f0e6','#e8c46a','#7fae5a','#f0e8d0'],garnish:'#6fbf8f'},
  n:{fr:'Sauce miel-aneth',en:'Honey dill sauce'},
  p:{fr:'Winnipeg, Manitoba, Canada',en:'Winnipeg, Manitoba, Canada'},
  d:{fr:"Une sauce de mayonnaise, de miel et d'aneth, servie avec les croquettes de poulet et les frites. Elle est propre au Manitoba au point d'être inconnue à deux provinces de là : les Manitobains découvrent souvent en voyageant qu'elle n'existe nulle part ailleurs.",
     en:"A sauce of mayonnaise, honey and dill, served with chicken fingers and chips. It is so particular to Manitoba as to be unknown two provinces away: Manitobans often discover while travelling that it exists nowhere else."},
  i:[['mayonnaise',200,'g'],['honey',50,'ml'],['dill',3,'tbsp'],['garlic_powder',1,'tsp'],['lemon',1,'pc'],['white_vinegar',1,'tsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Employez de l'aneth frais et non séché : séché, il n'apporte qu'une amertume herbacée et aucune fraîcheur.","Hachez-le très finement au couteau, sans les tiges dures, et laissez-le une minute sur la planche pour qu'il libère son huile.","Tiédissez à peine le miel pour qu'il se mêle sans grumeaux — chauffé au-delà de 40 °C, il perd son parfum.","Mêlez à la mayonnaise avec l'ail en poudre, une pointe de vinaigre et le jus de citron, en fouettant à la fourchette.","Laissez reposer 4 heures au froid : la sauce est plate le premier quart d'heure et juste ensuite. Elle se garde une semaine."],
     en:["Use fresh dill and not dried: dried, it brings only a grassy bitterness and no freshness at all.","Chop it very finely by knife, without the tough stems, and leave it a minute on the board to release its oil.","Warm the honey barely so it blends without lumps — heated above 40°C it loses its scent.","Mix into the mayonnaise with the garlic powder, a touch of vinegar and the lemon juice, whisking with a fork.","Rest 4 hours in the cold: the sauce is flat for the first quarter of an hour and right afterwards. It keeps a week."]} },

{ id:'pickered-fish', c:'na', lat:50.633, lon:-96.990, base:6, prep:60, cook:20, diff:2, tags:['sea','fresh','slow'],
  art:{v:'bowl',bg:'#26384a',plate:'#f4f0e6',style:'fish',food:['#f4f0e6','#e0b45a','#7fae5a','#f0e8d0'],garnish:'#6fbf8f'},
  n:{fr:'Poisson mariné islandais du Manitoba',en:'Manitoba pickled fish'},
  p:{fr:'Gimli, Manitoba, Canada',en:'Gimli, Manitoba, Canada'},
  d:{fr:"Du doré ou du brochet du lac Winnipeg mariné au vinaigre sucré, aux oignons et aux baies de genièvre. Gimli fut fondée en 1875 par des Islandais fuyant une éruption volcanique ; ils y ont recréé leur conservation du poisson, et la colonie reste la plus grande communauté islandaise hors d'Islande.",
     en:"Walleye or pike from Lake Winnipeg pickled in sweetened vinegar with onions and juniper. Gimli was founded in 1875 by Icelanders fleeing a volcanic eruption; they recreated their fish curing there, and the settlement remains the largest Icelandic community outside Iceland."},
  i:[['pike',500,'g'],['white_vinegar',250,'ml'],['sugar',100,'g'],['mustard_seeds',1,'tbsp'],['juniper_berries',10,'pc'],['onion',2,'pc'],['bay_leaf',3,'pc'],['coarse_salt',60,'g'],['water',150,'ml'],['black_peppercorns',10,'pc'],['rye_bread',300,'g']],
  s:{fr:["Levez les filets et retirez toutes les arêtes intramusculaires à la pince : le brochet en compte des rangées entières, et une seule gâche le plat.","Salez-les à sec 12 heures au froid, puis rincez-les et laissez-les tremper 2 heures à l'eau claire.","Portez le vinaigre, l'eau, le sucre et les épices à ébullition, puis laissez refroidir entièrement — une marinade chaude cuirait le poisson en blanc et le rendrait cotonneux.","Taillez les filets en morceaux de 4 cm et alternez-les dans un bocal avec les rondelles d'oignon.","Couvrez de marinade froide et laissez au réfrigérateur cinq jours au minimum. Se garde un mois et s'accompagne de pain de seigle."],
     en:["Fillet the fish and pull every pin bone with tweezers: pike has whole rows of them, and one spoils the dish.","Dry-salt them 12 hours in the cold, then rinse and soak them 2 hours in clear water.","Boil the vinegar, water, sugar and spices, then cool completely — a warm marinade would cook the fish white and leave it woolly.","Cut the fillets into 4 cm pieces and layer them in a jar with onion rings.","Cover with the cold marinade and refrigerate at least five days. It keeps a month and goes with rye bread."]} },

{ id:'tarte-au-sucre', c:'na', lat:46.813, lon:-71.208, base:8, prep:40, cook:35, diff:1, tags:['sweet','bake','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#8f6a4a','#c9924a','#e8dcb8','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Tarte au sucre',en:'Sugar pie'},
  p:{fr:'Québec, Québec, Canada',en:'Quebec City, Quebec, Canada'},
  d:{fr:"Une tarte à la cassonade et à la crème, prise comme un caramel mou. Elle vient des tourtes au sucre du nord de la France, adaptées au sucre d'érable puis à la cassonade importée ; il ne faut surtout pas la cuire jusqu'à ce qu'elle soit ferme, elle prend en refroidissant.",
     en:"A tart of brown sugar and cream, set like a soft caramel. It descends from the sugar tarts of northern France, adapted first to maple sugar then to imported brown sugar; it must not be baked until firm, it sets as it cools."},
  i:[['shortcrust_pastry',300,'g'],['brown_sugar',300,'g'],['heavy_cream',200,'ml'],['butter',60,'g'],['flour',2,'tbsp'],['vanilla',1,'pc'],['egg',1,'pc'],['salt',null,'']],
  s:{fr:["Foncez le moule et faites cuire la pâte à blanc 12 minutes : sans cette précuisson, l'appareil très liquide détremperait le fond.","Mêlez la cassonade et la farine à sec avant d'ajouter quoi que ce soit de liquide — c'est le seul moyen d'éviter les grumeaux.","Ajoutez la crème, le beurre fondu, l'œuf et la vanille, et fouettez juste assez pour homogénéiser, sans faire mousser.","Versez dans le fond précuit et cuisez 30 minutes à 180 °C : le centre doit encore trembler franchement à la sortie.","Une tarte cuite jusqu'à fermeté devient granuleuse en refroidissant. Laissez-la prendre 4 heures à température ambiante."],
     en:["Line the tin and blind-bake the pastry 12 minutes: without that pre-baking the very liquid filling would soak the base.","Mix the brown sugar and flour dry before adding any liquid — the only way to avoid lumps.","Add the cream, melted butter, egg and vanilla, and whisk just enough to combine, without aerating.","Pour into the pre-baked case and bake 30 minutes at 180°C: the centre must still tremble frankly when it comes out.","A tart baked until firm turns grainy as it cools. Let it set 4 hours at room temperature."]} },

{ id:'cretons', c:'na', lat:45.502, lon:-73.567, base:8, prep:30, cook:120, diff:2, tags:['pork','slow','breakfast'],
  art:{v:'bowl',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#c9a878','#8f6a4a','#e8dcb8','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Cretons',en:'Cretons'},
  p:{fr:'Montréal, Québec, Canada',en:'Montreal, Quebec, Canada'},
  d:{fr:"Une rillette de porc au lait, à la cannelle et au clou de girofle, tartinée sur du pain grillé au petit-déjeuner. Malgré le nom, ils n'ont rien des cretons français, qui sont des résidus de graisse frits : le lait et les épices douces en font un pâté propre au Québec.",
     en:"A pork spread cooked in milk with cinnamon and clove, eaten on toast at breakfast. Despite the name they are nothing like French cretons, which are fried fat residues: the milk and the sweet spices make this a Quebec pâté of its own."},
  i:[['ground_pork',500,'g'],['whole_milk',200,'ml'],['onion',1,'pc'],['cinnamon',1,'tsp'],['cloves',0.5,'tsp'],['nutmeg',0.5,'tsp'],['breadcrumbs',60,'g'],['garlic',2,'clove'],['white_bread',8,'slice'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites suer l'oignon et l'ail hachés très fin, puis ajoutez le porc haché en l'écrasant à la fourchette pour qu'il ne s'agglomère pas.","Mouillez de lait et laissez mijoter 1 h 30 à découvert, à feu très doux, en remuant toutes les dix minutes.","Le lait doit s'évaporer presque entièrement et le gras se séparer : c'est le signe que les cretons sont prêts.","Ajoutez la chapelure dans les dix dernières minutes — elle absorbe le gras restant et donne la texture tartinable.","Versez dans des pots, tassez et laissez prendre 12 heures au froid. Les épices ne se sentent qu'au second jour."],
     en:["Sweat the very finely chopped onion and garlic, then add the minced pork, crushing it with a fork so it does not clump.","Moisten with milk and simmer 1½ hours uncovered over very low heat, stirring every ten minutes.","The milk must evaporate almost entirely and the fat separate: the sign the cretons are ready.","Add the breadcrumbs in the last ten minutes — they absorb the remaining fat and give the spreadable texture.","Pot them, press down and set 12 hours in the cold. The spices only come through on the second day."]} },

{ id:'pouding-chomeur', c:'na', lat:45.508, lon:-73.554, base:6, prep:20, cook:40, diff:1, tags:['sweet','bake','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'cake',food:['#c9924a','#f2dfa8','#8f6a4a','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Pouding chômeur',en:'Pouding chômeur'},
  p:{fr:'Montréal, Québec, Canada',en:'Montreal, Quebec, Canada'},
  d:{fr:"Un gâteau blanc sur lequel on verse un sirop chaud avant cuisson : le gâteau monte, le sirop descend, et il se forme une sauce sous le biscuit. Il fut créé par les ouvrières des usines de Montréal pendant la crise de 1929, avec de la cassonade — le sirop d'érable est venu plus tard.",
     en:"A plain cake over which hot syrup is poured before baking: the cake rises, the syrup sinks, and a sauce forms beneath the sponge. It was created by Montreal factory women during the 1929 slump, with brown sugar — the maple syrup came later."},
  i:[['flour',250,'g'],['sugar',120,'g'],['butter',120,'g'],['egg',2,'pc'],['whole_milk',150,'ml'],['baking_powder',2,'tsp'],['maple_syrup',300,'ml'],['heavy_cream',200,'ml'],['brown_sugar',100,'g'],['vanilla',1,'pc'],['salt',null,'']],
  s:{fr:["Crémez le beurre et le sucre, ajoutez les œufs puis alternez farine et lait, et versez la pâte dans un plat profond.","Le plat doit être haut : le sirop double presque de volume en bouillant et déborde d'un moule à tarte.","Portez le sirop d'érable, la crème et la cassonade à ébullition et laissez bouillonner deux minutes.","Versez-le brûlant sur la pâte crue, sans mélanger : c'est ce contraste de températures qui fait migrer le sirop au fond.","Enfournez 40 minutes à 180 °C sans jamais ouvrir. Servez tiède, en creusant jusqu'à la sauce du fond."],
     en:["Cream the butter and sugar, add the eggs then alternate flour and milk, and pour the batter into a deep dish.","The dish must be tall: the syrup nearly doubles as it boils and overflows a tart tin.","Bring the maple syrup, cream and brown sugar to the boil and let them bubble for two minutes.","Pour it scalding over the raw batter, without mixing: that difference in temperature is what sends the syrup to the bottom.","Bake 40 minutes at 180°C without opening the door. Serve warm, digging down to the sauce beneath."]} },

{ id:'cipate', c:'na', lat:48.236, lon:-79.023, base:10, prep:90, cook:360, diff:3, tags:['slow','festive','poultry'],
  art:{v:'pot',bg:'#2b2419',plate:'#f0e4c8',style:'pastry',food:['#c9924a','#8f5a3a','#e8dcb8','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Cipâte',en:'Cipâte'},
  p:{fr:'Abitibi, Québec, Canada',en:'Abitibi, Quebec, Canada'},
  d:{fr:"Une tourte à étages de gibier, de porc et de pommes de terre, séparés par des abaisses de pâte, cuite six heures. Le nom vient de sea pie, la tourte des marins anglais, francisé par l'oreille ; en Abitibi on la fait au lièvre et à l'orignal, ailleurs au poulet.",
     en:"A layered pie of game, pork and potato separated by sheets of pastry, baked for six hours. The name comes from sea pie, the English sailors' dish, reshaped by French ears; in Abitibi it is made with hare and moose, elsewhere with chicken."},
  i:[['rabbit',600,'g'],['pork_shoulder',500,'g'],['chicken',500,'g'],['potato',800,'g'],['onion',3,'pc'],['shortcrust_pastry',900,'g'],['chicken_broth',1.2,'l'],['savory',1,'tbsp'],['cloves',4,'pc'],['bay_leaf',3,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Découpez toutes les viandes en cubes de 3 cm et faites-les mariner une nuit avec l'oignon, la sarriette et les épices.","Foncez une cocotte de fonte d'une abaisse épaisse remontant sur les parois — la cipâte cuit dans son moule, elle ne se démoule pas.","Alternez viande, pomme de terre et abaisse de pâte, en trois étages, en salant chaque couche.","Versez le bouillon chaud jusqu'à couvrir le dernier étage, couvrez d'une abaisse et percez une cheminée large.","Cuisez 45 minutes à 200 °C puis 5 heures à 140 °C. Rajoutez du bouillon par la cheminée si le niveau baisse : une cipâte sèche est un échec."],
     en:["Cut all the meats into 3 cm cubes and marinate them overnight with the onion, savory and spices.","Line a cast-iron pot with a thick sheet of pastry taken up the sides — a cipâte bakes in its dish and is never turned out.","Alternate meat, potato and pastry sheets in three tiers, salting each layer.","Pour in hot broth to cover the top tier, cover with a sheet of pastry and cut a wide chimney.","Bake 45 minutes at 200°C then 5 hours at 140°C. Top up with broth through the chimney if the level drops: a dry cipâte is a failure."]} },

{ id:'oreilles-de-crisse', c:'na', lat:46.820, lon:-71.215, base:6, prep:20, cook:20, diff:2, tags:['pork','fry','festive'],
  art:{v:'bowl',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#c9924a','#8f5a3a','#e0b45a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Oreilles de crisse',en:'Oreilles de crisse'},
  p:{fr:'Québec, Québec, Canada',en:'Quebec City, Quebec, Canada'},
  d:{fr:"Des lardons de flanc de porc salé frits jusqu'à se recroqueviller en cornets croustillants. Ils accompagnent le repas de la cabane à sucre au printemps ; le nom, un juron déguisé, vient de la forme qu'elles prennent à la friture — une oreille repliée sur elle-même.",
     en:"Strips of salt pork belly fried until they curl into crisp horns. They accompany the sugar shack meal in spring; the name, a disguised oath, comes from the shape they take in the fryer — an ear folded on itself."},
  i:[['salted_pork',500,'g'],['maple_syrup',60,'ml'],['black_peppercorns',1,'tbsp'],['water',500,'ml']],
  s:{fr:["Faites dessaler le flanc de porc 2 heures à l'eau froide en la changeant deux fois, sinon les oreilles seront immangeables.","Taillez-le en lanières de 5 mm d'épaisseur, en travers du grain et en gardant la couenne : c'est la couenne qui les fait se recroqueviller.","Pochez-les 10 minutes à l'eau frémissante et épongez-les à fond — cette précuisson rend une partie du gras et évite qu'elles brûlent.","Faites-les frire dans leur propre graisse à feu moyen, 8 minutes, sans matière grasse ajoutée : elles se replient d'elles-mêmes.","Égouttez sur du papier, poivrez et arrosez d'un filet de sirop d'érable. Se mangent brûlantes et se ramollissent en un quart d'heure."],
     en:["Soak the salt pork belly 2 hours in cold water, changing it twice, or the oreilles will be inedible.","Cut it into 5 mm strips across the grain, keeping the rind: it is the rind that makes them curl.","Poach them 10 minutes in simmering water and blot them thoroughly — that pre-cooking renders some fat and stops them burning.","Fry them in their own fat over medium heat for 8 minutes, adding nothing: they fold themselves.","Drain on paper, pepper and trickle over maple syrup. Eaten scalding, they soften within a quarter of an hour."]} },

{ id:'grands-peres-au-sirop', c:'na', lat:46.807, lon:-71.220, base:6, prep:25, cook:25, diff:1, tags:['sweet','comfort','fast'],
  art:{v:'bowl',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#f4f0e6','#c9924a','#e8dcb8','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Grands-pères au sirop d’érable',en:'Grands-pères in maple syrup'},
  p:{fr:'Québec, Québec, Canada',en:'Quebec City, Quebec, Canada'},
  d:{fr:"Des boules de pâte pochées directement dans un sirop d'érable bouillant, gonflées et imbibées. On ne les frit jamais : elles cuisent à la vapeur sous le couvercle, au-dessus du sirop autant que dedans, ce qui explique qu'il ne faille pas ouvrir la casserole.",
     en:"Balls of dough poached straight in boiling maple syrup, swollen and soaked through. They are never fried: they steam under the lid, above the syrup as much as in it, which is why the pan must not be opened."},
  i:[['flour',250,'g'],['baking_powder',2,'tsp'],['butter',60,'g'],['whole_milk',150,'ml'],['maple_syrup',400,'ml'],['water',250,'ml'],['sugar',50,'g'],['salt',null,'']],
  s:{fr:["Portez le sirop d'érable, l'eau et le sucre à ébullition dans une casserole large et haute : le liquide doit faire trois centimètres de fond.","Sablez le beurre froid dans la farine, la levure et le sel, puis liez au lait sans travailler la pâte.","Prélevez des boules à la cuillère et déposez-les à la surface du sirop bouillant, sans les enfoncer et sans qu'elles se touchent.","Couvrez immédiatement et laissez 20 minutes à feu doux, sans jamais soulever le couvercle : la vapeur emprisonnée fait doubler les boules.","Elles sont cuites quand une aiguille ressort sèche. Servez brûlants, dans le sirop, avec de la crème froide."],
     en:["Bring the maple syrup, water and sugar to the boil in a wide, deep pan: the liquid should be three centimetres deep.","Rub the cold butter into the flour, baking powder and salt, then bind with the milk without working the dough.","Scoop balls with a spoon and set them on the surface of the boiling syrup, without pushing them under and without touching.","Cover immediately and give them 20 minutes over low heat, never lifting the lid: the trapped steam doubles them in size.","They are done when a needle comes out dry. Serve scalding, in the syrup, with cold cream."]} },

{ id:'partridgeberry-pie', c:'na', lat:47.561, lon:-52.712, base:8, prep:50, cook:50, diff:2, tags:['sweet','bake','fruit'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#c9402c','#e0b45a','#f2dfa8','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Tarte aux airelles rouges',en:'Partridgeberry pie'},
  p:{fr:'Saint-Jean, Terre-Neuve-et-Labrador, Canada',en:'St. John’s, Newfoundland and Labrador, Canada'},
  d:{fr:"Une tarte aux airelles rouges de la toundra, très acides, sucrées et liées à la fécule. Les Terre-Neuviens les appellent partridgeberries et les cueillent en septembre sur les barrens battus par le vent ; les baies gèlent sur pied et se conservent tout l'hiver.",
     en:"A pie of tundra lingonberries, very sharp, sweetened and thickened with starch. Newfoundlanders call them partridgeberries and pick them in September on the wind-scoured barrens; the berries freeze on the plant and keep all winter."},
  i:[['lingonberries',500,'g'],['shortcrust_pastry',600,'g'],['sugar',180,'g'],['cornstarch',30,'g'],['butter',30,'g'],['cinnamon',1,'tsp'],['orange_zest',1,'pc'],['egg_yolk',1,'pc'],['salt',null,'']],
  s:{fr:["Triez les baies à la main et écartez les feuilles et les tiges — un tri à l'eau les fait éclater et perdre leur jus.","Mêlez-les au sucre et à la fécule, mais goûtez avant : l'airelle est bien plus acide que la myrtille et supporte deux fois plus de sucre.","Faites-en chauffer un tiers à la casserole cinq minutes pour les faire éclater, puis mêlez-les aux crues : les unes donnent la sauce, les autres tiennent.","Garnissez, parsemez de beurre et couvrez d'un disque entier — cette baie rend peu de jus, un treillis la dessécherait.","Dorez, entaillez trois fentes et cuisez 50 minutes à 190 °C. Laissez refroidir complètement : chaude, la garniture coule."],
     en:["Sort the berries by hand and pick out leaves and stems — washing them makes them burst and lose their juice.","Mix them with the sugar and cornstarch, but taste first: lingonberry is far sharper than blueberry and takes twice the sugar.","Heat a third of them in a pan for five minutes to burst them, then mix with the raw ones: the first give the sauce, the second hold their shape.","Fill, dot with butter and cover with a solid disc — this berry gives little juice, and a lattice would dry it out.","Glaze, cut three vents and bake 50 minutes at 190°C. Cool completely: warm, the filling runs."]} },

{ id:'malpeque-oysters', c:'na', lat:46.518, lon:-63.638, base:4, prep:25, cook:5, diff:2, tags:['sea','fresh','festive'],
  art:{v:'plate',bg:'#26485c',plate:'#f4f0e6',style:'other',food:['#e8dcc0','#f4f0e6','#7fae5a','#e0b45a'],garnish:'#6fbf8f'},
  n:{fr:'Huîtres de Malpeque',en:'Malpeque oysters'},
  p:{fr:'Malpeque, Île-du-Prince-Édouard, Canada',en:'Malpeque, Prince Edward Island, Canada'},
  d:{fr:"Des huîtres de la baie de Malpeque, servies crues sur glace avec du citron. Elles poussent quatre à sept ans dans une eau plus froide que celle du Sud, ce qui ralentit la croissance et concentre le goût ; elles ont remporté le grand prix de l'Exposition de Saint-Louis en 1900.",
     en:"Oysters from Malpeque Bay, served raw on ice with lemon. They grow four to seven years in colder water than farther south, which slows growth and concentrates flavour; they took the grand prize at the St. Louis Exposition in 1900."},
  i:[['oysters',24,'pc'],['lemon',2,'pc'],['shallot',2,'pc'],['red_wine_vinegar',60,'ml'],['butter',80,'g'],['garlic',2,'clove'],['parsley',2,'tbsp'],['rye_bread',200,'g'],['pepper',null,'']],
  s:{fr:["Gardez les huîtres à plat, creux vers le bas, dans un linge humide : couchées sur le côté, elles perdent leur eau.","Ouvrez-les au couteau court en entrant par la charnière et non par le côté : la charnière cède d'un quart de tour, le côté demande de forcer.","Jetez la première eau et attendez deux minutes : l'huître en refait une seconde, plus claire et bien meilleure.","Détachez la noix du muscle inférieur pour que chacun n'ait pas à le faire, et remettez-la dans sa coquille.","Servez sur glace pilée avec un vinaigre à l'échalote et du citron. Quelques-unes peuvent passer deux minutes sous le gril, beurrées à l'ail."],
     en:["Keep the oysters flat, cupped side down, in a damp cloth: laid on their side they lose their liquor.","Open them with a short knife going in at the hinge and not the side: the hinge gives with a quarter turn, the side needs force.","Discard the first liquor and wait two minutes: the oyster makes a second, clearer and far better.","Free the oyster from the lower muscle so nobody has to do it, and return it to its shell.","Serve on crushed ice with a shallot vinegar and lemon. A few may go two minutes under the grill, buttered with garlic."]} },

{ id:'hodgepodge', c:'na', lat:44.649, lon:-63.575, base:6, prep:30, cook:35, diff:1, tags:['veg','fresh','comfort'],
  art:{v:'bowl',bg:'#28331f',plate:'#f4f0e6',style:'soup',food:['#f4f0e6','#7fae5a','#e0b45a','#f0e8d0'],garnish:'#6fbf8f'},
  n:{fr:'Hodgepodge',en:'Hodgepodge'},
  p:{fr:'Halifax, Nouvelle-Écosse, Canada',en:'Halifax, Nova Scotia, Canada'},
  d:{fr:"Un ragoût crémeux des tout premiers légumes du potager, cuits à peine et liés au beurre. Ce n'est pas un plat d'hiver mais de fin juillet : on l'attend toute l'année, on le fait une ou deux fois quand les pommes de terre nouvelles et les haricots arrivent en même temps, et la saison est finie.",
     en:"A creamy stew of the season's first garden vegetables, barely cooked and bound with butter. It is not a winter dish but a late July one: awaited all year, made once or twice when the new potatoes and beans arrive together, and then the season is over."},
  i:[['potato',600,'g'],['green_beans',300,'g'],['peas',200,'g'],['carrot',3,'pc'],['heavy_cream',300,'ml'],['butter',80,'g'],['spring_onion',4,'pc'],['dill',2,'tbsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Employez des pommes de terre nouvelles à peau fine, non pelées mais frottées : la peau est le meilleur du légume en cette saison.","Cuisez chaque légume dans le même faitout mais l'un après l'autre, du plus long au plus court, en les retirant à mesure.","Gardez très peu d'eau au fond — deux centimètres — car c'est elle qui, avec la crème, fera la sauce.","Remettez tout dans le faitout, ajoutez la crème et le beurre et laissez frémir trois minutes seulement, sans jamais bouillir.","Les légumes doivent rester croquants : un hodgepodge trop cuit devient une soupe et perd ce qui le rendait attendu."],
     en:["Use new potatoes with thin skins, unpeeled but scrubbed: at this season the skin is the best of the vegetable.","Cook each vegetable in the same pot but one after another, longest first, lifting each out as it is done.","Keep very little water in the base — two centimetres — because with the cream it will make the sauce.","Return everything to the pot, add the cream and butter and let it tremble for three minutes only, never boiling.","The vegetables must stay crisp: an overcooked hodgepodge becomes a soup and loses what made it worth waiting for."]} },

{ id:'rapure-acadienne', c:'na', lat:44.336, lon:-66.117, base:8, prep:120, cook:150, diff:3, tags:['poultry','slow','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f0e4c8',style:'other',food:['#c9a878','#8f6a4a','#e8dcb8','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Râpure acadienne',en:'Acadian rappie pie'},
  p:{fr:'Baie Sainte-Marie, Nouvelle-Écosse, Canada',en:'Baie Sainte-Marie, Nova Scotia, Canada'},
  d:{fr:"Un gratin de pommes de terre râpées et pressées, dont on remplace l'eau extraite par du bouillon de volaille. C'est une opération de substitution : on ôte tout le liquide de la pomme de terre pour lui rendre exactement le même volume en bouillon, ce qui donne une texture translucide et gélatineuse.",
     en:"A bake of grated, pressed potato in which the extracted water is replaced by chicken broth. It is an operation of substitution: every drop of liquid is removed from the potato and exactly the same volume given back as broth, producing a translucent, gelatinous texture."},
  i:[['potato',3,'kg'],['chicken',1.2,'kg'],['onion',3,'pc'],['smoked_bacon',200,'g'],['butter',80,'g'],['bay_leaf',2,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Pochez le poulet 1 h 30 avec l'oignon et le laurier, désossez-le et gardez tout le bouillon, filtré et brûlant.","Râpez les pommes de terre très fin et pressez-les par poignées dans un linge, jusqu'à ce qu'il ne sorte plus une goutte.","Mesurez l'eau extraite : c'est exactement ce volume de bouillon bouillant qu'il faut reverser sur la râpure, ni plus ni moins.","Versez le bouillon très chaud en fouettant : la râpure blanchit, épaissit et devient translucide en quelques secondes.","Montez en deux couches avec le poulet au milieu, parsemez de lardons et cuisez 2 h 30 à 200 °C jusqu'à une croûte brune et craquante."],
     en:["Poach the chicken 1½ hours with the onion and bay, bone it and keep all the broth, strained and scalding.","Grate the potatoes very finely and press them by handfuls in a cloth, until not another drop comes out.","Measure the extracted water: exactly that volume of boiling broth must go back into the gratings, no more and no less.","Pour the very hot broth in, whisking: the gratings whiten, thicken and turn translucent within seconds.","Build in two layers with the chicken in the middle, scatter bacon and bake 2½ hours at 200°C to a brown, crackling crust."]} },

{ id:'blueberry-grunt', c:'na', lat:44.640, lon:-63.590, base:6, prep:25, cook:25, diff:1, tags:['sweet','fruit','comfort'],
  art:{v:'pot',bg:'#2c3440',plate:'#f4f0e6',style:'other',food:['#4a4a7a','#f4f0e6','#e0b45a','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Blueberry grunt',en:'Blueberry grunt'},
  p:{fr:'Halifax, Nouvelle-Écosse, Canada',en:'Halifax, Nova Scotia, Canada'},
  d:{fr:"Des bleuets sauvages mijotés sous des boulettes de pâte cuites à la vapeur, dans une seule casserole. Le nom vient du bruit : les fruits grognent en bouillonnant sous le couvercle. Il date de l'époque où les cuisines n'avaient pas de four et où tout se faisait sur le feu.",
     en:"Wild blueberries stewed under steamed dumplings, all in one pan. The name comes from the sound: the fruit grunts as it bubbles under the lid. It dates from when kitchens had no oven and everything was done over the fire."},
  i:[['blueberries',500,'g'],['sugar',150,'g'],['flour',250,'g'],['butter',80,'g'],['whole_milk',150,'ml'],['baking_powder',2,'tsp'],['lemon',1,'pc'],['cinnamon',1,'tsp'],['heavy_cream',200,'ml'],['water',100,'ml'],['salt',null,'']],
  s:{fr:["Faites compoter les bleuets avec le sucre, l'eau, le zeste et la cannelle 8 minutes, jusqu'à ce qu'ils éclatent et rendent leur jus.","Le fond de liquide doit rester généreux : c'est la vapeur qui monte de lui qui cuira les boulettes, et un fond sec les laisserait crues.","Sablez le beurre dans la farine, la levure et le sel, puis liez au lait sans travailler la pâte.","Déposez des cuillerées de pâte à la surface des fruits bouillonnants, sans les enfoncer et bien espacées — elles doublent.","Couvrez et laissez 15 minutes sans jamais soulever le couvercle. Servez brûlant, avec de la crème froide versée dessus."],
     en:["Stew the blueberries with the sugar, water, zest and cinnamon for 8 minutes, until they burst and give up their juice.","The liquid must stay generous: it is the steam rising from it that cooks the dumplings, and a dry base leaves them raw.","Rub the butter into the flour, baking powder and salt, then bind with the milk without working the dough.","Drop spoonfuls of dough onto the bubbling fruit, without pushing them under and well spaced — they double.","Cover and give them 15 minutes without ever lifting the lid. Serve scalding, with cold cream poured over."]} },

{ id:'caribou-steak', c:'na', lat:62.454, lon:-114.372, base:4, prep:30, cook:12, diff:2, tags:['grill','fast','festive'],
  art:{v:'plate',bg:'#2b2419',plate:'#f4f0e6',style:'grill',food:['#8f3b2a','#6f2a2a','#e8dcb8','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Steak de caribou',en:'Caribou steak'},
  p:{fr:'Yellowknife, Territoires du Nord-Ouest, Canada',en:'Yellowknife, Northwest Territories, Canada'},
  d:{fr:"Un pavé de caribou saisi au beurre, servi saignant avec des airelles. Le caribou est chassé par les Dénés et les Inuvialuit depuis des millénaires ; sa viande ne contient presque pas de gras et se nourrit de lichen l'hiver, ce qui lui donne un goût de mousse et de résine.",
     en:"A caribou steak seared in butter, served rare with lingonberries. Caribou has been hunted by the Dene and Inuvialuit for millennia; the meat holds almost no fat and the animal feeds on lichen in winter, which gives it a taste of moss and resin."},
  i:[['venison',600,'g'],['butter',80,'g'],['garlic',3,'clove'],['juniper_berries',8,'pc'],['lingonberry_jam',100,'g'],['red_wine',100,'ml'],['thyme',3,'sprig'],['potato',600,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Sortez la viande deux heures à l'avance : un pavé glacé au cœur cuirait à l'extérieur avant d'être tiède au centre.","Écrasez le genièvre au mortier avec le poivre et frottez-en la viande, mais ne salez qu'au moment de la mettre en poêle.","Saisissez à feu très vif dans un beurre mousseux, 2 minutes par face, en arrosant à la cuillère avec l'ail et le thym.","Le caribou n'a pas de gras pour se protéger : au-delà de saignant, il devient sec et hépatique, sans retour possible.","Laissez reposer autant de temps qu'il a cuit, puis déglacez au vin rouge et à la confiture d'airelles. Servez avec des pommes de terre."],
     en:["Take the meat out two hours ahead: a steak frozen at the centre would cook outside before the middle was even warm.","Crush the juniper in a mortar with the pepper and rub it into the meat, but salt only as it goes into the pan.","Sear over fierce heat in foaming butter, 2 minutes a side, spooning it over with the garlic and thyme.","Caribou has no fat to protect it: past rare it turns dry and livery, with no way back.","Rest it as long as it cooked, then deglaze with red wine and lingonberry jam. Serve with potatoes."]} },

{ id:'muktuk', c:'na', lat:63.746, lon:-68.517, base:6, prep:30, cook:0, diff:2, tags:['sea','fresh','festive'],
  art:{v:'board',bg:'#2c3440',plate:'#f4f0e6',style:'other',food:['#3a3a4a','#f4f0e6','#e8dcc0','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Muktuk',en:'Muktuk'},
  p:{fr:'Iqaluit, Nunavut, Canada',en:'Iqaluit, Nunavut, Canada'},
  d:{fr:"De la peau et du lard de narval ou de baleine boréale, mangés crus, en cubes. C'est l'une des rares sources de vitamine C de l'Arctique : la peau en contient autant que l'orange, et sans elle le scorbut aurait été inévitable dans une alimentation sans végétaux.",
     en:"Skin and blubber of narwhal or bowhead whale, eaten raw in cubes. It is one of the few sources of vitamin C in the Arctic: the skin holds as much as an orange, and without it scurvy would have been unavoidable in a diet with no plants."},
  i:[['whale_skin',500,'g'],['soy_sauce',40,'ml'],['onion',1,'pc'],['coarse_salt',1,'tbsp'],['lemon',1,'pc']],
  s:{fr:["Le muktuk se prélève sur l'animal fraîchement chassé et se consomme dans les heures qui suivent, ou se congèle immédiatement.","Il ne se cuisine pas : le chauffer détruit la vitamine C qui en justifie l'usage, et rend la peau caoutchouteuse.","Coupez en cubes de deux centimètres avec un ulu, en gardant la peau noire et le lard blanc ensemble : ce sont les deux couches qui font le muktuk.","La peau doit craquer sous la dent et le lard fondre : si la peau est molle, l'animal était vieux ou la conservation trop longue.","Servez cru, avec du sel, de l'oignon cru ou une pointe de soja. Il se mange aussi légèrement fermenté sous la mousse, mais cette préparation demande un savoir local."],
     en:["Muktuk is taken from a freshly hunted animal and eaten within hours, or frozen immediately.","It is not cooked: heating destroys the vitamin C that justifies its use, and turns the skin rubbery.","Cut it into two-centimetre cubes with an ulu, keeping the black skin and white blubber together: those two layers are what make muktuk.","The skin should crack under the tooth and the blubber melt: if the skin is soft, the animal was old or the keeping too long.","Serve raw, with salt, raw onion or a touch of soy. It is also eaten lightly fermented under moss, but that preparation needs local knowledge."]} }
,

{ id:'boston-cream-pie', c:'na', lat:42.352, lon:-71.065, base:10, prep:120, cook:35, diff:3, tags:['sweet','bake','festive'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'cake',food:['#3a2018','#f2dfa8','#f4f0e6','#e8c46a'],garnish:'#c9754a'},
  n:{fr:'Boston cream pie',en:'Boston cream pie'},
  p:{fr:'Boston, Massachusetts, États-Unis',en:'Boston, Massachusetts, United States'},
  d:{fr:"Une génoise fourrée de crème pâtissière et glacée au chocolat, malgré son nom de tourte. Elle a été créée en 1856 à l'hôtel Parker House de Boston ; on l'appelait pie parce qu'on la cuisait alors dans des moules à tourte, les moules à gâteau étant rares.",
     en:"A sponge filled with pastry cream and glazed with chocolate, despite being called a pie. It was created in 1856 at Boston's Parker House hotel; it was called a pie because it was baked in pie tins, cake tins then being scarce."},
  i:[['flour',250,'g'],['egg',5,'pc'],['sugar',300,'g'],['butter',180,'g'],['baking_powder',10,'g'],['whole_milk',600,'ml'],['egg_yolk',5,'pc'],['cornstarch',50,'g'],['vanilla',2,'pc'],['dark_chocolate',200,'g'],['heavy_cream',200,'ml']],
  s:{fr:["Préparez la crème pâtissière en premier et laissez-la refroidir au moins quatre heures, filmée au contact.","Une crème tiède fait fondre la génoise et le gâteau glisse en deux couches dès qu'on le coupe.","Cuisez deux disques de génoise plutôt qu'un seul que vous trancheriez : la découpe donne une surface irrégulière que la crème traverse.","Étalez la crème froide sur le premier disque en laissant un centimètre de marge, puis posez le second sans presser.","Nappez d'une ganache tiède et laissez-la couler naturellement sur les bords. Réfrigérez deux heures avant de servir."],
     en:["Make the pastry cream first and chill it at least four hours, covered on the surface.","A warm cream melts the sponge and the cake slides apart the moment it is cut.","Bake two sponge discs rather than one to be split: cutting gives an uneven surface the cream soaks through.","Spread the cold cream on the first disc leaving a centimetre margin, then set the second on without pressing.","Coat with a warm ganache and let it run naturally down the sides. Chill two hours before serving."]} },

{ id:'apple-cider-donuts', c:'na', lat:44.260, lon:-72.575, base:12, prep:90, cook:25, diff:2, tags:['sweet','fry','fruit'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#c9924a','#e8c46a','#f2dfa8','#8f5a3a'],garnish:'#c9754a'},
  n:{fr:'Beignets au cidre de pomme',en:'Apple cider donuts'},
  p:{fr:'Vermont, États-Unis',en:'Vermont, United States'},
  d:{fr:"Des beignets au cidre doux réduit, roulés dans le sucre à la cannelle. Ils appartiennent à l'automne en Nouvelle-Angleterre : on les vend dans les vergers pendant la cueillette, et la réduction du cidre est ce qui distingue les bons des autres.",
     en:"Doughnuts made with reduced sweet cider, rolled in cinnamon sugar. They belong to the New England autumn: sold at orchards during picking season, and the cider reduction is what separates the good ones from the rest."},
  i:[['apple_cider',750,'ml'],['flour',600,'g'],['baking_powder',15,'g'],['baking_soda',5,'g'],['sugar',300,'g'],['butter',120,'g'],['egg',2,'pc'],['buttermilk',150,'ml'],['cinnamon',15,'g'],['nutmeg',5,'g'],['frying_oil',2,'l'],['salt',null,'']],
  s:{fr:["Faites réduire le cidre doux des trois quarts, jusqu'à obtenir moins de 200 ml de sirop épais et sombre.","Sans cette réduction, le goût de pomme disparaît entièrement à la friture : c'est l'étape que tout le monde abrège et qui fait échouer la recette.","Laissez le sirop refroidir avant de l'incorporer, puis travaillez la pâte le moins possible.","Réfrigérez-la une heure : molle et collante, elle est impossible à découper proprement.","Frites à 180 °C, quatre-vingt-dix secondes par face, et roulez dans le sucre à la cannelle tant qu'ils sont brûlants."],
     en:["Reduce the sweet cider by three-quarters, to under 200 ml of thick dark syrup.","Without that reduction the apple flavour disappears entirely in the fryer: the step everyone cuts short and the reason the recipe fails.","Cool the syrup before working it in, then handle the dough as little as possible.","Chill it an hour: soft and sticky, it cannot be cut cleanly.","Fry at 180°C, ninety seconds a side, and roll in cinnamon sugar while still scalding."]} },

{ id:'new-england-boiled-dinner', c:'na', lat:42.400, lon:-71.100, base:8, prep:40, cook:210, diff:1, tags:['beef','slow','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f0e4c8',style:'other',food:['#c9302a','#f4f0e6','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'New England boiled dinner',en:'New England boiled dinner'},
  p:{fr:'Nouvelle-Angleterre, États-Unis',en:'New England, United States'},
  d:{fr:"Du bœuf salé bouilli avec chou, betteraves et racines, servi dans une seule assiette. Les restes ont donné naissance à un second plat, le red flannel hash, où la betterave colore tout en rouge : la moitié de l'intérêt du plat est dans ce lendemain.",
     en:"Corned beef boiled with cabbage, beetroot and root vegetables, served on one plate. The leftovers gave rise to a second dish, red flannel hash, where the beetroot turns everything red: half the point of the meal is the next day."},
  i:[['corned_beef',2,'kg'],['cabbage',1,'pc'],['potato',800,'g'],['carrot',6,'pc'],['turnip',500,'g'],['beetroot',500,'g'],['onion',3,'pc'],['bay_leaf',3,'pc'],['black_peppercorns',10,'g'],['mustard',60,'g'],['horseradish',40,'g']],
  s:{fr:["Rincez le bœuf salé à l'eau froide et faites-le dégorger une heure si la saumure est forte.","Portez à frémissement, jamais à ébullition : à gros bouillons, les fibres se contractent et la viande devient sèche et filandreuse.","Comptez trois heures à couvert, en écumant la première demi-heure.","Cuisez les betteraves à part, toujours : dans le même pot, elles teindraient tout le plat en rose dès la première heure.","Ajoutez les racines une heure avant la fin, le chou en quartiers dans les vingt dernières minutes. Servez avec moutarde et raifort."],
     en:["Rinse the corned beef in cold water and soak it an hour if the brine is strong.","Bring to a tremble, never a boil: at a rolling boil the fibres contract and the meat goes dry and stringy.","Allow three hours covered, skimming for the first half hour.","Cook the beetroot separately, always: in the same pot it would dye the whole dish pink within the first hour.","Add the roots an hour before the end, the cabbage in wedges for the last twenty minutes. Serve with mustard and horseradish."]} },

{ id:'new-york-pizza', c:'na', lat:40.713, lon:-74.006, base:4, prep:1440, cook:15, diff:3, tags:['bake','cheese','street'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'flat',food:['#c9302a','#f4f0e6','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Pizza new-yorkaise',en:'New York-style pizza'},
  p:{fr:'New York, États-Unis',en:'New York City, United States'},
  d:{fr:"Une grande pizza à pâte fine et souple, vendue à la part et pliée en deux pour être mangée. Le pliage n'est pas une facétie : la part fait vingt-cinq centimètres et s'affaisserait sans lui, et c'est la seule manière de la manger debout.",
     en:"A large pizza with a thin, pliable crust, sold by the slice and folded in half to eat. The fold is not a joke: the slice is twenty-five centimetres long and would droop without it, and folding is the only way to eat it standing."},
  i:[['bread_flour',600,'g'],['water',380,'ml'],['fresh_yeast',5,'g'],['olive_oil',30,'ml'],['sugar',10,'g'],['canned_tomatoes',400,'g'],['mozzarella',400,'g'],['parmesan',60,'g'],['oregano',5,'g'],['garlic',3,'clove'],['salt',null,'']],
  s:{fr:["Pétrissez une pâte à 63 % d'hydratation et laissez-la fermenter vingt-quatre heures au froid.","Cette fermentation longue donne la souplesse : une pâte poussée en deux heures est cassante et se brise au pliage.","N'employez pas de tomate cuite — la sauce new-yorkaise est de la tomate crue concassée, à peine salée et parfumée à l'origan.","Étalez à la main jusqu'à quarante centimètres, en laissant un bord de deux centimètres, et n'employez jamais de rouleau.","Cuisez à 290 °C sur une pierre brûlante, huit à dix minutes, jusqu'à ce que le dessous soit taché de brun."],
     en:["Knead a dough at 63% hydration and ferment it twenty-four hours in the cold.","That long ferment gives the pliability: a dough proved in two hours is brittle and snaps when folded.","Do not use cooked tomato — New York sauce is crushed raw tomato, barely salted and scented with oregano.","Stretch by hand to forty centimetres, leaving a two-centimetre rim, and never use a rolling pin.","Bake at 290°C on a scalding stone, eight to ten minutes, until the underside is spotted brown."]} },

{ id:'pecan-pie', c:'na', lat:32.776, lon:-96.797, base:10, prep:60, cook:60, diff:2, tags:['sweet','bake','festive'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#8f5a3a','#c9754a','#e8c46a','#f2dfa8'],garnish:'#c9754a'},
  n:{fr:'Tarte aux noix de pécan',en:'Pecan pie'},
  p:{fr:'Sud des États-Unis',en:'American South'},
  d:{fr:"Une tarte à la garniture de sirop et d'œufs couverte de noix de pécan. Le pacanier est le seul arbre à noix majeur originaire d'Amérique du Nord ; la tarte s'est répandue dans les années 1920 grâce à une campagne du fabricant de sirop de maïs Karo.",
     en:"A pie of syrup and egg custard topped with pecans. The pecan is the only major nut tree native to North America; the pie spread in the 1920s through a campaign by the corn syrup maker Karo."},
  i:[['shortcrust_pastry',300,'g'],['pecans',300,'g'],['corn_syrup',300,'ml'],['brown_sugar',150,'g'],['egg',4,'pc'],['butter',80,'g'],['vanilla',1,'pc'],['bourbon',40,'ml'],['salt',null,'']],
  s:{fr:["Faites cuire le fond à blanc quinze minutes avec des poids : la garniture est très liquide et détremperait une pâte crue.","Grillez les noix de pécan à sec dix minutes et laissez-les refroidir : crues, elles restent molles sous la garniture.","Battez les œufs sans les faire mousser — la mousse remonte et forme une croûte spongieuse en surface.","Disposez les noix face bombée vers le haut sur le fond, puis versez l'appareil doucement par-dessus : elles remontent et se placent d'elles-mêmes.","Cuisez 50 minutes à 175 °C. Le centre doit encore trembler ; il prend en refroidissant."],
     en:["Blind bake the shell fifteen minutes with weights: the filling is very liquid and would soak a raw base.","Toast the pecans dry for ten minutes and cool them: raw, they stay soft under the filling.","Beat the eggs without frothing — foam rises and forms a spongy crust on the surface.","Lay the pecans rounded side up in the shell, then pour the filling gently over: they float up and arrange themselves.","Bake 50 minutes at 175°C. The centre should still tremble; it sets as it cools."]} },

{ id:'collard-greens-sud', c:'na', lat:33.749, lon:-84.388, base:6, prep:40, cook:120, diff:1, tags:['veg','slow','pork'],
  art:{v:'pot',bg:'#28331f',plate:'#f0e4c8',style:'other',food:['#2a3a1a','#4f6f3a','#8f5a3a','#e8c46a'],garnish:'#7fae6a'},
  n:{fr:'Chou cavalier au jarret fumé',en:'Collard greens'},
  p:{fr:'Atlanta, Géorgie, États-Unis',en:'Atlanta, Georgia, United States'},
  d:{fr:"Des feuilles de chou cavalier mijotées des heures avec du porc fumé. Le jus de cuisson s'appelle le pot likker et ne se jette jamais : il concentre les vitamines passées dans l'eau, et on le boit ou on y trempe du pain de maïs.",
     en:"Collard leaves simmered for hours with smoked pork. The cooking liquid is called pot likker and is never thrown out: it concentrates the vitamins leached into the water, and is drunk or soaked up with cornbread."},
  i:[['collard_greens',1.5,'kg'],['pork_knuckle',600,'g'],['onion',2,'pc'],['garlic',6,'clove'],['cider_vinegar',60,'ml'],['sugar',15,'g'],['chili_flakes',5,'g'],['chicken_broth',1.5,'l'],['corn_bread',6,'slice'],['salt',null,'']],
  s:{fr:["Lavez les feuilles trois fois dans un grand volume d'eau : le chou cavalier retient énormément de terre entre ses nervures.","Retirez la nervure centrale de chaque feuille — elle reste dure après deux heures de cuisson et gâche la texture.","Faites d'abord mijoter le jarret fumé une heure seule, pour parfumer le bouillon avant d'y mettre les feuilles.","Ajoutez le chou en plusieurs fois : il réduit des trois quarts et n'entrerait pas dans la marmite d'un coup.","Comptez encore une heure. Ajoutez le vinaigre à la toute fin, hors du feu : ajouté tôt, il fixe le vert mais durcit la feuille."],
     en:["Wash the leaves three times in plenty of water: collards hold a great deal of grit between their ribs.","Strip the central rib from every leaf — it stays tough after two hours' cooking and spoils the texture.","Simmer the ham hock alone for an hour first, to flavour the broth before the greens go in.","Add the greens in batches: they shrink by three-quarters and would not fit the pot at once.","Allow another hour. Add the vinegar at the very end, off the heat: added early it fixes the green but toughens the leaf."]} },

{ id:'hushpuppies', c:'na', lat:32.777, lon:-79.931, base:8, prep:30, cook:20, diff:1, tags:['fry','street','fast'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#e8c46a','#c9924a','#f2dfa8','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Hushpuppies',en:'Hushpuppies'},
  p:{fr:'Charleston, Caroline du Sud, États-Unis',en:'Charleston, South Carolina, United States'},
  d:{fr:"Des boulettes de farine de maïs frites, servies avec le poisson frit. Le nom viendrait de pêcheurs jetant des morceaux de pâte aux chiens pour les faire taire ; l'étymologie est incertaine, mais l'association avec la friture de poisson est constante depuis le XIXe siècle.",
     en:"Fried cornmeal balls served alongside fried fish. The name is said to come from fishermen throwing scraps of batter to the dogs to quiet them; the etymology is uncertain, but the pairing with a fish fry is constant since the nineteenth century."},
  i:[['cornmeal',300,'g'],['flour',100,'g'],['baking_powder',12,'g'],['egg',2,'pc'],['buttermilk',300,'ml'],['onion',1,'pc'],['sugar',20,'g'],['frying_oil',1.5,'l'],['jalapeno',1,'pc'],['salt',null,'']],
  s:{fr:["Employez une farine de maïs à mouture moyenne : trop fine, la boulette est compacte ; trop grosse, elle reste sableuse.","Mêlez sec et liquide à peine, quinze secondes, en laissant la pâte grumeleuse.","Laissez reposer dix minutes que la farine s'hydrate, mais pas davantage : la levure chimique commence à travailler et l'attente lui fait perdre son effet.","Prélevez à la cuillère à glace et laissez tomber dans l'huile à 180 °C, sans façonner à la main.","Elles se retournent d'elles-mêmes quand un côté est cuit. Comptez trois minutes en tout."],
     en:["Use medium-grind cornmeal: too fine and the ball is dense, too coarse and it stays sandy.","Combine dry and wet barely, for fifteen seconds, leaving the batter lumpy.","Rest ten minutes for the meal to hydrate, but no longer: the baking powder starts working and waiting wastes its lift.","Scoop with a small ice cream scoop and drop into oil at 180°C, without shaping by hand.","They turn themselves over when one side is cooked. Allow three minutes in all."]} },

{ id:'reuben-sandwich', c:'na', lat:41.257, lon:-95.934, base:4, prep:30, cook:20, diff:2, tags:['beef','comfort','cheese'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'roll',food:['#c9302a','#f4f0e6','#8f5a3a','#e8c46a'],garnish:'#7fae6a'},
  n:{fr:'Reuben sandwich',en:'Reuben sandwich'},
  p:{fr:'Omaha, Nebraska, États-Unis',en:'Omaha, Nebraska, United States'},
  d:{fr:"Un sandwich grillé au bœuf salé, choucroute, emmental suisse et sauce russe, sur pain de seigle. Omaha et New York s'en disputent l'invention depuis un siècle ; la version d'Omaha le fait naître vers 1925 d'une partie de poker au Blackstone Hotel.",
     en:"A grilled sandwich of corned beef, sauerkraut, Swiss cheese and Russian dressing on rye. Omaha and New York have disputed its invention for a century; the Omaha version has it born around 1925 at a poker game in the Blackstone Hotel."},
  i:[['rye_bread',8,'slice'],['corned_beef',500,'g'],['sauerkraut',300,'g'],['swiss_cheese',200,'g'],['mayonnaise',120,'g'],['ketchup',40,'g'],['horseradish',20,'g'],['pickles',60,'g'],['butter',100,'g'],['worcestershire',10,'ml']],
  s:{fr:["Pressez la choucroute à fond dans un linge : c'est son eau qui détrempe le pain et fait échouer le sandwich.","Réchauffez le bœuf salé à la vapeur plutôt qu'à la poêle, pour qu'il reste souple et humide.","Montez dans cet ordre : pain, fromage, bœuf, choucroute, sauce, fromage, pain. Le fromage des deux côtés fait barrière à l'humidité.","Beurrez l'extérieur du pain, pas la poêle : le beurre fond régulièrement et dore la mie sans la brûler.","Grillez sous presse, à feu moyen, quatre minutes par face, jusqu'à ce que le fromage coule sur les bords."],
     en:["Press the sauerkraut out thoroughly in a cloth: its water soaks the bread and ruins the sandwich.","Warm the corned beef by steaming rather than in a pan, so it stays supple and moist.","Build in this order: bread, cheese, beef, sauerkraut, dressing, cheese, bread. Cheese on both sides walls off the moisture.","Butter the outside of the bread, not the pan: the butter melts evenly and browns the crumb without scorching it.","Grill under a weight over medium heat, four minutes a side, until the cheese runs at the edges."]} }
,

{ id:'goetta', c:'na', lat:39.103, lon:-84.512, base:8, prep:60, cook:180, diff:2, tags:['pork','slow','breakfast'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#8f5a3a','#c9924a','#f2dfa8','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Goetta',en:'Goetta'},
  p:{fr:'Cincinnati, Ohio, États-Unis',en:'Cincinnati, Ohio, United States'},
  d:{fr:"Une préparation de porc et d'avoine coupée, moulée puis tranchée et poêlée. Elle a été apportée par les immigrants allemands du Bas-Rhin au XIXe siècle : l'avoine étirait une petite quantité de viande sur plusieurs repas, et Cincinnati en consomme encore des centaines de tonnes par an.",
     en:"A preparation of pork and steel-cut oats, moulded then sliced and pan-fried. It was brought by Lower Rhine German immigrants in the nineteenth century: the oats stretched a little meat across several meals, and Cincinnati still eats hundreds of tonnes a year."},
  i:[['pork_shoulder',700,'g'],['ground_beef',300,'g'],['oats',400,'g'],['onion',2,'pc'],['bay_leaf',3,'pc'],['black_peppercorns',10,'g'],['allspice',5,'g'],['water',2,'l'],['butter',60,'g'],['salt',null,'']],
  s:{fr:["Faites bouillir le porc entier avec les aromates deux heures, jusqu'à ce qu'il se défasse, puis effilochez-le et gardez le bouillon.","Employez de l'avoine coupée en acier, jamais des flocons : les flocons se dissolvent en bouillie et la goetta ne se tranchera pas.","Cuisez l'avoine dans le bouillon une heure et demie à feu très doux, en remuant souvent — elle attache facilement.","Incorporez la viande et laissez cuire encore trente minutes, jusqu'à ce que la cuillère tienne debout dans la masse.","Versez dans des moules à cake et réfrigérez douze heures. Tranchez à un centimètre et poêlez au beurre jusqu'à croûte brune."],
     en:["Boil the whole pork with the aromatics for two hours until it falls apart, then shred it and keep the broth.","Use steel-cut oats, never rolled: rolled oats dissolve into porridge and the goetta will not slice.","Cook the oats in the broth an hour and a half over very low heat, stirring often — they catch easily.","Fold in the meat and cook another thirty minutes, until a spoon stands up in the mass.","Pour into loaf tins and chill twelve hours. Slice at a centimetre and fry in butter to a brown crust."]} },

{ id:'fajitas', c:'na', lat:26.203, lon:-98.230, base:6, prep:240, cook:20, diff:2, tags:['beef','grill','street'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'grill',food:['#8f4a3a','#7fae5a','#e8c46a','#f4f0e6'],garnish:'#7fae6a'},
  n:{fr:'Fajitas',en:'Fajitas'},
  p:{fr:'Vallée du Rio Grande, Texas, États-Unis',en:'Rio Grande Valley, Texas, United States'},
  d:{fr:"De la bavette grillée tranchée fin, servie avec des poivrons et des tortillas de blé. Le mot désigne la hampe de bœuf, morceau que les propriétaires de ranch abandonnaient aux vaqueros mexicains en paiement partiel ; ils en ont fait le plat qui porte aujourd'hui son nom.",
     en:"Grilled skirt steak sliced thin, served with peppers and flour tortillas. The word names the beef skirt, a cut ranch owners left to the Mexican vaqueros as part payment; they made it into the dish that now carries its name."},
  i:[['beef_skirt',1,'kg'],['lime',5,'pc'],['garlic',8,'clove'],['cumin',15,'g'],['chili_powder',15,'g'],['bell_pepper',3,'pc'],['onion',3,'pc'],['flour_tortillas',12,'pc'],['sour_cream',200,'ml'],['avocado',2,'pc'],['sunflower_oil',60,'ml'],['salt',null,'']],
  s:{fr:["Retirez la membrane argentée de la bavette : elle se rétracte à la chaleur et fait boucler la viande.","Faites mariner quatre heures au citron vert, à l'ail et aux épices, sans dépasser six — l'acide finit par rendre la chair farineuse.","Grillez sur une plaque de fonte brûlante, trois minutes par face, en visant une croûte franche et un cœur saignant.","Laissez reposer dix minutes, puis tranchez en travers de la fibre, en biseau, à un demi-centimètre.","Trancher dans le sens de la fibre rend cette pièce immangeable, quelle que soit la cuisson : le sens de coupe fait tout."],
     en:["Remove the silverskin from the skirt: it contracts in the heat and buckles the meat.","Marinate four hours in lime, garlic and spices, and no more than six — the acid eventually turns the flesh mealy.","Grill on a scalding cast-iron plate, three minutes a side, aiming for a good crust and a rare centre.","Rest ten minutes, then slice across the grain on the bias, at half a centimetre.","Slicing with the grain makes this cut inedible however it was cooked: the direction of the cut is everything."]} },

{ id:'queso-fundido', c:'na', lat:29.424, lon:-98.494, base:6, prep:20, cook:20, diff:1, tags:['cheese','comfort','fast'],
  art:{v:'pot',bg:'#33291f',plate:'#f0e4c8',style:'other',food:['#f4f0e6','#8f5a3a','#7fae5a','#e8c46a'],garnish:'#7fae6a'},
  n:{fr:'Queso fundido',en:'Queso fundido'},
  p:{fr:'San Antonio, Texas, États-Unis',en:'San Antonio, Texas, United States'},
  d:{fr:"Du fromage fondu au four avec du chorizo et des poivrons, servi bouillonnant. Il exige un fromage à pâte filée qui fond sans se séparer ; le cheddar, tentant, rend son huile et se fige en caoutchouc dès qu'il refroidit de quelques degrés.",
     en:"Cheese melted in the oven with chorizo and peppers, served bubbling. It needs a pasta filata cheese that melts without splitting; cheddar, tempting as it is, releases its oil and sets to rubber within a few degrees of cooling."},
  i:[['quesillo',500,'g'],['chorizo',250,'g'],['poblano_pepper',2,'pc'],['onion',1,'pc'],['ripe_tomato',200,'g'],['flour_tortillas',12,'pc'],['cilantro',1,'bunch'],['garlic',3,'clove'],['salt',null,'']],
  s:{fr:["Grillez les poblanos à la flamme jusqu'à ce que la peau cloque, enfermez-les dix minutes et pelez-les.","Faites revenir le chorizo émietté et égouttez le gras rendu : laissé dans le plat, il se sépare du fromage et flotte en surface.","Râpez le fromage plutôt que de le couper en dés : râpé, il fond uniformément et sans grumeaux.","Enfournez à 200 °C dix minutes seulement, juste le temps que le fromage file.","Servez immédiatement, dans le plat de cuisson. Refroidi deux minutes, il durcit et ne se rattrape pas."],
     en:["Char the poblanos over a flame until the skin blisters, seal them ten minutes and peel them.","Fry the crumbled chorizo and drain the rendered fat: left in the dish it separates from the cheese and floats on top.","Grate the cheese rather than dicing it: grated, it melts evenly and without lumps.","Bake at 200°C for ten minutes only, just long enough for the cheese to stretch.","Serve at once, in the baking dish. Two minutes cold and it hardens beyond recovery."]} },

{ id:'sopapillas', c:'na', lat:35.687, lon:-105.938, base:8, prep:60, cook:20, diff:2, tags:['sweet','fry','bread'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#e8c46a','#f2dfa8','#c9924a','#f4f0e6'],garnish:'#c9754a'},
  n:{fr:'Sopapillas',en:'Sopapillas'},
  p:{fr:'Santa Fe, Nouveau-Mexique, États-Unis',en:'Santa Fe, New Mexico, United States'},
  d:{fr:"Des coussins de pâte frits, creux à l'intérieur, servis avec du miel. Au Nouveau-Mexique ils accompagnent le plat salé et non le dessert : on en perce un coin et on y verse le miel, ce qui rafraîchit la bouche entre deux bouchées de piment.",
     en:"Fried pillows of dough, hollow inside, served with honey. In New Mexico they accompany the savoury course rather than dessert: a corner is torn open and honey poured in, which cools the mouth between mouthfuls of chilli."},
  i:[['flour',500,'g'],['baking_powder',15,'g'],['lard',60,'g'],['water',280,'ml'],['sugar',20,'g'],['frying_oil',2,'l'],['honey',200,'g'],['salt',null,'']],
  s:{fr:["Pétrissez brièvement et laissez reposer une heure : une pâte trop travaillée reste plate et ne se creuse pas.","Abaissez à cinq millimètres exactement et découpez des triangles ou des carrés, sans repiquer les chutes.","La pâte doit être manipulée le moins possible ; réabaissée, elle perd son pouvoir de gonfler.","Chauffez l'huile à 195 °C, plus chaud que pour la plupart des fritures : c'est la vapeur brutale qui soulève les deux faces.","Immergez la pâte et pressez-la sous l'huile trois secondes avec l'écumoire. Elle gonfle en ballon aussitôt."],
     en:["Knead briefly and rest an hour: an overworked dough stays flat and will not hollow.","Roll to exactly five millimetres and cut triangles or squares, without re-rolling the trimmings.","The dough must be handled as little as possible; re-rolled, it loses its power to puff.","Heat the oil to 195°C, hotter than for most frying: it is the violent steam that lifts the two faces apart.","Submerge the dough and hold it under with a skimmer for three seconds. It balloons at once."]} },

{ id:'pulled-pork-sandwich', c:'na', lat:35.150, lon:-90.049, base:8, prep:720, cook:600, diff:3, tags:['pork','slow','street'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'roll',food:['#8f4a3a','#5a3020','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Sandwich au porc effiloché',en:'Pulled pork sandwich'},
  p:{fr:'Memphis, Tennessee, États-Unis',en:'Memphis, Tennessee, United States'},
  d:{fr:"De l'épaule de porc fumée dix heures, effilochée et servie en sandwich avec du chou. À Memphis, la salade de chou se met dans le pain et non à côté : c'est la règle locale, et servir le chou en accompagnement passe pour une erreur d'étranger.",
     en:"Pork shoulder smoked for ten hours, pulled and served in a bun with slaw. In Memphis the slaw goes in the sandwich, not beside it: that is the local rule, and serving it on the side marks you as an outsider."},
  i:[['pork_shoulder',3,'kg'],['paprika',60,'g'],['brown_sugar',80,'g'],['black_peppercorns',20,'g'],['cayenne_pepper',10,'g'],['cider_vinegar',300,'ml'],['ketchup',200,'g'],['cabbage',600,'g'],['mayonnaise',150,'g'],['bread_roll',8,'pc'],['mustard',40,'g'],['salt',null,'']],
  s:{fr:["Frottez l'épaule du mélange d'épices douze heures à l'avance, et laissez-la à découvert au réfrigérateur.","Fumez à 110 °C au bois de caryer ou de pommier, dix heures, en visant 95 °C à cœur.","Vers 70 °C la température cesse de monter pendant des heures : c'est le stall, dû à l'évaporation, et il faut simplement attendre.","Enveloppez de papier boucher à ce moment-là si vous voulez l'abréger, jamais d'aluminium, qui ramollit l'écorce.","Effilochez à la main en mêlant l'écorce sombre à la chair pâle, arrosez de sauce au vinaigre et servez avec le chou dans le pain."],
     en:["Rub the shoulder with the spice mix twelve hours ahead, and leave it uncovered in the refrigerator.","Smoke at 110°C over hickory or apple wood for ten hours, aiming for 95°C at the centre.","Around 70°C the temperature stops rising for hours: that is the stall, caused by evaporation, and you simply wait it out.","Wrap in butcher's paper at that point if you want to shorten it, never in foil, which softens the bark.","Pull by hand, mixing the dark bark through the pale meat, douse with vinegar sauce and serve with the slaw inside the bun."]} },

{ id:'hoppin-john', c:'na', lat:32.780, lon:-79.935, base:6, prep:720, cook:90, diff:1, tags:['legume','rice','festive'],
  art:{v:'bowl',bg:'#33291f',plate:'#f0e4c8',style:'rice',food:['#8f7a5a','#f4f0e6','#4f6f3a','#e8c46a'],garnish:'#7fae6a'},
  n:{fr:'Hoppin\' John',en:'Hoppin\' John'},
  p:{fr:'Charleston, Caroline du Sud, États-Unis',en:'Charleston, South Carolina, United States'},
  d:{fr:"Du riz aux doliques à œil noir et au porc fumé, mangé le jour de l'an pour la chance. Chaque haricot représente une pièce de monnaie, le chou vert servi à côté représente les billets : la superstition est prise assez au sérieux pour que le plat soit introuvable le 2 janvier.",
     en:"Rice with black-eyed peas and smoked pork, eaten on New Year's Day for luck. Each pea stands for a coin and the greens served alongside for banknotes: the superstition is taken seriously enough that the dish is unfindable on 2 January."},
  i:[['black_eyed_peas',400,'g'],['long_grain_rice',300,'g'],['pork_knuckle',500,'g'],['onion',2,'pc'],['celery',3,'stalk'],['bell_pepper',1,'pc'],['bay_leaf',2,'pc'],['thyme',1,'bunch'],['chili_flakes',5,'g'],['collard_greens',400,'g'],['salt',null,'']],
  s:{fr:["Faites tremper les doliques une nuit : elles cuisent alors en quarante minutes au lieu de deux heures.","Faites d'abord mijoter le jarret fumé une heure, puis ajoutez les haricots trempés dans ce bouillon.","Ne salez qu'à la fin — le porc fumé sale déjà beaucoup, et le sel précoce durcit la peau des haricots.","Mesurez le bouillon restant et cuisez le riz dedans, deux volumes pour un, en le posant sur les haricots sans remuer.","Vingt minutes à couvert, puis laissez reposer dix minutes. Servez avec des chou cavaliers mijotés à côté."],
     en:["Soak the peas overnight: they then cook in forty minutes instead of two hours.","Simmer the ham hock alone for an hour first, then add the soaked peas to that broth.","Salt only at the end — smoked pork is already salty, and early salt hardens the pea skins.","Measure the remaining broth and cook the rice in it, two parts to one, set on the peas without stirring.","Twenty minutes covered, then rest ten minutes. Serve with stewed collard greens alongside."]} },

{ id:'haupia', c:'na', lat:21.307, lon:-157.858, base:8, prep:20, cook:20, diff:1, tags:['sweet','fresh','fruit'],
  art:{v:'plate',bg:'#26485c',plate:'#f4ead4',style:'cake',food:['#f4f0e6','#f0e8d0','#e8dcb8','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Haupia',en:'Haupia'},
  p:{fr:'Honolulu, Hawaï, États-Unis',en:'Honolulu, Hawaii, United States'},
  d:{fr:"Un flan de lait de coco pris à l'arrow-root, découpé en carrés fermes. Il se prenait autrefois à la fécule de pia, une plante hawaïenne aujourd'hui rare ; la maïzena l'a remplacée, mais la texture d'origine était plus translucide et plus ferme.",
     en:"A coconut milk pudding set with arrowroot and cut into firm squares. It was once set with pia starch, a now scarce Hawaiian plant; cornflour has replaced it, but the original texture was more translucent and firmer."},
  i:[['coconut_milk',800,'ml'],['cornstarch',80,'g'],['sugar',150,'g'],['water',200,'ml'],['salt',null,'']],
  s:{fr:["Délayez la fécule dans l'eau froide jusqu'à obtenir un lait parfaitement lisse, sans le moindre grumeau.","Chauffez le lait de coco et le sucre sans bouillir, puis versez la fécule délayée en filet, en fouettant.","Faites bouillir une minute pleine en remuant : la fécule n'atteint son pouvoir épaississant qu'après ébullition franche.","Retirée avant, la préparation paraît prise mais redevient liquide en refroidissant et ne se découpera jamais.","Versez dans un plat carré sur deux centimètres et laissez prendre trois heures au frais. Découpez au couteau mouillé."],
     en:["Slake the starch in cold water to a perfectly smooth milk, without a single lump.","Heat the coconut milk and sugar without boiling, then pour in the slaked starch in a stream, whisking.","Boil for one full minute, stirring: starch reaches its thickening power only after a proper boil.","Taken off before that, the mixture looks set but returns to liquid as it cools and will never cut.","Pour into a square dish two centimetres deep and set three hours in the cold. Cut with a wetted knife."]} }
];
